/* ===== GEMS Web App compatibility layer ===== */
(function(){
  window.__GEMS_BROWSER__ = true;
  window.__GEMS_MEDIA__ = window.__GEMS_MEDIA__ || {};

  const MEDIA_KEY = 'gems-browser-media-v992';
  const STATE_KEY = 'gems-browser-state';
  const readMediaStore = () => {
    try { return JSON.parse(localStorage.getItem(MEDIA_KEY) || '{}'); } catch (_) { return {}; }
  };
  const writeMediaStore = (map) => {
    try { localStorage.setItem(MEDIA_KEY, JSON.stringify(map)); return true; }
    catch (_) { toast?.('画像が多すぎるため保存容量を超えました'); return false; }
  };

  function browserDownload(data, name, type='application/octet-stream'){
    const blob = data instanceof Blob ? data : new Blob([data], {type});
    const a = document.createElement('a');
    a.href = URL.createObjectURL(blob);
    a.download = name;
    document.body.appendChild(a);
    a.click();
    a.remove();
    setTimeout(()=>URL.revokeObjectURL(a.href),1000);
  }

  function pickFile(accept='image/*', capture=''){
    return new Promise(resolve=>{
      const input=document.createElement('input');
      input.type='file'; input.accept=accept;
      if(capture) input.setAttribute('capture',capture);
      input.style.display='none';
      document.body.appendChild(input);
      input.onchange=()=>{const f=input.files?.[0]||null;input.remove();resolve(f)};
      input.click();
    });
  }

  function fileToDataURL(file){
    return new Promise((resolve,reject)=>{
      const r=new FileReader();
      r.onload=()=>resolve(String(r.result||''));
      r.onerror=reject; r.readAsDataURL(file);
    });
  }

  function resizeImageDataURL(dataURL, maxSide=1800, quality=.86){
    return new Promise((resolve,reject)=>{
      const img=new Image();
      img.onload=()=>{
        const scale=Math.min(1,maxSide/Math.max(img.naturalWidth,img.naturalHeight));
        const c=document.createElement('canvas');
        c.width=Math.max(1,Math.round(img.naturalWidth*scale));
        c.height=Math.max(1,Math.round(img.naturalHeight*scale));
        c.getContext('2d').drawImage(img,0,0,c.width,c.height);
        resolve(c.toDataURL('image/jpeg',quality));
      };
      img.onerror=reject; img.src=dataURL;
    });
  }

  async function addBrowserAttachment(file, ctx={}){
    if(!file) return;
    const raw=await fileToDataURL(file);
    const dataURL=await resizeImageDataURL(raw,1800,.86);
    const token=`${Date.now()}_${Math.random().toString(36).slice(2,8)}`;
    const path=`attachments/${token}.jpg`;
    const meta={
      id:`att_${token}`,
      name:file.name || 'GEMS画像.jpg',
      kind:'image',
      path,
      thumbDataURL:dataURL,
      createdAt:new Date().toISOString(),
      source:'browser'
    };
    const media=readMediaStore();
    media[path]=dataURL;
    if(!writeMediaStore(media)) return;
    window.__GEMS_MEDIA__[path]=dataURL;
    window.GEMS_NATIVE_ATTACHMENT(meta,ctx);
    persist();
  }

  async function importJSONFile(){
    const f=await pickFile('.json,application/json');
    if(!f)return;
    try{
      const obj=JSON.parse(await f.text());
      const data=obj?.state || obj;
      if(!data || typeof data!=='object') throw new Error();
      window.GEMS_NATIVE_RESTORE(data);
    }catch(_){ toast('JSONを読み込めませんでした'); }
  }

  async function restoreBackupFile(){
    const f=await pickFile('.json,application/json');
    if(!f)return;
    try{
      const obj=JSON.parse(await f.text());
      const data=obj?.state || obj;
      if(!data || typeof data!=='object') throw new Error();
      if(obj?.media){
        writeMediaStore(obj.media);
        window.__GEMS_MEDIA__={...obj.media};
      }
      window.GEMS_NATIVE_RESTORE(data);
    }catch(_){ toast('バックアップを復元できませんでした'); }
  }

  async function fullBackup(){
    const media=readMediaStore();
    const bundle={format:'GEMS Web Full Backup',version:'9.9.2-web',exportedAt:new Date().toISOString(),state:G.state,media};
    browserDownload(JSON.stringify(bundle,null,2),'GEMS_full_backup.json','application/json');
  }

  function exportFeedback(ext){
    const f=G.state.feedback||[];
    if(ext==='json'){
      browserDownload(JSON.stringify(f,null,2),'GEMS_feedback.json','application/json');
      return;
    }
    const md=f.map(x=>`## ${x.category||'不具合'} / ${x.screen||''}\n\n${x.message||''}\n\n- ${x.createdAt||''}\n`).join('\n');
    browserDownload(md,'GEMS_feedback.md','text/markdown;charset=utf-8');
  }

  function printEventPDF(eventId){
    const e=G.state.events.find(x=>x.id===eventId);
    if(!e){toast('現場が見つかりません');return}
    const old=document.title;
    document.title=`GEMS_${e.name||'event'}`;
    window.print();
    setTimeout(()=>document.title=old,1000);
  }

  async function browserNative(action,params={}){
    try{
      if(action==='persist'){
        localStorage.setItem(STATE_KEY,JSON.stringify(G.state));
        return;
      }
      if(action==='load-media'){
        window.__GEMS_MEDIA__=readMediaStore();
        window.GEMS_NATIVE_MEDIA_MAP(window.__GEMS_MEDIA__);
        return;
      }
      if(action==='pick-image-attachment'){
        await addBrowserAttachment(await pickFile('image/*'),params.ctx||params);
        return;
      }
      if(action==='pick-photo'){
        const f=await pickFile('image/*', params.camera ? 'environment' : '');
        await addBrowserAttachment(f,params.ctx||params);
        return;
      }
      if(action==='capture-image' || action==='capture-profile-icon'){
        const f=await pickFile('image/*','environment');
        await addBrowserAttachment(f,params.ctx||params);
        return;
      }
      if(action==='export-csv'){
        browserDownload(buildCSV(),'GEMS.csv','text/csv;charset=utf-8');
        return;
      }
      if(action==='export-json'){
        browserDownload(JSON.stringify(GEMS_EXPORT_STATE(),null,2),'GEMS.json','application/json');
        return;
      }
      if(action==='import-json'){ await importJSONFile(); return; }
      if(action==='full-backup'){ await fullBackup(); return; }
      if(action==='restore-backup'){ await restoreBackupFile(); return; }
      if(action==='export-feedback-json'){ exportFeedback('json'); return; }
      if(action==='export-feedback-md'){ exportFeedback('md'); return; }
      if(action==='event-pdf'){ printEventPDF(params.eventId); return; }
      if(action==='reset-files'){
        localStorage.removeItem(STATE_KEY);
        localStorage.removeItem(MEDIA_KEY);
        window.__GEMS_MEDIA__={};
        return;
      }
      if(action==='share' || action==='share-cheki' || action==='share-cheki-mosaic'){
        const txt=String(params.text||'');
        if(navigator.share){
          try{
            await navigator.share({title:'GEMS',text:txt});
            return;
          }catch(_){}
        }
        if(txt && navigator.clipboard) await navigator.clipboard.writeText(txt).catch(()=>{});
        toast('共有内容をクリップボードにコピーしました');
        return;
      }
      if(action==='share-chatgpt'){
        const txt=String(params.text||'');
        if(txt && navigator.clipboard) await navigator.clipboard.writeText(txt).catch(()=>{});
        window.open('https://chatgpt.com/','_blank','noopener');
        return;
      }
      if(action==='open-yahoo'){
        window.open('https://map.yahoo.co.jp/','_blank','noopener'); return;
      }
      if(action==='transit-distance'){
        setTimeout(()=>window.GEMS_NATIVE_DISTANCE?.({ok:false,error:'Web版ではYahoo!距離自動取得は未対応です。'}),50);
        return;
      }
      if(action==='google-form-feedback'){
        window.open('https://docs.google.com/forms/','_blank','noopener'); return;
      }
      if(action==='official-schedule-list' || action==='official-schedule-detail' || action==='musicbrainz-sync' || action==='x-avatar-sync'){
        toast('この機能はWeb版では外部サービス連携を無効化しています');
        return;
      }
      if(action==='repair-images'){
        const media=readMediaStore();
        window.__GEMS_MEDIA__=media;
        window.GEMS_NATIVE_MEDIA_MAP(media);
        toast('画像表示を修復しました');
        return;
      }
      if(action==='rotate-attachment'){
        const a=G.state.attachments.find(x=>x.id===params.id);
        if(!a) return;
        const src=mediaURL(a.path);
        if(!src) return toast('画像を読み込めませんでした');
        const img=new Image();
        img.onload=()=>{
          const c=document.createElement('canvas');
          c.width=img.naturalHeight; c.height=img.naturalWidth;
          const x=c.getContext('2d');
          x.translate(c.width,0); x.rotate(Math.PI/2); x.drawImage(img,0,0);
          const data=c.toDataURL('image/jpeg',.9);
          const media=readMediaStore(); media[a.path]=data; writeMediaStore(media);
          a.thumbDataURL=data; window.__GEMS_MEDIA__[a.path]=data;
          persist(); renderAll(); window.GEMS_NATIVE_ROTATE_DONE?.({id:a.id,path:a.path,thumbDataURL:data});
        };
        img.src=src; return;
      }
      if(action==='edit-attachment-crop' || action==='capture-crop-image'){
        const a=G.state.attachments.find(x=>x.id===params.id);
        if(a && mediaURL(a.path)) window.GEMS_NATIVE_CROP_START({dataURL:mediaURL(a.path)},params.ctx||params);
        else toast('画像を読み込めませんでした');
        return;
      }
      if(action==='save-crop'){
        const data=window.GEMS_GET_PENDING_CROP?.();
        const a=G.state.attachments.find(x=>x.id===params.id);
        if(data && a){
          const media=readMediaStore(); media[a.path]=data; writeMediaStore(media);
          a.thumbDataURL=data; window.__GEMS_MEDIA__[a.path]=data; persist(); renderAll();
        }
        window.GEMS_NATIVE_CROP_DONE?.(a||{});
        return;
      }
      if(action==='gems-scan-capture' || action==='gems-scan-save'){
        toast('GEMS SCANはWeb版では通常の画像選択をご利用ください'); return;
      }
      if(action==='cheki-mosaic-start'){
        const a=G.state.attachments.find(x=>x.id===params.id);
        if(a && mediaURL(a.path)) window.GEMS_NATIVE_MOSAIC_START({dataURL:mediaURL(a.path)},params);
        else toast('画像を読み込めませんでした');
        return;
      }
      toast(`Web版では「${action}」を実行できません`);
    }catch(err){
      console.error(err);
      toast('Web版での処理に失敗しました');
    }
  }

  window.__GEMS_BROWSER_NATIVE__ = browserNative;
  window.__GEMS_BROWSER_READY__ = true;

  // Replace the original browserNative function before the app's init is called.
  window.browserNative = browserNative;
  const originalNative = window.native;
  // The original native() is scoped inside the app closure, so the public bridge
  // is provided by patching the global location fallback below.
  const oldHref = window.location.href;
})();

function browserNative(action,params){return window.__GEMS_BROWSER_NATIVE__(action,params)}

function downloadText(text,name,type){const b=new Blob([text],{type}),a=document.createElement('a');a.href=URL.createObjectURL(b);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),500)}
function persist(){native('persist')}

