function starterState(){
 const s=sampleMasterState();
 s.venues=[];s.songs=[];s.templates=[];s.tags=[];s.events=[];s.travels=[];s.attachments=[];s.trash=[];
 s.settings=defaultSettings();
 return s;
}
function normalizeState(raw){
 const s=raw&&typeof raw==='object'?raw:blankState();s.version=4;
 const def=defaultSettings();s.settings={...def,...(s.settings||{}),features:{...def.features,...(s.settings?.features||{})},budgets:{months:{},years:{},...(s.settings?.budgets||{})},navImages:{...(s.settings?.navImages||{})},actionImages:{...(s.settings?.actionImages||{})},homeImages:[...(s.settings?.homeImages||[])]};
 ['groups','members','memberColors','venues','songs','templates','tags','events','travels','attachments','trash'].forEach(k=>{if(!Array.isArray(s[k]))s[k]=[]});
 if(!s.memberColors.length)s.memberColors=clone(DEFAULT_MEMBER_COLORS);DEFAULT_MEMBER_COLORS.forEach(c=>{if(!s.memberColors.some(x=>x.id===c.id||x.name===c.name))s.memberColors.push(clone(c))});
 s.groups=s.groups.map(g=>({...g,active:g.active!==false,system:g.system===true||BUILTIN_GROUP_NAMES.includes(g.name)}));
 const colorByHex=h=>s.memberColors.find(c=>String(c.color||'').toLowerCase()===String(h||'').toLowerCase());
 s.members=s.members.map(m=>{let memberColorId=m.memberColorId||'';if(!memberColorId&&m.memberColor)memberColorId=colorByHex(m.memberColor)?.id||'';return{...m,active:m.active!==false,favorite:!!m.favorite,birthday:m.birthday||'',memberColorId,memberColor:m.memberColor||'',memberships:Array.isArray(m.memberships)?m.memberships:[],notes:m.notes||''}});
 s.events=s.events.map(e=>({...e,groupIds:Array.isArray(e.groupIds)?e.groupIds:[],benefits:(e.benefits||[]).map(b=>({...b,note:b.note||'',attachments:Array.isArray(b.attachments)?b.attachments:[]})),expenses:e.expenses||[],tags:e.tags||[],attachments:e.attachments||[],setlist:e.setlist||[]}));
 s.attachments=s.attachments.map(a=>({...a,thumbDataURL:a.thumbDataURL||''}));
 s.travels=s.travels.map(t=>({...t,eventIds:Array.isArray(t.eventIds)?t.eventIds:[],attachments:t.attachments||[],actualNights:Number.isFinite(Number(t.actualNights))?Number(t.actualNights):Number(t.overnights)||0,recognizedNights:Number(t.recognizedNights)||0}));
 return s
}

function memberColorById(id){return G.state.memberColors.find(c=>c.id===id)}
function memberColorFor(m){return memberColorById(m?.memberColorId)||null}
function memberColorOptions(selected='',includeRetired=true){return G.state.memberColors.filter(c=>includeRetired||c.active!==false).map(c=>`<option value="${c.id}" ${c.id===selected?'selected':''}>${esc(c.name)}${c.active===false?'（廃止）':''}</option>`).join('')}
function dateDiffDays(a,b){if(!a||!b)return 0;const x=new Date(`${a}T12:00:00`),y=new Date(`${b}T12:00:00`);return Math.max(0,Math.round((y-x)/86400000))}
function travelDistanceInfo(km){km=Number(km)||0;if(km<150)return{distanceAdd:0,maxNights:0,label:'150km未満'};if(km<300)return{distanceAdd:.25,maxNights:1,label:'150〜300km未満'};if(km<500)return{distanceAdd:.5,maxNights:2,label:'300〜500km未満'};if(km<800)return{distanceAdd:.75,maxNights:3,label:'500〜800km未満'};return{distanceAdd:1,maxNights:4,label:'800km以上'}}
function travelNightsInfo(t){const actual=dateDiffDays(t.startDate,t.endDate),rule=travelDistanceInfo(t.distanceKm),recognized=Math.min(actual,rule.maxNights);return{actual,recognized,excluded:Math.max(0,actual-recognized),...rule,lodgingAdd:round2(recognized*.5),total:round2(rule.distanceAdd+recognized*.5)}}
function chekiBenefits(events){const rows=[];(events||[]).forEach(e=>(e.benefits||[]).forEach(b=>{if((b.kind||'cheki')==='bingo'||Number(b.count)<=0)return;rows.push({event:e,benefit:b,count:Number(b.count)||0,groupId:resolveBenefitGroup(b,e),memberId:b.memberId||''})}));return rows}
function memberRelevantEvents(memberId){return activeEvents().filter(e=>(e.benefits||[]).some(b=>b.memberId===memberId))}
function groupRelevantEvents(groupId){return activeEvents().filter(e=>(e.groupIds||[]).includes(groupId)||(e.benefits||[]).some(b=>resolveBenefitGroup(b,e)===groupId))}
function profileFirstLast(events){const a=events.filter(e=>e.date).sort((x,y)=>x.date.localeCompare(y.date));return{first:a[0]?.date||'',last:a[a.length-1]?.date||''}}
function scheduleShareRangeLabel(a){if(G.analysisPeriod==='month')return `${$('analysisMonth').value} 月間`;if(['year','firstHalf','secondHalf'].includes(G.analysisPeriod))return `${$('analysisYear').value}年`;return '通算'}
function groupById(id){return G.state.groups.find(x=>x.id===id)}
function memberById(id){return G.state.members.find(x=>x.id===id)}
function venueById(id){return G.state.venues.find(x=>x.id===id)}
function songById(id){return G.state.songs.find(x=>x.id===id)}
function typeById(id){return TYPES.find(x=>x.id===id)||{id,name:id,count:0,base:0}}
function memberGroups(memberId,date=''){const m=memberById(memberId);if(!m)return[];return (m.memberships||[]).filter(mm=>(!mm.from||!date||date>=mm.from)&&(!mm.to||!date||date<=mm.to)).map(mm=>mm.groupId)}
function resolveBenefitGroup(b,e){if(b.groupId)return b.groupId;const gs=memberGroups(b.memberId,e.date);return gs.find(id=>e.groupIds?.includes(id))||gs[0]||e.groupIds?.[0]||''}
function eventCount(e){const t=typeById(e.type);if(e.type==='schedule'||e.type==='merch')return 0;if(e.type==='other')return Number(e.otherCount??1)||0;return Number(t.count)||0}
function benefitRate(e,b){if(e.type==='online_cheki')return .4;if(e.type==='online_bingo'||b.kind==='bingo')return .1;return .2}
function eventWorkdays(e){
 if(!e||e.deletedAt)return 0;
 let d=0;
 if(e.type==='other')d=Number(e.otherDays)||0;else d=Number(typeById(e.type).base)||0;
 const benefits=e.benefits||[];
 if(['special','handover'].includes(e.type)&&benefits.some(b=>b.case))d+=.4;
 d+=sum(benefits,b=>Number(b.count||0)*benefitRate(e,b));
 return round2(d);
}
function groupEventAlloc(e){
 const out={};const groups=(e.groupIds||[]).filter(Boolean);const benefits=e.benefits||[];
 const add=(g,n)=>{if(!g||!n)return;out[g]=round2((out[g]||0)+n)};
 let base=0;
 if(e.type==='other')base=Number(e.otherDays)||0;else base=Number(typeById(e.type).base)||0;
 if(base&&groups.length){const each=round2(base/groups.length);groups.forEach(g=>add(g,each))}
 if(['special','handover'].includes(e.type)&&benefits.some(b=>b.case)){
   const bg=[...new Set(benefits.map(b=>resolveBenefitGroup(b,e)).filter(Boolean))];const targets=bg.length?bg:groups;
   if(targets.length){const each=round2(.4/targets.length);targets.forEach(g=>add(g,each))}
 }
 benefits.forEach(b=>add(resolveBenefitGroup(b,e),round2((Number(b.count)||0)*benefitRate(e,b))));
 if(!groups.length&&Object.keys(out).length===0&&base)add('__unassigned',round2(base));
 return out;
}
function travelWorkdays(t){return travelNightsInfo(t).total}
function travelEventAlloc(t){
 const linked=(t.eventIds||[]).map(id=>G.state.events.find(e=>e.id===id&&!e.deletedAt)).filter(Boolean);const total=sum(linked,eventWorkdays);const out={};
 linked.forEach(e=>{out[e.id]=total?round2(travelWorkdays(t)*eventWorkdays(e)/total):0});return out
}
function travelGroupAlloc(t){
 const evAlloc=travelEventAlloc(t),out={};
 Object.entries(evAlloc).forEach(([eid,td])=>{const e=G.state.events.find(x=>x.id===eid);if(!e||!td)return;const ga=groupEventAlloc(e),den=sum(Object.values(ga));if(!den)return;Object.entries(ga).forEach(([g,d])=>{if(g==='__unassigned')return;out[g]=round2((out[g]||0)+round2(td*d/den))})});
 return out;
}
function eventTravelShare(e){if(!e.travelId)return 0;const t=G.state.travels.find(x=>x.id===e.travelId&&!x.deletedAt);return t?travelEventAlloc(t)[e.id]||0:0}
function eventTotalDays(e){return round2(eventWorkdays(e)+eventTravelShare(e))}
function expenseTotal(e){if(e?.type==='schedule')return 0;return sum(e.expenses||[],x=>x.amount)}
function travelExpenseTotal(t){return (Number(t.transportCost)||0)+(Number(t.lodgingCost)||0)}
function eventDateInRange(e,start,end){const d=e.date||e.scheduleAt?.slice(0,10);return d&&(!start||d>=start)&&(!end||d<=end)}
function travelInRange(t,start,end){return (!start||t.startDate>=start)&&(!end||t.startDate<=end)}
function statusIncluded(e,mode='all'){if(mode==='actual')return e.status==='実績';if(mode==='confirmed')return ['実績','確定予定'].includes(e.status);return true}
function periodRange(kind,key){
 if(kind==='all')return{start:'',end:''};
 if(kind==='month'){const [y,m]=String(key||`${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,'0')}`).split('-').map(Number);const last=new Date(y,m,0).getDate();return{start:`${y}-${String(m).padStart(2,'0')}-01`,end:`${y}-${String(m).padStart(2,'0')}-${last}`}}
 const y=Number(key)||now.getFullYear();if(kind==='year')return{start:`${y}-01-01`,end:`${y}-12-31`};if(kind==='firstHalf')return{start:`${y}-01-01`,end:`${y}-06-30`};return{start:`${y}-07-01`,end:`${y}-12-31`}
}
function analysisData(kind,key,scope='all'){
 const {start,end}=periodRange(kind,key);const events=G.state.events.filter(e=>!e.deletedAt&&e.type!=='schedule'&&eventDateInRange(e,start,end)&&statusIncluded(e,scope));const eligibleIds=new Set(events.map(e=>e.id));const travels=G.state.travels.filter(t=>!t.deletedAt&&travelInRange(t,start,end)&&(scope==='all'||(t.eventIds||[]).some(id=>eligibleIds.has(id))||(scope==='actual'&&(!t.eventIds||!t.eventIds.length)&&t.endDate<=todayISO())));
 const eventDays=sum(events,eventWorkdays),travelDays=sum(travels,travelWorkdays),eventCountTotal=sum(events,eventCount),eventExpenses=sum(events,expenseTotal),travelExpenses=sum(travels,travelExpenseTotal);
 const groups={};events.forEach(e=>Object.entries(groupEventAlloc(e)).forEach(([g,d])=>{if(g==='__unassigned')return;groups[g]??={event:0,travel:0};groups[g].event=round2(groups[g].event+d)}));travels.forEach(t=>Object.entries(travelGroupAlloc(t)).forEach(([g,d])=>{groups[g]??={event:0,travel:0};groups[g].travel=round2(groups[g].travel+d)}));
 const expenseCats={};events.forEach(e=>(e.expenses||[]).forEach(x=>expenseCats[x.category||'その他出費']=(expenseCats[x.category||'その他出費']||0)+(Number(x.amount)||0)));if(travelExpenses){expenseCats['交通費']=(expenseCats['交通費']||0)+sum(travels,t=>t.transportCost);expenseCats['宿泊費']=(expenseCats['宿泊費']||0)+sum(travels,t=>t.lodgingCost)}
 const songCounts={};events.forEach(e=>(e.setlist||[]).forEach(r=>{const title=songById(r.songId)?.title||r.songTitle||'';if(title)songCounts[title]=(songCounts[title]||0)+1}));
 const chekiGroups={},chekiMembers={};chekiBenefits(events).forEach(r=>{if(r.groupId)chekiGroups[r.groupId]=(chekiGroups[r.groupId]||0)+r.count;if(r.memberId)chekiMembers[r.memberId]=(chekiMembers[r.memberId]||0)+r.count});
 return{start,end,events,travels,eventDays:round2(eventDays),travelDays:round2(travelDays),totalDays:round2(eventDays+travelDays),eventCount:round2(eventCountTotal),eventExpenses,travelExpenses,totalExpenses:eventExpenses+travelExpenses,groups,expenseCats,songCounts,chekiGroups,chekiMembers,chekiTotal:sum(Object.values(chekiMembers))}
}
function scheduleExpired(e){if(e.type!=='schedule')return false;const at=e.scheduleAt||`${e.date}T23:59`;return new Date(at)<new Date()}
function activeEvents(){return G.state.events.filter(e=>!e.deletedAt)}
function activeTravels(){return G.state.travels.filter(t=>!t.deletedAt)}
function activeSchedules(){return activeEvents().filter(e=>e.type==='schedule'&&!scheduleExpired(e))}
function stationSuggestions(){return [...new Set([G.state.settings.homeStation,...G.state.venues.map(v=>v.station),...G.state.travels.flatMap(t=>[t.originStation,t.destinationStation])].filter(Boolean))].sort((a,b)=>a.localeCompare(b,'ja'))}
function attachmentById(id){return G.state.attachments.find(a=>a.id===id)}

function applyTheme(){
 const preset=THEME_PRESETS.find(x=>x.id===G.state.settings.themePreset)||THEME_PRESETS[1];const custom=G.state.settings.customThemeColor;const color=custom||preset.color;document.documentElement.style.setProperty('--primary',color);document.documentElement.style.setProperty('--primary-soft',custom?hexMix(color,'#ffffff',.78):preset.soft);document.documentElement.style.setProperty('--primary-ink',custom?contrastInk(color):preset.ink);
 document.body.classList.remove('auto-dark');document.body.style.colorScheme='';if(G.state.settings.appearance==='dark'){document.body.classList.add('auto-dark');document.body.style.colorScheme='dark'}else if(G.state.settings.appearance==='auto')document.body.classList.add('auto-dark');else document.body.style.colorScheme='light';
}
function hexMix(a,b,t){const p=x=>parseInt(x,16);a=a.replace('#','').padEnd(6,'0');b=b.replace('#','').padEnd(6,'f');return '#'+[0,2,4].map(i=>Math.round(p(a.slice(i,i+2))*(1-t)+p(b.slice(i,i+2))*t).toString(16).padStart(2,'0')).join('')}
function contrastInk(c){c=c.replace('#','');const r=parseInt(c.slice(0,2),16),g=parseInt(c.slice(2,4),16),b=parseInt(c.slice(4,6),16);return(r*.299+g*.587+b*.114)>170?'#17202a':'#ffffff'}
function themePresetFromColor(c){return THEME_PRESETS.find(x=>x.color.toLowerCase()===String(c).toLowerCase())?.id||''}

function toast(msg){const t=$('toast');t.textContent=msg;t.classList.add('show');clearTimeout(toast._t);toast._t=setTimeout(()=>t.classList.remove('show'),1800)}
function showView(name){qsa('.view').forEach(v=>v.classList.toggle('active',v.dataset.view===name));const navName=name==='travel'?'events':name;qsa('.nav-btn').forEach(b=>b.classList.toggle('active',b.dataset.nav===navName));if(name==='home')renderHome();if(name==='events')renderEvents();if(name==='travel')renderTravels();if(name==='digest')renderDigest();if(name==='analysis')renderAnalysis();if(name==='settings')renderSettings();window.scrollTo({top:0,behavior:'instant'})}
function setModal(html){$('modal').innerHTML=html;$('modalBackdrop').classList.remove('hidden');$('modal').scrollTop=0}
function closeModal(){$('modalBackdrop').classList.add('hidden');$('modal').innerHTML='';G.editingEventId=null;G.editingTravelId=null;G.formSeedEvent=null;G.formSeedTravel=null}
function confirmModal(title,text,onYes,{danger=false,requireWord=''}={}){setModal(`<div class="modal-head"><h2>${esc(title)}</h2><button class="close-btn" data-close>×</button></div><div class="panel flat"><p class="detail-text">${esc(text)}</p>${requireWord?`<label class="field"><span>確認のため「${esc(requireWord)}」と入力</span><input id="confirmWord"></label>`:''}</div><div class="modal-foot"><button class="btn" data-close>キャンセル</button><button class="btn ${danger?'danger':'primary'}" id="confirmYes">実行</button></div>`);$('confirmYes').onclick=()=>{if(requireWord&&$('confirmWord').value!==requireWord){toast('確認文字が一致しません');return}onYes();closeModal()}}

function attachmentByPath(path){return G.state.attachments.find(a=>a.path===path)}
function mediaURL(path){if(!path)return'';const a=attachmentByPath(path);return a?.thumbDataURL||window.__GEMS_MEDIA__?.[path]||''}
function mediaImg(path,alt=''){const src=mediaURL(path);return src?`<img src="${esc(src)}" alt="${esc(alt)}">`:''}
function renderNavImages(){NAVS.forEach(([id,,icon])=>{const holder=document.querySelector(`[data-nav-icon="${id}"]`);const aid=G.state.settings.navImages?.[id],a=attachmentById(aid),img=a?mediaImg(a.path):'';holder.innerHTML=img||icon});const qa=attachmentById(G.state.settings.actionImages?.quickAdd),img=qa?mediaImg(qa.path):'';if($('quickAddVisual'))$('quickAddVisual').innerHTML=img||'＋'}
function renderHero(){
 const ids=G.state.settings.homeImages||[],track=$('heroTrack'),dots=$('heroDots');
 if(!ids.length){track.innerHTML=`<div class="hero-slide"><div class="hero-empty"><strong>GEMS</strong><span>General Event Management System</span></div></div>`;dots.innerHTML='';return}
 const items=ids.map(id=>attachmentById(id)).filter(Boolean).map(a=>({a,src:mediaURL(a.path)})).filter(x=>x.src);
 if(!items.length){track.innerHTML=`<div class="hero-slide"><div class="hero-empty"><strong>画像を再読み込み中</strong><span>表示されない場合は設定から画像を選び直してください</span></div></div>`;dots.innerHTML='';return}
 track.innerHTML=items.map(({a,src})=>`<div class="hero-slide"><img src="${esc(src)}" alt="${esc(a.name||'')}"></div>`).join('');dots.innerHTML=items.map(()=>'<i class="hero-dot"></i>').join('');
}
function nextRelevantEvents(){
 const today=todayISO();return activeEvents().filter(e=>{const d=(e.scheduleAt||e.date||'').slice(0,10);return d>=today&&(e.type!=='schedule'||!scheduleExpired(e))}).sort((a,b)=>dateTimeValue(a).localeCompare(dateTimeValue(b))).slice(0,5)
}
function renderHome(){
 renderHero();renderNavImages();const hasEvents=activeEvents().length>0;if($('gettingStartedPanel'))$('gettingStartedPanel').classList.toggle('hidden',hasEvents);const mKey=`${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,'0')}`,a=analysisData('month',mKey),next=activeEvents().filter(e=>e.type!=='schedule'&&!e.deletedAt&&e.date>=todayISO()).sort((x,y)=>x.date.localeCompare(y.date))[0];
 const nextDays=next?daysUntil(next.date):null;
 $('homeKpis').innerHTML=`
 <div class="kpi primary"><div class="label">次の現場</div><strong>${nextDays==null?'—':`あと${nextDays}日`}</strong><small>${next?esc(next.name):'予定なし'}</small></div>
 <div class="kpi"><div class="label">今月の現場</div><strong>${a.eventCount.toFixed(0)}<small> 件</small></strong><small>${now.getFullYear()}年${now.getMonth()+1}月</small></div>
 <div class="kpi"><div class="label">今月の総Carat</div><strong>${a.totalDays.toFixed(2)}</strong><small>現場 ${a.eventDays.toFixed(2)} / 遠征 ${a.travelDays.toFixed(2)}</small></div>
 <div class="kpi"><div class="label">今月の支出</div><strong style="font-size:20px">${yen(a.totalExpenses)}</strong><small>現場＋遠征</small></div>`;
 const actions=nextRelevantEvents();$('nextActions').innerHTML=actions.length?actions.map(e=>{const d=(e.scheduleAt||e.date).slice(0,10),du=daysUntil(d);return `<div class="action-row" data-event-open="${e.id}"><div class="action-date">${esc(fmtDateShort(d))}<small>${e.type==='schedule'?(e.scheduleAt?.slice(11,16)||''):''}</small></div><div><div class="action-name">${e.important?'★ ':''}${esc(e.name)}</div><div class="action-meta">${esc(e.type==='schedule'?(e.scheduleKind||'スケジュール'):typeById(e.type).name)}</div></div><div class="countdown">${`あと${du}日`}</div></div>`}).join(''):'<div class="empty">直近の予定はありません</div>';
 const imp=activeEvents().filter(e=>e.important&&e.type!=='schedule'&&e.date>=todayISO()).sort((a,b)=>a.date.localeCompare(b.date)).slice(0,8);$('importantPanel').classList.toggle('hidden',!imp.length);$('importantStrip').innerHTML=imp.map(e=>`<div class="important-card" data-event-open="${e.id}"><div class="event-date">${esc(fmtDate(e.date))}</div><b><span class="star">★</span>${esc(e.name)}</b><div class="event-meta">${esc(eventGroupNames(e))}</div></div>`).join('');
 const rec=activeEvents().filter(e=>e.type!=='schedule'&&e.date<=todayISO()).sort((a,b)=>b.date.localeCompare(a.date)).slice(0,5);$('recentEvents').innerHTML=rec.length?rec.map(eventCardHTML).join(''):'<div class="empty">実績はまだありません</div>';
 bindEventOpeners();
}
function eventGroupNames(e){return (e.groupIds||[]).map(id=>groupById(id)?.name).filter(Boolean).join(' / ')||'グループ未設定'}
function eventVenue(e){return venueById(e.venueId)?.name||e.venueText||''}
function eventPhotoAttachments(e){return (e.attachments||[]).map(attachmentById).filter(Boolean).filter(a=>!!mediaURL(a.path))}
function eventCardPhotoHTML(e){const imgs=eventPhotoAttachments(e).slice(0,4);if(!imgs.length)return'';return `<div class="event-card-bg">${imgs.map((a,i)=>`<img src="${esc(mediaURL(a.path))}" alt="" style="animation-delay:${i*4}s">`).join('')}</div>`}
function eventCardHTML(e){
 const expired=scheduleExpired(e),days=eventWorkdays(e),travel=eventTravelShare(e),alloc=groupEventAlloc(e),photos=eventPhotoAttachments(e);return `<div class="event-card ${photos.length?'has-photo':''}">${eventCardPhotoHTML(e)}
 <div class="event-top"><div><div class="event-date">${esc(e.type==='schedule'?(e.scheduleAt?e.scheduleAt.replace('T',' '):fmtDate(e.date)):fmtDate(e.date))} ${e.important?'★':''}</div><h3>${esc(e.name)}</h3><div class="event-meta">${esc(e.type==='schedule'?(e.scheduleKind||'スケジュール'):typeById(e.type).name)}${e.status?` ・ ${esc(e.status)}`:''}${eventVenue(e)?`<br>${esc(eventVenue(e))}`:''}</div></div><div class="event-day">${e.type==='schedule'?'—':days.toFixed(2)}<small>${e.type==='schedule'?(expired?'終了':'予定'):travel?`+遠征 ${travel.toFixed(2)}`:'GEM Carat'}</small></div></div>
 ${Object.keys(alloc).length?`<div class="alloc-row">${Object.entries(alloc).filter(([g])=>g!=='__unassigned').map(([g,d])=>`<span class="badge primary">${esc(groupById(g)?.name||'不明')} ${d.toFixed(2)}</span>`).join('')}</div>`:''}
 <div class="event-actions"><button class="btn small" data-event-open="${e.id}">開く</button><button class="btn small" data-event-edit="${e.id}">編集</button><button class="btn small danger" data-event-delete="${e.id}">削除</button></div></div>`
}
function populateEventFilters(){
 const fg=$('filterGroup'),ft=$('filterType'),fs=$('filterStatus'),fTag=$('filterTag');
 const gval=fg.value,tval=ft.value,sval=fs.value,tagval=fTag.value;
 fg.innerHTML='<option value="">全グループ</option>'+G.state.groups.filter(g=>g.active!==false).map(g=>`<option value="${g.id}">${esc(g.name)}</option>`).join('');
 ft.innerHTML='<option value="">全種別</option>'+TYPES.map(t=>`<option value="${t.id}">${esc(t.name)}</option>`).join('');fs.innerHTML='<option value="">全ステータス</option>'+STATUS.map(x=>`<option>${x}</option>`).join('');fTag.innerHTML='<option value="">全タグ</option>'+G.state.tags.map(x=>`<option>${esc(x)}</option>`).join('');fg.value=gval;ft.value=tval;fs.value=sval;fTag.value=tagval;
}
function filteredEvents(){
 const q=($('eventSearch')?.value||'').trim().toLowerCase(),g=$('filterGroup')?.value||'',t=$('filterType')?.value||'',st=$('filterStatus')?.value||'',tag=$('filterTag')?.value||'',imp=$('filterImportant')?.checked;
 return activeEvents().filter(e=>{
   if(e.type==='schedule'&&scheduleExpired(e)&&!G.state.settings.showEndedSchedules)return false;
   if(g&&!e.groupIds?.includes(g))return false;if(t&&e.type!==t)return false;if(st&&e.status!==st)return false;if(tag&&!e.tags?.includes(tag))return false;if(imp&&!e.important)return false;
   if(q){const members=(e.benefits||[]).map(b=>memberById(b.memberId)?.name).join(' ');const hay=[e.name,eventVenue(e),eventGroupNames(e),(e.tags||[]).join(' '),members,e.notes||''].join(' ').toLowerCase();if(!hay.includes(q))return false}return true
 }).sort((a,b)=>dateTimeValue(b).localeCompare(dateTimeValue(a)))
}
function renderEvents(){
 populateEventFilters();$('eventListMode').classList.toggle('hidden',G.eventMode!=='list');$('calendarMode').classList.toggle('hidden',G.eventMode!=='calendar');
 qsa('[data-event-sub]').forEach(b=>b.classList.toggle('active-mode',(b.dataset.eventSub==='calendar'&&G.eventMode==='calendar')||(b.dataset.eventSub==='list'&&G.eventMode==='list'&&!G.scheduleOnly)||(b.dataset.eventSub==='schedule'&&G.scheduleOnly)));
 if(G.eventMode==='list'){
   let rows=filteredEvents();if(G.scheduleOnly)rows=rows.filter(e=>e.type==='schedule');else rows=rows.filter(e=>e.type!=='schedule');
   $('eventList').innerHTML=rows.map(eventCardHTML).join('')||(activeEvents().length?'<div class="empty-state"><b>条件に一致するデータがありません</b><span>検索条件を変えてみてください。</span></div>':'<div class="empty-state"><div class="empty-icon">＋</div><b>まだ現場が登録されていません</b><span>ライブ、特典会、配信、申込締切などをここから登録します。</span><button class="btn primary" id="emptyAddEventBtn">最初の現場を登録する</button></div>');bindEventActions();if($('emptyAddEventBtn'))$('emptyAddEventBtn').onclick=()=>openEventForm()
 }else renderCalendar()
}
function bindEventActions(){qsa('[data-event-open]').forEach(x=>x.onclick=()=>openEventDetail(x.dataset.eventOpen));qsa('[data-event-edit]').forEach(x=>x.onclick=()=>openEventForm(x.dataset.eventEdit));qsa('[data-event-delete]').forEach(x=>x.onclick=()=>deleteEvent(x.dataset.eventDelete))}
function bindEventOpeners(){qsa('[data-event-open]').forEach(x=>x.onclick=()=>openEventDetail(x.dataset.eventOpen))}
function renderCalendar(){
 const y=G.calDate.getFullYear(),m=G.calDate.getMonth();$('calTitle').textContent=`${y}年 ${m+1}月`;const first=new Date(y,m,1),last=new Date(y,m+1,0),start=new Date(y,m,1-first.getDay());let html=['日','月','火','水','木','金','土'].map(x=>`<div class="weekday">${x}</div>`).join('');
 for(let i=0;i<42;i++){const d=new Date(start);d.setDate(start.getDate()+i);const ds=isoDate(d),dayEvents=activeEvents().filter(e=>(e.scheduleAt||e.date||'').slice(0,10)===ds&&(!scheduleExpired(e)||G.state.settings.showEndedSchedules)),travelHere=activeTravels().some(t=>ds>=t.startDate&&ds<=t.endDate),classes=['daycell',d.getMonth()!==m?'out':'',ds===todayISO()?'today':''].filter(Boolean).join(' ');html+=`<div class="${classes}" data-cal-day="${ds}"><div class="daynum">${d.getDate()}</div>${dayEvents.slice(0,4).map(e=>`<div class="daydot ${e.type==='schedule'?'schedule':''} ${e.important?'important':''}"></div>`).join('')}${travelHere?'<div class="daydot travel"></div>':''}</div>`}
 $('calendarGrid').innerHTML=html;qsa('[data-cal-day]').forEach(c=>c.onclick=()=>renderCalendarDay(c.dataset.calDay));renderCalendarDay(todayISO())
}
function renderCalendarDay(ds){const list=activeEvents().filter(e=>(e.scheduleAt||e.date||'').slice(0,10)===ds&&(!scheduleExpired(e)||G.state.settings.showEndedSchedules)),trs=activeTravels().filter(t=>ds>=t.startDate&&ds<=t.endDate);$('calendarDayList').innerHTML=`<div class="event-date">${esc(fmtDate(ds))}</div>`+(list.length?list.map(eventCardHTML).join(''):'')+(trs.length?trs.map(t=>`<div class="event-card"><div class="event-top"><div><div class="event-date">遠征</div><h3>${esc(t.name)}</h3><div class="event-meta">${esc(t.originStation||'')} → ${esc(t.destinationStation||'')}</div></div><div class="event-day">${travelWorkdays(t).toFixed(2)}<small>遠征Carat</small></div></div><div class="event-actions"><button class="btn small" data-cal-travel-open="${t.id}">開く</button></div></div>`).join(''):'')+(!list.length&&!trs.length?'<div class="empty">この日の登録はありません</div>':'');bindEventActions();qsa('[data-cal-travel-open]').forEach(b=>b.onclick=()=>openTravelDetail(b.dataset.calTravelOpen))}
function groupCheckHTML(selected=[]){return `<div class="chips" id="eventGroupChecks">${G.state.groups.filter(g=>g.active!==false).map(g=>`<label class="chip ${selected.includes(g.id)?'active':''}"><input type="checkbox" value="${g.id}" ${selected.includes(g.id)?'checked':''} style="display:none">${esc(g.name)}</label>`).join('')}</div>`}
function groupOptions(selected='',blank='グループ'){return `<option value="">${esc(blank)}</option>`+G.state.groups.filter(g=>g.active!==false).map(g=>`<option value="${g.id}" ${g.id===selected?'selected':''}>${esc(g.name)}</option>`).join('')}
function memberOptions(selected='',groupId='',date=''){const ms=G.state.members.filter(m=>(m.active!==false||m.id===selected||!!date&&memberGroups(m.id,date).length)&&(!groupId||memberGroups(m.id,date).includes(groupId)));return `<option value="">メンバー</option>`+ms.map(m=>`<option value="${m.id}" ${m.id===selected?'selected':''}>${esc(m.name)}${m.active===false?'（活動終了）':''}</option>`).join('')}
function benefitRowHTML(b={}){
 const id=b.id||uid('b'),atts=b.attachments||[];const detail=(G.state.settings.features.notes||G.state.settings.features.attachments)?`<details class="benefit-extra"><summary>チェキ詳細（任意）${atts.length?` ・ 画像${atts.length}枚`:''}</summary>${G.state.settings.features.notes?`<label class="field" style="margin-top:7px"><span>この明細のメモ</span><textarea data-ben-note placeholder="会話内容・エピソード等。空欄でOK。">${esc(b.note||'')}</textarea></label>`:''}${G.state.settings.features.attachments?`<input type="hidden" data-ben-attachments value='${esc(JSON.stringify(atts))}'><div class="benefit-image-strip" data-ben-image-list>${benefitImagesHTML(atts)}</div><button type="button" class="btn small" data-ben-add-image>＋ チェキ画像</button>`:''}</details>`:'';
 return `<div class="benefit-row" data-benefit-row="${id}"><select data-ben-group>${groupOptions(b.groupId||'')}</select><select data-ben-member>${memberOptions(b.memberId||'',b.groupId||'', $('eventDate')?.value||'')}</select><input data-ben-count type="number" min="0" step="1" value="${Number(b.count)||0}" placeholder="枚数"><label class="chip case-chip" title="基礎0.4Carat"><input data-ben-case type="checkbox" ${b.case?'checked':''}> 件数</label><button class="row-remove" data-row-remove>×</button>${detail}</div>`
}

function benefitImagesHTML(ids=[]){return ids.length?ids.map(id=>{const a=attachmentById(id);if(!a)return'';const src=mediaURL(a.path);if(!src)native('load-media',{id});return `<button type="button" class="benefit-thumb" data-att-open="${id}">${src?`<img data-media-path="${esc(a.path)}" src="${esc(src)}" alt="チェキ">`:'<span class="image-placeholder">読込中</span>'}</button>`}).join(''):'<span class="hint">画像なし</span>'}
function updateBenefitImageList(row,ids){const hidden=row.querySelector('[data-ben-attachments]');if(hidden)hidden.value=JSON.stringify(ids);const list=row.querySelector('[data-ben-image-list]');if(list)list.innerHTML=benefitImagesHTML(ids);qsa('[data-att-open]',row).forEach(b=>b.onclick=()=>native('open-attachment',{id:b.dataset.attOpen}))}
function expenseRowHTML(x={}){return `<div class="expense-row"><select data-exp-cat>${EXPENSE_CATEGORIES.map(c=>`<option ${c===(x.category||'チケット')?'selected':''}>${c}</option>`).join('')}</select><input data-exp-amount type="number" min="0" step="1" value="${Number(x.amount)||''}" placeholder="金額"><input data-exp-desc type="text" value="${esc(x.description||'')}" placeholder="内容・その他出費名"><button class="row-remove" data-row-remove>×</button></div>`}
function songOptions(selected='',groupId=''){return `<option value="">楽曲を選択／自由入力</option>`+G.state.songs.filter(s=>!groupId||s.groupId===groupId).map(s=>`<option value="${s.id}" ${s.id===selected?'selected':''}>${esc(s.title)}</option>`).join('')}
function setlistRowHTML(r={},i=0){return `<div class="setlist-row"><input data-set-order type="number" min="1" step="1" value="${r.order||i+1}"><select data-set-group>${groupOptions(r.groupId||'')}</select><select data-set-song>${songOptions(r.songId||'',r.groupId||'')}</select><button class="row-remove" data-row-remove>×</button><label class="field" style="grid-column:2/-1;margin:0"><input data-set-title value="${esc(r.songTitle||'')}" placeholder="データベースにない場合の楽曲名"><span class="hint"><label><input data-set-encore type="checkbox" ${r.encore?'checked':''}> アンコール</label></span></label></div>`}
function currentEventFromForm(){
 const type=$('eventType').value,groupIds=qsa('#eventGroupChecks input:checked').map(x=>x.value),venueSel=$('eventVenue').value;
 const seed=G.formSeedEvent||{};return{id:$('eventId').value||uid('e'),date:$('eventDate').value,time:$('eventTime').value,name:$('eventName').value.trim(),type,status:type==='schedule'?'確定予定':$('eventStatus').value,groupIds,venueId:venueSel==='__custom'?'':venueSel,venueText:venueSel==='__custom'?$('eventVenueText').value.trim():'',important:$('eventImportant').checked,tags:G.state.settings.features.tags?($('eventTags').value||'').split(',').map(x=>x.trim()).filter(Boolean):(seed.tags||[]),seatNumber:$('seatNumber')?.value?.trim()??seed.seatNumber??'',queueNumber:$('queueNumber')?.value?.trim()??seed.queueNumber??'',benefits:collectBenefits(),expenses:type==='schedule'?[]:collectExpenses(),notes:$('eventNotes')?$('eventNotes').value:(seed.notes||''),attachments:JSON.parse($('eventAttachmentsState')?.value||'[]'),setlist:G.state.settings.features.setlist?collectSetlist():(seed.setlist||[]),travelEnabled:G.state.settings.features.travel?($('travelToggle')?.checked||false):!!seed.travelEnabled,travelId:G.state.settings.features.travel?($('eventTravelId')?.value||''):(seed.travelId||''),otherDays:Number($('otherDays')?.value)||0,otherCount:Number($('otherCount')?.value??1)||0,scheduleKind:$('scheduleKind')?.value||'',scheduleAt:$('scheduleAt')?.value||'',createdAt:$('eventCreatedAt').value||new Date().toISOString(),updatedAt:new Date().toISOString()}
}
function collectBenefits(){return qsa('[data-benefit-row]').map(r=>({id:r.dataset.benefitRow,groupId:r.querySelector('[data-ben-group]').value,memberId:r.querySelector('[data-ben-member]').value,count:Number(r.querySelector('[data-ben-count]').value)||0,case:r.querySelector('[data-ben-case]')?.checked||false,kind:$('eventType').value==='online_bingo'?'bingo':'cheki',note:r.querySelector('[data-ben-note]')?.value||'',attachments:(()=>{try{return JSON.parse(r.querySelector('[data-ben-attachments]')?.value||'[]')}catch{return[]}})()})).filter(x=>x.count>0||x.case)}
function collectExpenses(){return qsa('.expense-row').map(r=>({id:uid('x'),category:r.querySelector('[data-exp-cat]').value,amount:Number(r.querySelector('[data-exp-amount]').value)||0,description:r.querySelector('[data-exp-desc]').value.trim()})).filter(x=>x.amount>0||x.description)}
function collectSetlist(){return qsa('.setlist-row').map((r,i)=>({id:uid('sl'),order:Number(r.querySelector('[data-set-order]').value)||i+1,groupId:r.querySelector('[data-set-group]').value,songId:r.querySelector('[data-set-song]').value,songTitle:r.querySelector('[data-set-title]').value.trim(),encore:r.querySelector('[data-set-encore]').checked,notes:''})).filter(x=>x.songId||x.songTitle)}
function eventFormHTML(e){
 const features=G.state.settings.features,venueOpts='<option value="">会場未設定</option>'+G.state.venues.map(v=>`<option value="${v.id}" ${v.id===e.venueId?'selected':''}>${esc(v.name)}</option>`).join('')+`<option value="__custom" ${!e.venueId&&e.venueText?'selected':''}>自由入力</option>`;
 return `<div class="modal-head"><div><div class="guide-kicker">EVENT ENTRY</div><h2>${G.editingEventId?'現場を編集':'現場を登録'}</h2></div><button class="close-btn" data-close>×</button></div>
 <input type="hidden" id="eventId" value="${e.id||''}"><input type="hidden" id="eventCreatedAt" value="${esc(e.createdAt||'')}"><input type="hidden" id="eventAttachmentsState" value='${esc(JSON.stringify(e.attachments||[]))}'>
 <div class="entry-intro"><b>まず必須項目だけ入力すれば登録できます</b><span><em>*</em> の付いた項目が必須です。その他は必要なときだけ入力してください。</span></div>
 ${G.state.templates.length?`<div class="template-assist"><label class="field" style="margin:0"><span>いつもの入力を使う</span><div class="inline-action"><select id="templateSelect"><option value="">テンプレートを使わない</option>${G.state.templates.map(t=>`<option value="${t.id}">${esc(t.name)}</option>`).join('')}</select><button class="btn small" id="applyTemplateBtn">適用</button></div></label></div>`:''}
 <section class="form-section"><div class="form-section-head"><span class="step-no">1</span><div><b>基本情報</b><small>まずここを入力します</small></div></div><div class="form-grid"><label class="field"><span class="req">日付</span><input id="eventDate" type="date" value="${e.date||todayISO()}"></label><label class="field"><span>時刻</span><input id="eventTime" type="time" value="${e.time||''}"></label><label class="field full"><span class="req">現場名</span><input id="eventName" type="text" value="${esc(e.name||'')}" placeholder="例：○○ツアー 東京公演" autocomplete="off" autocapitalize="none" spellcheck="false"></label><label class="field"><span class="req">現場種別</span><select id="eventType">${TYPES.map(t=>`<option value="${t.id}" ${t.id===e.type?'selected':''}>${esc(t.name)}</option>`).join('')}</select><div class="hint" id="eventTypeHelp"></div></label><label class="field" id="statusField"><span>ステータス</span><select id="eventStatus">${STATUS.map(s=>`<option ${s===(e.status||'確定予定')?'selected':''}>${s}</option>`).join('')}</select><div class="hint">参加済みなら「実績」、参加が決まっていれば「確定予定」。</div></label></div></section>
 <section class="form-section"><div class="form-section-head"><span class="step-no">2</span><div><b>出演・会場</b><small>誰の、どこで行われる現場か</small></div></div><div class="form-grid"><div class="field full"><span>グループ</span><div class="hint" style="margin-bottom:6px">複数グループの対バンは複数選択できます。</div>${groupCheckHTML(e.groupIds||[])}</div><label class="field full"><span>会場</span><select id="eventVenue">${venueOpts}</select><input id="eventVenueText" class="${!e.venueId&&e.venueText?'':'hidden'}" style="margin-top:6px" value="${esc(e.venueText||'')}" placeholder="会場名を自由入力"></label><label class="switch-row field full"><div class="text"><b>重要現場としてマーク</b><small>ONにするとホーム画面で目立つ位置に表示します</small></div><span class="switch"><input type="checkbox" id="eventImportant" ${e.important?'checked':''}><i></i></span></label></div></section>
 <section class="form-section"><div class="form-section-head"><span class="step-no">3</span><div><b>現場に応じた情報</b><small>種別に合わせて必要な欄だけ表示されます</small></div></div><div id="typeSpecific"></div><div id="benefitSection"></div><div id="expenseSection" class="field ${features.expenses||e.type==='merch'?'':'hidden'}"><span class="field-label">支出明細</span><div class="hint" style="margin-bottom:7px">金額を記録したいときだけ追加します。</div><div id="expenseRows">${(e.expenses||[]).map(expenseRowHTML).join('')}</div><button class="btn small" id="addExpenseRow">＋ 支出を追加</button></div>${features.setlist?`<div id="setlistSection" class="field"><span class="field-label">セットリスト</span><div class="hint" style="margin-bottom:7px">ライブの場合のみ使用します。空欄でも構いません。</div><div id="setlistRows">${(e.setlist||[]).map(setlistRowHTML).join('')}</div><button class="btn small" id="addSetlistRow">＋ 楽曲を追加</button></div>`:''}</section>
 ${(features.tags||features.notes||features.attachments)?`<section class="form-section optional-section"><div class="form-section-head"><span class="step-no optional">4</span><div><b>記録を残す（任意）</b><small>設定でONにした項目だけ表示</small></div></div>${features.tags?`<label class="field"><span>タグ</span><input id="eventTags" list="tagSuggestions" value="${esc((e.tags||[]).join(', '))}" placeholder="例：生誕, 遠征（カンマ区切り）"><datalist id="tagSuggestions">${G.state.tags.map(t=>`<option value="${esc(t)}">`).join('')}</datalist></label>`:''}${features.notes?`<label class="field"><span>参考事項・意見</span><textarea id="eventNotes" placeholder="書きたいときだけ。空欄でまったく問題ありません。">${esc(e.notes||'')}</textarea></label>`:''}${features.attachments?`<div class="field"><span class="field-label">画像</span><div class="attachment-list" id="eventAttachmentList"></div><button class="btn small" id="addEventAttachment">＋ 画像を追加</button></div>`:''}</section>`:''}
 ${features.travel?`<section class="form-section optional-section"><div class="form-section-head"><span class="step-no optional">5</span><div><b>遠征（任意）</b><small>遠征でない現場はOFFのままでOK</small></div></div><label class="switch-row"><div class="text"><b>この現場を遠征に含める</b><small>ONにすると既存遠征への紐付け・新規遠征作成ができます</small></div><span class="switch"><input id="travelToggle" type="checkbox" ${e.travelEnabled?'checked':''}><i></i></span></label><div id="eventTravelBox"></div></section>`:'<input id="travelToggle" type="checkbox" class="hidden">'}
 <div class="template-footer"><button class="btn small" id="saveAsTemplateBtn">この入力内容をテンプレートとして保存</button></div><div class="panel compact hidden" id="templateSaveBox"><label class="field" style="margin:0"><span>テンプレート名</span><div class="inline-action"><input id="templateNameInput" placeholder="例：通常ライブ"><button class="btn small" id="confirmTemplateSave">保存</button></div></label></div>
 <div class="modal-foot"><button class="btn" data-close>キャンセル</button><button class="btn primary" id="saveEventBtn">${G.editingEventId?'この内容で更新':'この内容で登録'}</button></div>`
}
function defaultEvent(){return{id:'',date:todayISO(),time:'',name:'',type:'live',status:'確定予定',groupIds:G.state.settings.primaryGroupId?[G.state.settings.primaryGroupId]:[],venueId:'',venueText:'',important:false,tags:[],benefits:[],expenses:[],notes:'',attachments:[],setlist:[],travelEnabled:false,travelId:'',otherDays:0,otherCount:1,scheduleKind:'',scheduleAt:'',createdAt:''}}
function openEventForm(id=''){
 G.editingEventId=id||null;const e=id?clone(G.state.events.find(x=>x.id===id)):defaultEvent();if(!e)return;G.formSeedEvent=clone(e);setModal(eventFormHTML(e));bindEventForm(e);updateEventTypeUI(e);renderEventAttachments(e.attachments||[]);renderEventTravelBox(e)
}
function updateEventTypeUI(seed=null){
 const type=$('eventType').value,features=G.state.settings.features,e=seed||{};$('statusField').classList.toggle('hidden',type==='schedule');const typeHelp={live:'ライブ・フェス・対バンなど。基本1.00Caratです。',release:'リリースイベント。基本1.00Caratです。',special:'大特典会。基礎0.40＋チェキ1枚×0.20で算定します。',handover:'写真集などのお渡し会。基礎0.40＋チェキ1枚×0.20で算定します。',online_cheki:'オンラインのサインチェキ。1枠0.40Caratです。',online_bingo:'オンラインビンゴ等。1枠0.10Caratです。',stream:'配信視聴のみ。0.50Caratです。',unauthorized:'無券で現地へ行った場合。0.50Caratです。',unauthorized_stream:'無券現地＋配信視聴。1.00Caratです。',merch:'物販・FC更新等だけを記録。現場件数・Caratは0です。',schedule:'抽選締切・先着開始などの予定。現場件数・Caratは0です。',other:'自由にCarat・件数を設定します。'};if($('eventTypeHelp'))$('eventTypeHelp').textContent=typeHelp[type]||'';
 let html='';if(type==='schedule')html=`<div class="form-grid"><label class="field"><span>スケジュール種別</span><select id="scheduleKind">${SCHEDULE_KINDS.map(x=>`<option ${x===(e.scheduleKind||'チケット抽選締切')?'selected':''}>${x}</option>`).join('')}</select></label><label class="field"><span>期限・開始日時</span><input id="scheduleAt" type="datetime-local" value="${e.scheduleAt||`${$('eventDate').value}T${$('eventTime').value||'20:00'}`}"></label></div>`;
 else if(type==='other')html=`<div class="form-grid"><label class="field"><span>GEM Carat</span><input id="otherDays" type="number" min="0" step="0.01" value="${e.otherDays||0}"></label><label class="field"><span>現場件数</span><input id="otherCount" type="number" min="0" step="1" value="${e.otherCount??1}"></label></div>`;
 else if(features.seatQueue&&type==='live')html=`<label class="field"><span>席番号</span><input id="seatNumber" value="${esc(e.seatNumber||'')}" placeholder="例：アリーナA3ブロック 12列 34番"></label>`;
 else if(features.seatQueue&&type==='release')html=`<label class="field"><span>整番</span><input id="queueNumber" value="${esc(e.queueNumber||'')}" placeholder="例：A-123"></label>`;
 $('typeSpecific').innerHTML=html;
 const benefitTypes=['special','handover','online_cheki','online_bingo'];const showBase=benefitTypes.includes(type)||type==='live';
 $('benefitSection').innerHTML=showBase?`<div class="field"><span class="field-label">${type==='live'?'終演後などの特典明細（任意）':'特典明細'}</span><div class="hint" style="margin-bottom:7px">${type==='live'?'チェキ等がある場合だけ追加します。':'参加したメンバー・枠数を追加してください。'}</div><div id="benefitRows">${(e.benefits||[]).map(benefitRowHTML).join('')}</div><button class="btn small" id="addBenefitRow">＋ 明細を追加</button><div class="hint case-hint">${['special','handover'].includes(type)?'「件数」を1行だけONにすると基礎0.40Caratを計上します。':''}</div></div>`:'';
 if($('addBenefitRow'))$('addBenefitRow').onclick=()=>{$('benefitRows').insertAdjacentHTML('beforeend',benefitRowHTML());bindDynamicRows();updateCaseVisibility()};bindDynamicRows();updateCaseVisibility();
 if($('setlistSection'))$('setlistSection').classList.toggle('hidden',type!=='live');
 if($('expenseSection'))$('expenseSection').classList.toggle('hidden',type==='schedule'||(!features.expenses&&type!=='merch'));
 if(type==='merch'||type==='schedule'){if($('travelToggle'))$('travelToggle').checked=false;if($('eventTravelBox'))$('eventTravelBox').innerHTML=''}
}
function updateCaseVisibility(){const show=['special','handover'].includes($('eventType').value);qsa('.case-chip').forEach(x=>x.classList.toggle('hidden',!show))}
function bindDynamicRows(){
 qsa('[data-row-remove]').forEach(b=>b.onclick=()=>b.closest('[data-benefit-row],.expense-row,.setlist-row')?.remove());
 qsa('[data-ben-group]').forEach(sel=>sel.onchange=()=>{const row=sel.closest('[data-benefit-row]'),m=row.querySelector('[data-ben-member]'),cur=m.value;m.innerHTML=memberOptions(cur,sel.value,$('eventDate').value)});
 qsa('[data-set-group]').forEach(sel=>sel.onchange=()=>{const row=sel.closest('.setlist-row'),song=row.querySelector('[data-set-song]'),cur=song.value;song.innerHTML=songOptions(cur,sel.value)});
 qsa('[data-ben-add-image]').forEach(b=>b.onclick=()=>native('pick-image-attachment',{target:'benefit',benefitId:b.closest('[data-benefit-row]').dataset.benefitRow,ratio:'4:3'}));
 qsa('[data-att-open]').forEach(b=>b.onclick=()=>native('open-attachment',{id:b.dataset.attOpen}));
}
function bindEventForm(e){
 qsa('[data-close]').forEach(b=>b.onclick=closeModal);qsa('#eventGroupChecks label').forEach(l=>l.onclick=()=>setTimeout(()=>l.classList.toggle('active',l.querySelector('input').checked),0));
 $('eventVenue').onchange=()=>$('eventVenueText').classList.toggle('hidden',$('eventVenue').value!=='__custom');$('eventType').onchange=()=>updateEventTypeUI(currentEventSnapshot(e));
 if($('addExpenseRow'))$('addExpenseRow').onclick=()=>{$('expenseRows').insertAdjacentHTML('beforeend',expenseRowHTML());bindDynamicRows()};
 if($('addSetlistRow'))$('addSetlistRow').onclick=()=>{$('setlistRows').insertAdjacentHTML('beforeend',setlistRowHTML({},qsa('.setlist-row').length));bindDynamicRows()};
 if($('addEventAttachment'))$('addEventAttachment').onclick=()=>native('pick-image-attachment',{entityType:'event',entityId:$('eventId').value||'draft'});
 if($('travelToggle'))$('travelToggle').onchange=()=>renderEventTravelBox({travelId:$('eventTravelId')?.value||''});
 if($('applyTemplateBtn'))$('applyTemplateBtn').onclick=()=>applyTemplateToForm($('templateSelect').value);
 $('saveAsTemplateBtn').onclick=()=>$('templateSaveBox').classList.toggle('hidden');if($('confirmTemplateSave'))$('confirmTemplateSave').onclick=saveTemplateFromForm;
 $('saveEventBtn').onclick=saveEventFromForm;
 bindDynamicRows();
}
function currentEventSnapshot(seed){try{return{...seed,...currentEventFromForm()}}catch{return seed||{}}}
function renderEventAttachments(ids=[]){if(!$('eventAttachmentList'))return;$('eventAttachmentsState').value=JSON.stringify(ids);$('eventAttachmentList').innerHTML=ids.map(id=>attachmentRowHTML(id,true)).join('')||'<div class="hint">添付なし</div>';qsa('[data-att-open]').forEach(b=>b.onclick=()=>native('open-attachment',{id:b.dataset.attOpen}));qsa('[data-att-remove]').forEach(b=>b.onclick=()=>removeAttachmentFromEvent(b.dataset.attRemove))}
function attachmentRowHTML(id,removable=false){const a=attachmentById(id);if(!a)return'';const icon='▧';return `<div class="attachment-row"><div class="file-icon">${icon}</div><div><b>${esc(a.name)}</b><small>image</small></div><div><button class="btn small" data-att-open="${a.id}">開く</button>${removable?`<button class="btn small danger" data-att-remove="${a.id}">外す</button>`:''}</div></div>`}
function removeAttachmentFromEvent(id){const ids=JSON.parse($('eventAttachmentsState').value||'[]').filter(x=>x!==id);renderEventAttachments(ids)}
function renderEventTravelBox(seed={}){if(!$('eventTravelBox'))return;const on=$('travelToggle').checked;if(!on){$('eventTravelBox').innerHTML='';return}const id=seed.travelId||'';$('eventTravelBox').innerHTML=`<div class="panel compact"><label class="field"><span>遠征</span><select id="eventTravelId"><option value="">新しい遠征を作成（現場保存後に登録）</option>${activeTravels().map(t=>`<option value="${t.id}" ${t.id===id?'selected':''}>${esc(t.name)} ${fmtDateShort(t.startDate)}〜${fmtDateShort(t.endDate)}</option>`).join('')}</select></label><div class="hint">既存遠征に追加する場合は選択。新規の場合は現場保存後、遠征登録画面を開きます。</div></div>`}
function validateEvent(e){const errs=[];if(!e.date)errs.push('日付を入力してください');if(!e.name)errs.push('現場名を入力してください');if(['special','handover'].includes(e.type)&&e.benefits.filter(b=>b.case).length>1)errs.push('「件数」は同一現場で1行だけ選択できます');if(e.type==='schedule'&&!e.scheduleAt)errs.push('スケジュール日時を入力してください');return errs}
function saveEventFromForm(){
 const e=currentEventFromForm(),errs=validateEvent(e);if(errs.length){toast(errs[0]);return}
 const idx=G.state.events.findIndex(x=>x.id===e.id);if(idx>=0)G.state.events[idx]=e;else G.state.events.push(e);
 (e.tags||[]).forEach(t=>{if(!G.state.tags.includes(t))G.state.tags.push(t)});
 if(e.travelId){const t=G.state.travels.find(x=>x.id===e.travelId);if(t&&!t.eventIds.includes(e.id))t.eventIds.push(e.id)}
 G.state.travels.forEach(t=>{if(t.id!==e.travelId)t.eventIds=(t.eventIds||[]).filter(id=>id!==e.id)});
 persist();closeModal();renderAll();toast(idx>=0?'更新しました':'登録しました');if(e.travelEnabled&&!e.travelId)setTimeout(()=>openTravelForm('',e.id),200)
}
function applyTemplateToForm(id){const t=G.state.templates.find(x=>x.id===id);if(!t)return;const d=t.data||{};if(d.type)$('eventType').value=d.type;if(d.status)$('eventStatus').value=d.status;qsa('#eventGroupChecks input').forEach(c=>{c.checked=(d.groupIds||[]).includes(c.value);c.closest('label').classList.toggle('active',c.checked)});if(d.venueId)$('eventVenue').value=d.venueId;updateEventTypeUI({...currentEventSnapshot(),...d,benefits:[]});toast('テンプレートを適用しました')}
function saveTemplateFromForm(){const name=$('templateNameInput').value.trim();if(!name){toast('テンプレート名を入力してください');return}const e=currentEventFromForm();G.state.templates.push({id:uid('tpl'),name,data:{type:e.type,status:e.status,groupIds:e.groupIds,venueId:e.venueId,venueText:e.venueText,tags:e.tags}});persist();$('templateSaveBox').classList.add('hidden');toast('テンプレートを保存しました')}

function shareTextEvent(e){return `${e.date.replaceAll('-','.')}\n${eventGroupNames(e)?eventGroupNames(e)+'「':''}${e.name}${eventGroupNames(e)?'」':''}${eventVenue(e)?`\n@ ${eventVenue(e)}`:''}\n\nGEMSに現場記録を追加しました。\n#GEMS #現場記録`}
function chatLogEvent(e){return `【GEMS 推し活ログ】\n日付：${e.date}\n現場：${e.name}\nグループ：${eventGroupNames(e)||'未設定'}\n会場：${eventVenue(e)||'未設定'}\n種別：${typeById(e.type).name}\nGEM Carat：${eventWorkdays(e).toFixed(2)}\n遠征Carat配分：${eventTravelShare(e).toFixed(2)}\nチェキ：${(e.benefits||[]).filter(b=>(b.kind||'cheki')!=='bingo').map(b=>`${memberById(b.memberId)?.name||groupById(resolveBenefitGroup(b,e))?.name||'未設定'} ${b.count}枚`).join('、')||'なし'}\n支出：${yen(expenseTotal(e))}${e.notes?`\n参考事項・意見：${e.notes}`:''}\n\nこの推し活ログを報告します。内容を整理・分析してください。`}
function shareTextCheki(e,b){return `${e.date.replaceAll('-','.')}｜${memberById(b.memberId)?.name||'メンバー'}\n${e.name}\nチェキ：${b.count}枚\n\nGEMS CHEKI LOG\n#GEMS`}
function chatLogCheki(e,b){return `【GEMS チェキログ】\n日付：${e.date}\n現場：${e.name}\nメンバー：${memberById(b.memberId)?.name||'未設定'}\n枚数：${b.count}${b.note?`\nメモ：${b.note}`:''}\n\nこのチェキ記録を報告します。`}
function shareTextMember(m,st){return `【GEMS MEMBER LOG】\n${m.name}\n通算関連GEM：${st.eventCount}件\n通算チェキ：${st.cheki}枚${st.first?`\n初回記録：${st.first}`:''}\n#GEMS`}
function chatLogMember(m,st){return `【GEMS メンバーログ】\nメンバー：${m.name}\n所属：${(m.memberships||[]).map(x=>groupById(x.groupId)?.name).filter(Boolean).join(' / ')||'未設定'}\n推し：${m.favorite?'はい':'いいえ'}\n通算関連GEM：${st.eventCount}\n通算チェキ：${st.cheki}枚\n初回記録：${st.first||'なし'}\n最終記録：${st.last||'なし'}${m.notes?`\n備考：${m.notes}`:''}\n\nこのメンバーについての推し活ログを報告します。`}
function shareTextGroup(g,st){return `【GEMS GROUP REPORT】\n${g.name}\n現場件数：${st.eventCount.toFixed(0)}\nGEM Carat：${st.eventDays.toFixed(2)}\n遠征Carat：${st.travelDays.toFixed(2)}\nチェキ：${st.cheki}枚\n#GEMS`}
function chatLogGroup(g,st){return `【GEMS グループログ】\nグループ：${g.name}\n現場件数：${st.eventCount.toFixed(0)}\nGEM Carat：${st.eventDays.toFixed(2)}\n遠征Carat：${st.travelDays.toFixed(2)}\nチェキ：${st.cheki}枚\n初回：${st.first||'なし'}\n最終：${st.last||'なし'}${g.notes?`\n備考：${g.notes}`:''}\n\nこのグループについての推し活ログを報告します。`}
function shareTextTravel(t){const n=travelNightsInfo(t);return `【GEMS TRAVEL LOG】\n${t.name}\n${t.startDate}〜${t.endDate}\n${t.originStation||'出発地'} → ${t.destinationStation||'行先'}\n遠征Carat：${n.total.toFixed(2)}\n#GEMS`}
function chatLogTravel(t){const n=travelNightsInfo(t);return `【GEMS 遠征ログ】\n遠征：${t.name}\n期間：${t.startDate}〜${t.endDate}\n区間：${t.originStation} → ${t.destinationStation}\n距離：${Number(t.distanceKm||0).toFixed(1)}km\n実宿泊：${n.actual}泊\n算定宿泊：${n.recognized}泊\n遠征Carat：${n.total.toFixed(2)}\n交通費：${yen(t.transportCost)}\n宿泊費：${yen(t.lodgingCost)}${t.notes?`\n参考事項・意見：${t.notes}`:''}\n\nこの遠征ログを報告します。`}
function openShareModal(title,text,attachmentIds=[],chatText=''){setModal(`<div class="modal-head"><h2>${esc(title)}</h2><button class="close-btn" data-close>×</button></div><div class="panel"><div class="share-preview">${esc(text)}</div>${attachmentIds.length?`<label class="switch-row" style="margin-top:10px"><div class="text"><b>画像も共有する</b><small>初期値OFF。チェキ画像等を共有するときだけON。</small></div><span class="switch"><input id="shareIncludeImages" type="checkbox"><i></i></span></label>`:''}</div><div class="share-actions"><button class="btn primary" id="shareSheetBtn">X / LINE / メールで共有</button><button class="btn chatgpt" id="shareChatGPTBtn">ChatGPTに報告</button></div><div class="modal-foot"><button class="btn" data-close>閉じる</button></div>`);qsa('[data-close]').forEach(b=>b.onclick=closeModal);$('shareSheetBtn').onclick=()=>native('share',{text,attachmentIds:$('shareIncludeImages')?.checked?attachmentIds:[]});$('shareChatGPTBtn').onclick=()=>native('share-chatgpt',{text:chatText||text})}
function eventDetailPhotosHTML(e){const atts=(e.attachments||[]).map(attachmentById).filter(Boolean);if(!atts.length)return'';const withSrc=atts.map(a=>({a,src:mediaURL(a.path)}));return `<div class="panel"><h3>現場写真</h3><div class="event-photo-grid">${withSrc.map(({a,src})=>`<button class="event-photo-btn" data-att-open="${a.id}">${src?`<img src="${esc(src)}" alt="${esc(a.name||'現場写真')}">`:'<span>画像を開く</span>'}</button>`).join('')}</div><div class="hint" style="margin-top:8px">画像をタップすると原画像を表示します。</div></div>`}
function eventDetailHeroHTML(e){const photos=eventPhotoAttachments(e).slice(0,5);if(!photos.length)return'';return `<div class="detail-photo-hero">${photos.map((a,i)=>`<img src="${esc(mediaURL(a.path))}" alt="" style="animation-delay:${i*4}s">`).join('')}<span class="detail-photo-count">写真 ${eventPhotoAttachments(e).length}枚</span></div>`}
function openEventDetail(id){const e=G.state.events.find(x=>x.id===id);if(!e)return;const ga=groupEventAlloc(e),travel=eventTravelShare(e),travelObj=e.travelId?G.state.travels.find(t=>t.id===e.travelId):null;setModal(`<div class="modal-head"><h2>${e.type==='schedule'?'スケジュール詳細':'現場詳細'}</h2><button class="close-btn" data-close>×</button></div><div class="panel">${e.type!=='schedule'?eventDetailHeroHTML(e):''}<div class="event-date">${esc(e.type==='schedule'?(e.scheduleAt||e.date).replace('T',' '):fmtDate(e.date))}</div><h2 style="margin:4px 0 7px">${e.important?'★ ':''}${esc(e.name)}</h2><div class="chips"><span class="badge">${esc(typeById(e.type).name)}</span>${e.status?`<span class="badge">${esc(e.status)}</span>`:''}${(e.tags||[]).map(t=>`<span class="badge primary">${esc(t)}</span>`).join('')}</div></div>${e.type!=='schedule'?`<div class="detail-grid"><div class="detail-item"><span>GEM Carat</span><b>${eventWorkdays(e).toFixed(2)}</b></div><div class="detail-item"><span>遠征Carat配分</span><b>${travel.toFixed(2)}</b></div><div class="detail-item"><span>合計Carat</span><b>${eventTotalDays(e).toFixed(2)}</b></div><div class="detail-item"><span>支出</span><b>${yen(expenseTotal(e))}</b></div><div class="detail-item"><span>グループ</span><b>${esc(eventGroupNames(e))}</b></div><div class="detail-item"><span>会場</span><b>${esc(eventVenue(e)||'—')}</b></div>${e.seatNumber?`<div class="detail-item"><span>席番号</span><b>${esc(e.seatNumber)}</b></div>`:''}${e.queueNumber?`<div class="detail-item"><span>整番</span><b>${esc(e.queueNumber)}</b></div>`:''}</div>`:''}${e.type!=='schedule'?eventDetailPhotosHTML(e):''}${Object.keys(ga).length?`<div class="panel"><h3>グループ別GEM Carat</h3>${Object.entries(ga).filter(([g])=>g!=='__unassigned').map(([g,d])=>`<div class="share-top"><b>${esc(groupById(g)?.name||'不明')}</b><span>${d.toFixed(2)}</span></div>`).join('')}</div>`:''}${e.benefits?.length?`<div class="panel"><h3>特典明細</h3>${e.benefits.map(b=>`<div class="master-row"><div><b>${esc(memberById(b.memberId)?.name||groupById(resolveBenefitGroup(b,e))?.name||'')}</b><small>${b.count} ${b.kind==='bingo'?'枠':'枚'}${b.case?' / 件数':''}${b.note?` / ${esc(b.note.slice(0,50))}`:''}${b.attachments?.length?` / 画像${b.attachments.length}枚`:''}</small></div>${b.kind!=='bingo'?`<button class="btn small" data-cheki-detail="${b.id}">開く</button>`:''}</div>`).join('')}</div>`:''}${e.expenses?.length?`<div class="panel"><h3>支出明細</h3><table class="table"><tbody>${e.expenses.map(x=>`<tr><td>${esc(x.category)}</td><td>${esc(x.description||'')}</td><td class="num">${yen(x.amount)}</td></tr>`).join('')}</tbody></table></div>`:''}${travelObj?`<div class="panel"><h3>遠征</h3><div class="detail-text">${esc(travelObj.name)}\n遠征Carat ${travelWorkdays(travelObj).toFixed(2)} / この現場への配分 ${travel.toFixed(2)}</div></div>`:''}${e.notes?`<div class="panel"><h3>参考事項・意見</h3><div class="detail-text">${esc(e.notes)}</div></div>`:''}${e.setlist?.length?`<div class="panel"><h3>セットリスト</h3><ol>${e.setlist.sort((a,b)=>a.order-b.order).map(r=>`<li>${esc(songById(r.songId)?.title||r.songTitle||'')} ${r.encore?'<span class="badge">ENCORE</span>':''}</li>`).join('')}</ol></div>`:''}<div class="modal-foot"><button class="btn" data-close>閉じる</button><button class="btn" id="detailShareBtn">共有</button><button class="btn danger" id="detailDeleteBtn">削除</button><button class="btn primary" id="detailEditBtn">編集</button></div>`);qsa('[data-close]').forEach(b=>b.onclick=closeModal);$('detailEditBtn').onclick=()=>{closeModal();setTimeout(()=>openEventForm(id),0)};$('detailDeleteBtn').onclick=()=>{closeModal();setTimeout(()=>deleteEvent(id),0)};$('detailShareBtn').onclick=()=>openShareModal(e.type==='schedule'?'予定を共有':'現場を共有',shareTextEvent(e),[],chatLogEvent(e));qsa('[data-cheki-detail]').forEach(b=>b.onclick=()=>openChekiDetail(e.id,b.dataset.chekiDetail));qsa('[data-att-open]').forEach(b=>b.onclick=()=>native('open-attachment',{id:b.dataset.attOpen}))}
function deleteEvent(id){const e=G.state.events.find(x=>x.id===id);if(!e)return;confirmModal('削除',`「${e.name}」を削除します。ゴミ箱から復元できます。`,()=>{e.deletedAt=new Date().toISOString();G.state.travels.forEach(t=>t.eventIds=(t.eventIds||[]).filter(x=>x!==id));G.state.trash.push({kind:'event',id,deletedAt:e.deletedAt});persist();renderAll();toast('削除しました')},{danger:true})}
function defaultTravel(eventId=''){const e=G.state.events.find(x=>x.id===eventId),v=e?venueById(e.venueId):null;return{id:'',name:e?`${eventVenue(e)||e.name} 遠征`:'',startDate:e?.date||todayISO(),endDate:e?.date||todayISO(),originStation:G.state.settings.homeStation||'',destinationStation:v?.station||'',distanceKm:0,distanceSource:'',actualNights:0,recognizedNights:0,transportCost:0,lodgingCost:0,eventIds:eventId?[eventId]:[],notes:'',attachments:[],createdAt:'',updatedAt:''}}
function travelCardHTML(t){const linked=(t.eventIds||[]).map(id=>G.state.events.find(e=>e.id===id&&!e.deletedAt)).filter(Boolean),ni=travelNightsInfo(t);return `<div class="travel-card"><div class="event-top"><div><div class="event-date">${esc(fmtDate(t.startDate))}〜${esc(fmtDateShort(t.endDate))}</div><h3>${esc(t.name)}</h3><div class="event-meta">${esc(t.originStation||'')} → ${esc(t.destinationStation||'')} ・ ${Number(t.distanceKm||0).toFixed(1)}km ・ 実${ni.actual}泊（算定${ni.recognized}泊）<br>紐付け ${linked.length}現場</div></div><div class="event-day">${travelWorkdays(t).toFixed(2)}<small>遠征Carat</small></div></div><div class="event-actions"><button class="btn small" data-travel-open="${t.id}">開く</button><button class="btn small" data-travel-edit="${t.id}">編集</button><button class="btn small danger" data-travel-delete="${t.id}">削除</button></div></div>`}

function digestPastEvents(){return activeEvents().filter(e=>e.type!=='schedule'&&e.status==='実績'&&e.date&&e.date<=todayISO()).sort((a,b)=>b.date.localeCompare(a.date))}
function dailyNumber(salt=''){let x=2166136261;for(const c of `${todayISO()}|${salt}`){x^=c.charCodeAt(0);x=Math.imul(x,16777619)}return Math.abs(x>>>0)}
function dailyPick(arr,salt=''){return arr.length?arr[dailyNumber(salt)%arr.length]:null}
function memoryEventCard(e,label=''){if(!e)return'<div class="digest-empty">表示できる過去現場がまだありません。</div>';const photos=eventPhotoAttachments(e),src=photos[0]?mediaURL(photos[0].path):'',cheki=sum(chekiBenefits([e]),x=>x.count);return `${src?`<div class="digest-photo"><img src="${esc(src)}" alt=""><span class="digest-photo-label">${esc(label||fmtDate(e.date))}</span></div>`:''}<div class="digest-memory-title">${esc(e.name)}</div><div class="digest-meta">${esc(fmtDate(e.date))} ・ ${esc(eventGroupNames(e))}${eventVenue(e)?`<br>${esc(eventVenue(e))}`:''}</div><div class="digest-stat-row"><div class="digest-stat"><b>${eventWorkdays(e).toFixed(2)}</b><span>GEM Carat</span></div><div class="digest-stat"><b>${cheki}</b><span>チェキ</span></div><div class="digest-stat"><b>${yen(expenseTotal(e))}</b><span>支出</span></div></div><div class="digest-actions"><button class="btn small" data-event-open="${e.id}">開く</button></div>`}
function onThisDayMemory(){const past=digestPastEvents(),today=todayISO(),md=today.slice(5);let exact=past.filter(e=>e.date.slice(5)===md&&e.date<today);if(exact.length){const e=exact[0],years=Number(today.slice(0,4))-Number(e.date.slice(0,4));return{e,label:`${years}年前の今日`}}const td=new Date(`${today}T00:00:00`),sameDay=past.filter(e=>Number(e.date.slice(8,10))===td.getDate());if(sameDay.length){const e=sameDay[0],d=new Date(`${e.date}T00:00:00`),months=(td.getFullYear()-d.getFullYear())*12+td.getMonth()-d.getMonth();return{e,label:`${months}か月前の今日に近い記録`}}return{e:dailyPick(past,'onthisday'),label:'今日に近い過去の記録'}}
function allPhotoRecords(){const out=[];for(const e of digestPastEvents()){for(const id of e.attachments||[]){const a=attachmentById(id),src=a?mediaURL(a.path):'';if(src)out.push({id,event:e,src,label:'現場写真'})}for(const b of e.benefits||[]){for(const id of b.attachments||[]){const a=attachmentById(id),src=a?mediaURL(a.path):'';if(src)out.push({id,event:e,benefit:b,src,label:memberById(b.memberId)?.name||'チェキ'})}}}return out}
function memberLastRecord(m){const ev=memberRelevantEvents(m.id).filter(e=>e.type!=='schedule'&&e.date<=todayISO()).sort((a,b)=>b.date.localeCompare(a.date));return ev[0]||null}
function digestRanking(kind='groups'){const y=String(new Date().getFullYear()),events=digestPastEvents().filter(e=>e.date.startsWith(y));let rows=[];if(kind==='groups'){const map={};for(const e of events)for(const gid of e.groupIds||[])map[gid]=(map[gid]||0)+eventCount(e);rows=Object.entries(map).map(([id,n])=>({name:groupById(id)?.name||'不明',n,unit:'現場'}))}else if(kind==='cheki'){const map={};for(const x of chekiBenefits(events)){const id=x.memberId||`g:${x.groupId}`,name=x.memberId?memberById(x.memberId)?.name:groupById(x.groupId)?.name;if(name)map[id]={name,n:(map[id]?.n||0)+x.count}}rows=Object.values(map).map(x=>({...x,unit:'枚'}))}else{const map={};for(const e of events){const v=eventVenue(e);if(v)map[v]=(map[v]||0)+eventCount(e)}rows=Object.entries(map).map(([name,n])=>({name,n,unit:'回'}))}return rows.sort((a,b)=>b.n-a.n).slice(0,5)}
function anniversaryItems(){const out=[],today=todayISO(),mmdd=today.slice(5),past=digestPastEvents();for(const g of G.state.groups.filter(g=>g.active!==false)){const ev=groupRelevantEvents(g.id).filter(e=>e.type!=='schedule'&&e.date<=today).sort((a,b)=>a.date.localeCompare(b.date));if(!ev.length)continue;const first=ev[0];if(first.date.slice(5)===mmdd&&first.date!==today){const yrs=Number(today.slice(0,4))-Number(first.date.slice(0,4));if(yrs>0)out.push({icon:'🎉',title:`${g.name} 初現場から${yrs}周年`,meta:first.name})}const cnt=Math.round(sum(ev,eventCount));if(cnt>0&&cnt%10===0)out.push({icon:'◆',title:`${g.name} ${cnt}現場到達`,meta:'通算記録'})}for(const m of G.state.members.filter(x=>x.favorite)){const st=memberStats(m.id);if(st.cheki>0&&st.cheki%10===0)out.push({icon:'◇',title:`${m.name} チェキ${st.cheki}枚`,meta:'通算記録'})}if(!out.length&&past.length){const e=past[past.length-1],days=Math.floor((new Date(`${today}T00:00:00`)-new Date(`${e.date}T00:00:00`))/86400000);out.push({icon:'◈',title:`GEMS最初の現場記録から${days}日`,meta:e.name})}return out.slice(0,8)}
function renderDigestMain(random=false){const past=digestPastEvents(),e=random?past[Math.floor(Math.random()*past.length)]:dailyPick(past,'main');$('digestMain').innerHTML=`<div class="digest-card"><div class="digest-card-head"><div><h3>GEMS DIGEST</h3><small>${random?'ランダムに選びました':'本日のピックアップ'}</small></div></div><div class="digest-body">${memoryEventCard(e,'TODAY\'S GEMS')}</div></div>`;bindEventOpeners()}
function renderDigestRandom(random=false){const past=digestPastEvents(),e=random?past[Math.floor(Math.random()*past.length)]:dailyPick(past,'random');$('digestRandomMemory').innerHTML=memoryEventCard(e,'RANDOM MEMORY');bindEventOpeners()}
function renderDigestPhoto(random=false){const photos=allPhotoRecords(),p=random?photos[Math.floor(Math.random()*photos.length)]:dailyPick(photos,'photo');$('digestPhoto').innerHTML=p?`<button class="digest-photo" style="border:0;width:100%;padding:0" data-att-open="${p.id}"><img src="${esc(p.src)}" alt=""><span class="digest-photo-label">${esc(p.label)} ・ ${esc(fmtDateShort(p.event.date))} ${esc(p.event.name)}</span></button>`:'<div class="digest-empty">画像を登録すると「今日の1枚」が表示されます。</div>';qsa('#digestPhoto [data-att-open]').forEach(b=>b.onclick=()=>native('open-attachment',{id:b.dataset.attOpen}))}
function renderDigestRanking(){const rows=digestRanking($('digestRankingKind')?.value||'groups');$('digestRanking').innerHTML=rows.length?`<div class="digest-list">${rows.map((r,i)=>`<div class="digest-row"><span class="digest-rank">${i+1}</span><div><b>${esc(r.name)}</b><small>${new Date().getFullYear()}年</small></div><strong>${r.n}${r.unit}</strong></div>`).join('')}</div>`:'<div class="digest-empty">今年の実績がまだありません。</div>'}
function renderDigest(){const od=onThisDayMemory();$('digestOnThisDay').innerHTML=memoryEventCard(od.e,od.label);const oshis=G.state.members.filter(m=>m.favorite).map(m=>({m,e:memberLastRecord(m)})).filter(x=>x.e).map(x=>({...x,days:daysUntil(x.e.date)*-1})).sort((a,b)=>b.days-a.days);$('digestLongTime').innerHTML=oshis.length?`<div class="digest-list">${oshis.slice(0,8).map(x=>`<button class="digest-row" style="width:100%;text-align:left" data-member-profile="${x.m.id}"><span class="member-color-dot ${memberColorFor(x.m)?'':'none'}" ${memberColorFor(x.m)?`style="background:${esc(memberColorFor(x.m).color)}"`:''}></span><div><b>${esc(x.m.name)}</b><small>最終記録 ${esc(fmtDateShort(x.e.date))} ・ ${esc(x.e.name)}</small></div><strong class="longtime-days">${x.days}日</strong></button>`).join('')}</div>`:'<div class="digest-empty">「推し」にチェックしたメンバーの記録があると表示されます。</div>';$('digestAnniversary').innerHTML=`<div class="digest-list">${anniversaryItems().map(x=>`<div class="digest-row"><span class="anniv-mark">${x.icon}</span><div><b>${esc(x.title)}</b><small>${esc(x.meta)}</small></div><strong></strong></div>`).join('')}</div>`;renderDigestMain(false);renderDigestRandom(false);renderDigestPhoto(false);renderDigestRanking();bindEventOpeners();qsa('[data-member-profile]').forEach(b=>b.onclick=()=>openMemberProfile(b.dataset.memberProfile));if($('digestAnotherBtn'))$('digestAnotherBtn').onclick=()=>renderDigestMain(true);if($('digestRefreshBtn'))$('digestRefreshBtn').onclick=()=>renderDigest();if($('randomMemoryBtn'))$('randomMemoryBtn').onclick=()=>renderDigestRandom(true);if($('randomPhotoBtn'))$('randomPhotoBtn').onclick=()=>renderDigestPhoto(true);if($('digestRankingKind'))$('digestRankingKind').onchange=renderDigestRanking}

function renderTravels(){const rows=activeTravels();$('travelList').innerHTML=rows.sort((a,b)=>b.startDate.localeCompare(a.startDate)).map(travelCardHTML).join('')||'<div class="panel empty-state"><b>遠征はまだ登録されていません</b><span>遠征を使わない場合は、このタブは何もしなくて大丈夫です。</span></div>';qsa('[data-travel-open]').forEach(b=>b.onclick=()=>openTravelDetail(b.dataset.travelOpen));qsa('[data-travel-edit]').forEach(b=>b.onclick=()=>openTravelForm(b.dataset.travelEdit));qsa('[data-travel-delete]').forEach(b=>b.onclick=()=>deleteTravel(b.dataset.travelDelete))}
function travelFormHTML(t){
 const ni=travelNightsInfo(t);return `<div class="modal-head"><div><div class="guide-kicker">TRAVEL ENTRY</div><h2>${G.editingTravelId?'遠征を編集':'遠征を登録'}</h2></div><button class="close-btn" data-close>×</button></div><input type="hidden" id="travelId" value="${t.id||''}"><input type="hidden" id="travelAttachmentsState" value='${esc(JSON.stringify(t.attachments||[]))}'>
 <div class="entry-intro"><b>遠征は、先に登録した現場をまとめる行程データです</b><span>①現場を登録 → ②遠征を作成 → ③この遠征に含む現場を検索して関連付けます。</span></div>
 <div class="panel form-panel"><label class="field"><span class="req">遠征名</span><input id="travelName" value="${esc(t.name||'')}" placeholder="例：大阪遠征"></label><div class="form-grid"><label class="field"><span>開始日</span><input id="travelStart" type="date" value="${t.startDate||todayISO()}"></label><label class="field"><span>終了日</span><input id="travelEnd" type="date" value="${t.endDate||t.startDate||todayISO()}"></label><label class="field"><span>出発地最寄駅</span><input id="travelOrigin" list="stationSuggestions" value="${esc(t.originStation||G.state.settings.homeStation||'')}" placeholder="例：幡ケ谷"></label><label class="field"><span>主たる遠征先最寄駅</span><input id="travelDestination" list="stationSuggestions" value="${esc(t.destinationStation||'')}" placeholder="関連GEMの会場最寄駅から選べます"><div class="station-candidates" id="travelStationCandidates"></div></label></div>
 <div class="form-grid"><label class="field"><span>距離（km）</span><input id="travelDistance" type="number" min="0" step="0.1" value="${Number(t.distanceKm)||''}"><div class="hint" id="distanceSourceHint">${esc(t.distanceSource||'Yahoo!乗換案内 第1候補を基準。取得できない場合は手動入力。')}</div></label><div class="field"><span>&nbsp;</span><button class="btn soft block" id="fetchDistanceBtn">Yahoo!乗換案内から距離取得</button><button class="btn ghost small block" id="openYahooBtn">Yahoo!で経路を確認</button></div></div>
 <div class="travel-rule"><div class="detail-item"><span>実宿泊数</span><b id="travelActualNights">${ni.actual}泊</b><small>開始日〜終了日から自動計算</small></div><div class="detail-item"><span>距離基準の上限</span><b id="travelMaxNights">${ni.maxNights}泊</b><small id="travelDistanceBand">${ni.label}</small></div><div class="detail-item"><span>算定対象宿泊</span><b id="travelRecognizedNights">${ni.recognized}泊</b><small id="travelExcludedNights">対象外 ${ni.excluded}泊</small></div><div class="detail-item"><span>遠征Carat</span><b id="travelDaysPreview">${ni.total.toFixed(2)}</b><small id="travelCalcBreakdown">距離 ${ni.distanceAdd.toFixed(2)} + 宿泊 ${ni.lodgingAdd.toFixed(2)}</small></div></div>
 <div class="form-grid" style="margin-top:10px"><label class="field"><span>交通費</span><input id="transportCost" type="number" min="0" step="1" value="${Number(t.transportCost)||''}"></label><label class="field"><span>宿泊費</span><input id="lodgingCost" type="number" min="0" step="1" value="${Number(t.lodgingCost)||''}"></label></div>
 <div class="field"><span class="field-label">同一遠征に含める現場</span><div class="travel-event-picker"><div class="search"><input id="travelEventSearch" placeholder="現場名・グループ・会場を検索"></div><div class="form-grid" style="margin-top:7px"><select id="travelEventGroupFilter"><option value="">すべてのグループ</option>${G.state.groups.filter(g=>g.active!==false).map(g=>`<option value="${g.id}">${esc(g.name)}</option>`).join('')}</select><select id="travelEventTypeFilter"><option value="">すべての種別</option>${TYPES.filter(x=>!['schedule','merch'].includes(x.id)).map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join('')}</select></div><label class="chip active" style="margin-top:7px"><input id="travelRangeOnly" type="checkbox" checked> 遠征期間内を優先表示</label><div class="search-helper">選択済みの現場は検索条件に関係なく表示します。</div><div class="travel-event-results" id="travelEventResults"></div><div class="data-status" id="travelEventSelectedCount"></div></div></div>
 ${G.state.settings.features.notes?`<label class="field"><span>参考事項・意見</span><textarea id="travelNotes" placeholder="観光や旅程の感想など。空欄でも構いません。">${esc(t.notes||'')}</textarea></label>`:''}${G.state.settings.features.attachments?`<div class="field"><span class="field-label">画像添付</span><div class="attachment-list" id="travelAttachmentList"></div><button class="btn small" id="addTravelAttachment">＋ 画像を追加</button></div>`:''}</div><div class="modal-foot"><button class="btn" data-close>キャンセル</button><button class="btn primary" id="saveTravelBtn">${G.editingTravelId?'更新':'登録'}</button></div>`}

function travelSelectedEventIds(){return [...(G.travelSelectedIds||new Set())]}
function travelCandidateStations(ids=travelSelectedEventIds()){const stations=[];ids.forEach(id=>{const e=G.state.events.find(x=>x.id===id),v=e?venueById(e.venueId):null;if(v?.station&&!stations.includes(v.station))stations.push(v.station)});return stations}
