 $('addHomeImageBtn').onclick=()=>native('pick-photo',{role:'home',ratio:'16:9'});$('customThemeColor').onchange=()=>{G.state.settings.customThemeColor=$('customThemeColor').value;G.state.settings.themePreset=themePresetFromColor($('customThemeColor').value)||G.state.settings.themePreset;persist();renderAll();renderSettings()};$('appearanceMode').onchange=()=>{G.state.settings.appearance=$('appearanceMode').value;persist();applyTheme()};$('saveBasicSettingsBtn').onclick=()=>{G.state.settings.primaryGroupId=$('primaryGroupSelect').value;G.state.settings.homeStation=$('homeStationInput').value.trim();G.state.settings.showEndedSchedules=$('showEndedSchedules').checked;persist();renderStations();toast('基本設定を保存しました')};if($('manageEndedSchedulesBtn'))$('manageEndedSchedulesBtn').onclick=openEndedSchedules;
 $('addGroupBtn').onclick=()=>openGroupMaster();$('addMemberBtn').onclick=()=>openMemberMaster();if($('addMemberColorBtn'))$('addMemberColorBtn').onclick=()=>openMemberColorMaster();$('addVenueBtn').onclick=()=>openVenueMaster();$('addSongBtn').onclick=()=>openSongMaster();$('addTagBtn').onclick=()=>{const t=$('newTagInput').value.trim();if(t&&!G.state.tags.includes(t)){G.state.tags.push(t);$('newTagInput').value='';persist();renderSettings()}};$('saveBudgetBtn').onclick=()=>{const mk=$('budgetMonthKey').value,ma=Number($('budgetMonthAmount').value)||0,yk=String($('budgetYearKey').value||''),ya=Number($('budgetYearAmount').value)||0;if(mk)G.state.settings.budgets.months[mk]=ma;if(yk)G.state.settings.budgets.years[yk]=ya;persist();toast('予算を保存しました')};
