function picto(kind){return `<span class="detail-launch-icon picto-${kind}"><i></i></span>`}
function currentViewName(){return document.querySelector('.view.active')?.dataset.view||'home'}
G.viewHistory=G.viewHistory||[];
function updateBackButton(){const b=$('gemsBackBtn');if(!b)return;const sub=$('subModalBackdrop'),modal=$('modalBackdrop');const overlays=(sub&&!sub.classList.contains('hidden'))||(modal&&!modal.classList.contains('hidden'));b.classList.toggle('hidden',!overlays&&currentViewName()==='home'&&!G.viewHistory.length)}
const _v8ShowView=showView;showView=function(name,opts={}){const cur=currentViewName();if(!opts.noHistory&&cur&&cur!==name)G.viewHistory.push(cur);_v8ShowView(name);updateBackButton()};
const _v8SetModal=setModal;setModal=function(h){_v8SetModal(h);updateBackButton()};const _v8CloseModal=closeModal;closeModal=function(){_v8CloseModal();updateBackButton()};
const _v8SetSubModal=setSubModal;setSubModal=function(h){_v8SetSubModal(h);updateBackButton()};const _v8CloseSubModal=closeSubModal;closeSubModal=function(){_v8CloseSubModal();updateBackButton()};
function backOneScreen(){const sub=$('subModalBackdrop');if(sub&&!sub.classList.contains('hidden')){closeSubModal();return}const modal=$('modalBackdrop');if(modal&&!modal.classList.contains('hidden')){closeModal();return}const prev=G.viewHistory.pop();if(prev)showView(prev,{noHistory:true});else if(currentViewName()!=='home')showView('home',{noHistory:true});updateBackButton()}

const _v8NormalizeState=normalizeState;normalizeState=function(raw){const s=_v8NormalizeState(raw);s.version=8;s.groups=s.groups.map(g=>({...g,iconAttachmentId:g.iconAttachmentId||''}));s.members=s.members.map(m=>({...m,iconAttachmentId:m.iconAttachmentId||''}));s.events=s.events.map(e=>({...e,performerMemberIds:Array.isArray(e.performerMemberIds)?e.performerMemberIds:[],benefits:(e.benefits||[]).map(b=>({...b,part:b.part||''}))}));return s};
function memberAvatarHTML(m,cls='profile-avatar-img'){const a=attachmentById(m?.iconAttachmentId),src=a?mediaURL(a.path):'',c=memberColorFor(m);const border=c?.color||'var(--line)';return src?`<img class="${cls}" style="--avatar-border:${esc(border)}" src="${esc(src)}" alt="${esc(m?.name||'')}">`:`<span class="${cls.replace('img','fallback')}" style="--avatar-border:${esc(border)}">${esc((m?.name||'?').slice(0,1))}</span>`}
function groupAvatarHTML(g,cls='profile-avatar-img'){const a=attachmentById(g?.iconAttachmentId),src=a?mediaURL(a.path):'';return src?`<img class="${cls}" style="--avatar-border:var(--primary)" src="${esc(src)}" alt="${esc(g?.name||'')}">`:`<span class="${cls.replace('img','fallback')}" style="--avatar-border:var(--primary)">${esc((g?.name||'G').slice(0,1))}</span>`}
function memberIsInGroupOn(m,groupId,date){return (m?.memberships||[]).some(mm=>mm.groupId===groupId&&(!mm.from||mm.from<=date)&&(!mm.to||mm.to>=date))}
function eventLiveMemberIds(e){if(Array.isArray(e.performerMemberIds)&&e.performerMemberIds.length)return e.performerMemberIds;return G.state.members.filter(m=>(e.groupIds||[]).some(g=>memberIsInGroupOn(m,g,e.date))).map(m=>m.id)}
memberRelevantEvents=function(memberId){return activeEvents().filter(e=>(e.benefits||[]).some(b=>b.memberId===memberId)||(e.type==='live'&&eventLiveMemberIds(e).includes(memberId)))};
memberStats=function(id){const ev=memberRelevantEvents(id).filter(e=>e.type!=='schedule'),pf=profileFirstLast(ev),chekiRows=chekiBenefits(ev).filter(x=>x.memberId===id),cheki=sum(chekiRows,x=>x.count),chekiEvents=new Set(chekiRows.map(x=>x.event.id)).size,liveSeen=ev.filter(e=>e.type==='live'&&eventLiveMemberIds(e).includes(id)).length;return{events:ev,eventCount:ev.length,cheki,chekiEvents,liveSeen,...pf}};

// Event photos include cheki images as a shared image asset.
eventPhotoAttachments=function(e){const ids=[...(e.attachments||[])];for(const b of e.benefits||[])for(const id of b.attachments||[])if(!ids.includes(id))ids.push(id);return ids.map(attachmentById).filter(Boolean).filter(a=>!!mediaURL(a.path))};

// List card: open first, edit only after opening.
eventCardHTML=function(e){const expired=scheduleExpired(e),days=eventWorkdays(e),travel=eventTravelShare(e),alloc=groupEventAlloc(e),photos=eventPhotoAttachments(e);return `<div class="event-card ${photos.length?'has-photo':''}">${eventCardPhotoHTML(e)}<div class="event-top"><div><div class="event-date">${esc(e.type==='schedule'?(e.scheduleAt?e.scheduleAt.replace('T',' '):fmtDate(e.date)):fmtDate(e.date))} ${e.important?'★':''}</div><h3>${esc(e.name)}</h3><div class="event-meta">${esc(e.type==='schedule'?(e.scheduleKind||'スケジュール'):typeById(e.type).name)}${e.status?` ・ ${esc(e.status)}`:''}${eventVenue(e)?`<br>${esc(eventVenue(e))}`:''}</div></div><div class="event-day">${e.type==='schedule'?'—':days.toFixed(2)}<small>${e.type==='schedule'?(expired?'終了':'予定'):travel?`+遠征 ${travel.toFixed(2)}`:'GEM Carat'}</small></div></div>${Object.keys(alloc).length?`<div class="alloc-row">${Object.entries(alloc).filter(([g])=>g!=='__unassigned').map(([g,d])=>`<span class="badge primary">${esc(groupById(g)?.name||'不明')} ${d.toFixed(2)}</span>`).join('')}</div>`:''}<div class="event-actions single"><button class="btn small" data-event-open="${e.id}">開く</button></div></div>`};
bindEventActions=function(){qsa('[data-event-open]').forEach(x=>x.onclick=()=>openEventDetail(x.dataset.eventOpen))};

function detailLaunchButton(id,kind,title,summaryId,extra=''){return `<button type="button" class="detail-launch ${extra}" id="${id}">${picto(kind)}<b>${title}</b><span id="${summaryId}"></span></button>`}
eventFormHTML=function(e){const features=G.state.settings.features,venueOpts='<option value="">会場未設定</option>'+G.state.venues.map(v=>`<option value="${v.id}" ${v.id===e.venueId?'selected':''}>${esc(v.name)}</option>`).join('')+`<option value="__custom" ${!e.venueId&&e.venueText?'selected':''}>自由入力</option>`;return `<div class="modal-head"><div><div class="guide-kicker">EVENT ENTRY</div><h2>${G.editingEventId?'現場を編集':'現場を登録'}</h2></div><button class="close-btn" data-close>×</button></div><input type="hidden" id="eventId" value="${e.id||''}"><input type="hidden" id="eventCreatedAt" value="${esc(e.createdAt||'')}"><input type="hidden" id="eventTime" value="${esc(e.time||'')}"><input type="hidden" id="eventAttachmentsState" value='${esc(JSON.stringify(e.attachments||[]))}'><div class="entry-intro"><b>現場本体は短く、明細は必要なときだけ</b><span><em>*</em> の項目だけで登録できます。チェキ・支出・物販・写真等はアイコンから開きます。</span></div>${G.state.templates.length?`<div class="template-assist"><label class="field" style="margin:0"><span>いつもの入力を使う</span><div class="inline-action"><select id="templateSelect"><option value="">テンプレートを使わない</option>${G.state.templates.map(t=>`<option value="${t.id}">${esc(t.name)}</option>`).join('')}</select><button class="btn small" id="applyTemplateBtn">適用</button></div></label></div>`:''}<section class="form-section"><div class="form-section-head"><span class="step-no">1</span><div><b>基本情報</b><small>現場を特定する最低限の情報</small></div></div><div class="form-grid"><label class="field"><span class="req">日付</span><input id="eventDate" type="date" value="${e.date||todayISO()}"></label><label class="field full"><span class="req">現場名</span><input id="eventName" type="text" value="${esc(e.name||'')}" placeholder="例：○○ツアー 東京公演" autocomplete="off" autocapitalize="none" spellcheck="false"></label><label class="field"><span class="req">現場種別</span><select id="eventType">${TYPES.map(t=>`<option value="${t.id}" ${t.id===e.type?'selected':''}>${esc(t.name)}</option>`).join('')}</select><div class="hint" id="eventTypeHelp"></div></label><label class="field" id="statusField"><span>ステータス</span><select id="eventStatus">${STATUS.map(s=>`<option ${s===(e.status||'確定予定')?'selected':''}>${s}</option>`).join('')}</select></label></div></section><section class="form-section"><div class="form-section-head"><span class="step-no">2</span><div><b>出演・会場</b><small>誰の、どこで行われる現場か</small></div></div><div class="form-grid"><div class="field full"><span>グループ</span>${groupCheckHTML(e.groupIds||[])}</div><label class="field full"><span>会場</span><select id="eventVenue">${venueOpts}</select><input id="eventVenueText" class="${!e.venueId&&e.venueText?'':'hidden'}" style="margin-top:6px" value="${esc(e.venueText||'')}" placeholder="会場名を自由入力"></label><label class="switch-row field full"><div class="text"><b>重要現場</b><small>ホームで目立つ位置に表示</small></div><span class="switch"><input type="checkbox" id="eventImportant" ${e.important?'checked':''}><i></i></span></label></div></section><section class="form-section"><div class="form-section-head"><span class="step-no">3</span><div><b>現場別情報</b><small>アイコンをタップして明細を入力</small></div></div><div id="typeSpecific"></div><div class="detail-launch-grid" id="detailLaunchGrid">${detailLaunchButton('openBenefitManager','cheki','チェキ・特典明細','benefitLaunchSummary','accent')}${detailLaunchButton('openExpenseManager','wallet','支出明細','expenseLaunchSummary')}${detailLaunchButton('openMerchManager','merch','物販明細','merchLaunchSummary')}${features.attachments?detailLaunchButton('openPhotoManager','camera','写真','photoLaunchSummary'):''}${features.setlist?detailLaunchButton('openSetlistManager','record','セットリスト','setlistLaunchSummary'):''}</div></section>${(features.tags||features.notes)?`<section class="form-section optional-section"><div class="form-section-head"><span class="step-no optional">4</span><div><b>その他の記録（任意）</b><small>設定でONにした項目のみ</small></div></div>${features.tags?`<label class="field"><span>タグ</span><input id="eventTags" list="tagSuggestions" value="${esc((e.tags||[]).join(', '))}" placeholder="例：生誕, 遠征"><datalist id="tagSuggestions">${G.state.tags.map(t=>`<option value="${esc(t)}">`).join('')}</datalist></label>`:''}${features.notes?`<label class="field"><span>参考事項・意見</span><textarea id="eventNotes" placeholder="空欄で問題ありません。">${esc(e.notes||'')}</textarea></label>`:''}</section>`:''}${features.travel?`<section class="form-section optional-section"><div class="form-section-head"><span class="step-no optional">5</span><div><b>遠征（任意）</b><small>遠征でない場合はOFF</small></div></div><label class="switch-row"><div class="text"><b>この現場を遠征に含める</b></div><span class="switch"><input type="checkbox" id="travelToggle" ${e.travelEnabled?'checked':''}><i></i></span></label><div id="eventTravelBox"></div></section>`:''}<div class="panel flat"><button class="btn small" id="saveAsTemplateBtn">この入力をテンプレート化</button><div id="templateSaveBox" class="hidden" style="margin-top:8px"><div class="inline-action"><input id="templateNameInput" placeholder="テンプレート名"><button class="btn small" id="confirmTemplateSave">保存</button></div></div></div><div class="modal-foot"><button class="btn" data-close>取消</button><button class="btn primary" id="saveEventBtn">${G.editingEventId?'保存':'確定して登録'}</button></div>`}
currentEventFromForm=function(){const type=$('eventType').value,groupIds=qsa('#eventGroupChecks input:checked').map(x=>x.value),venueSel=$('eventVenue').value,seed=G.formSeedEvent||{},d=draftDetails();syncLinkedExpenses();return{id:$('eventId').value||uid('e'),date:$('eventDate').value,time:seed.time||'',name:$('eventName').value.trim(),type,status:type==='schedule'?'確定予定':$('eventStatus').value,groupIds,venueId:venueSel==='__custom'?'':venueSel,venueText:venueSel==='__custom'?$('eventVenueText').value.trim():'',important:$('eventImportant').checked,tags:G.state.settings.features.tags?($('eventTags')?.value||'').split(',').map(x=>x.trim()).filter(Boolean):(seed.tags||[]),seatNumber:$('seatNumber')?.value?.trim()??seed.seatNumber??'',queueNumber:$('queueNumber')?.value?.trim()??seed.queueNumber??'',benefits:d.benefits.map(b=>({...b,kind:type==='online_bingo'?'bingo':'cheki'})),expenses:type==='schedule'?[]:clone(d.expenses),merchItems:clone(d.merchItems),notes:$('eventNotes')?$('eventNotes').value:(seed.notes||''),attachments:[...d.attachments],setlist:G.state.settings.features.setlist?clone(d.setlist):(seed.setlist||[]),performerMemberIds:seed.performerMemberIds||[],travelEnabled:G.state.settings.features.travel?($('travelToggle')?.checked||false):!!seed.travelEnabled,travelId:G.state.settings.features.travel?($('eventTravelId')?.value||''):(seed.travelId||''),otherDays:Number($('otherDays')?.value)||0,otherCount:Number($('otherCount')?.value??1)||0,scheduleKind:$('scheduleKind')?.value||'',scheduleAt:$('scheduleAt')?.value||'',createdAt:$('eventCreatedAt').value||new Date().toISOString(),updatedAt:new Date().toISOString()}};

function manualExpenseCategories(){return EXPENSE_CATEGORIES.filter(c=>c!=='チェキ')}
expenseEditorHTML=function(x={},index=0){return `<details class="detail-collapse" data-draft-expense="${x.id||uid('x')}"><summary><span><b>${esc(x.category||'支出')} ${x.linkType?'<span class="linked-badge">自動連携</span>':''}</b><small>${esc(x.description||'')} ・ ${yen(x.amount)}</small></span></summary><div class="detail-collapse-body">${x.linkType?`<div class="warning-box">この明細は${x.linkType==='benefit'?'チェキ':'物販'}明細から自動生成されます。元の明細を編集してください。</div>`:`<label class="field"><span>費目</span><select data-de-cat>${manualExpenseCategories().map(c=>`<option ${c===(x.category||'チケット')?'selected':''}>${c}</option>`).join('')}</select><div class="hint">チェキ代はチェキ明細から自動登録します。</div></label><label class="field"><span>金額</span><input data-de-amount type="number" min="0" value="${Number(x.amount)||''}"></label><label class="field"><span>内容</span><input data-de-desc value="${esc(x.description||'')}"></label><button class="btn danger small" data-de-remove>削除</button>`}</div></details>`};

benefitEditorHTML=function(b={},index=0){const id=b.id||uid('b'),groupId=b.groupId||'',atts=b.attachments||[];return `<details class="detail-collapse" data-draft-benefit="${id}" ${index===0&&b.__new?'open':''}><summary><span><b>${esc(memberById(b.memberId)?.name||groupById(groupId)?.name||`明細 ${index+1}`)}</b><small>${b.part?`${esc(b.part)} ・ `:''}${Number(b.count)||0}${$('eventType')?.value==='online_bingo'?'枠':'枚'}${b.expenseEnabled&&b.unitPrice?` ・ ${yen(Number(b.count)*Number(b.unitPrice))}`:''}${atts.length?` ・ 画像${atts.length}枚`:''}</small></span></summary><div class="detail-collapse-body"><div class="form-grid"><label class="field"><span>グループ</span><select data-db-group>${groupOptions(groupId)}</select></label><label class="field"><span>メンバー</span><select data-db-member>${memberOptions(b.memberId||'',groupId,$('eventDate')?.value||'')}</select></label><label class="field"><span>${$('eventType')?.value==='online_bingo'?'枠数':'枚数'}</span><input data-db-count type="number" min="0" step="1" value="${Number(b.count)||0}"></label><label class="field"><span>撮影した部（任意）</span><input data-db-part value="${esc(b.part||'')}" placeholder="例：4部 / A枠"></label><label class="switch-row case-chip"><div class="text"><b>件数</b><small>大特典会等の基礎0.40Carat</small></div><span class="switch"><input data-db-case type="checkbox" ${b.case?'checked':''}><i></i></span></label></div><label class="switch-row"><div class="text"><b>チェキ代を支出へ反映</b><small>枚数×単価を支出明細と自動連携</small></div><span class="switch"><input data-db-expense type="checkbox" ${b.expenseEnabled?'checked':''}><i></i></span></label><label class="field"><span>1枚・1枠あたり単価</span><input data-db-unit type="number" min="0" step="1" value="${Number(b.unitPrice)||''}" placeholder="例：2000"></label>${G.state.settings.features.notes?`<label class="field"><span>メモ・エピソード</span><textarea data-db-note>${esc(b.note||'')}</textarea></label>`:''}${G.state.settings.features.attachments?`<input type="hidden" data-db-atts value='${esc(JSON.stringify(atts))}'><div class="benefit-image-strip" data-db-images>${benefitImagesHTML(atts)}</div><div class="cheki-image-actions"><button class="btn small" type="button" data-db-library>写真ライブラリ</button><button class="btn small" type="button" data-db-camera>カメラで撮影</button></div>`:''}<button class="btn danger small" type="button" data-db-remove>この明細を削除</button></div></details>`};
syncBenefitDraftFromUI=function(){if(!$('benefitDraftList'))return;draftDetails().benefits=qsa('[data-draft-benefit]',$('benefitDraftList')).map(r=>({id:r.dataset.draftBenefit,groupId:r.querySelector('[data-db-group]').value,memberId:r.querySelector('[data-db-member]').value,count:Number(r.querySelector('[data-db-count]').value)||0,part:r.querySelector('[data-db-part]')?.value?.trim()||'',case:r.querySelector('[data-db-case]').checked,kind:$('eventType').value==='online_bingo'?'bingo':'cheki',note:r.querySelector('[data-db-note]')?.value||'',attachments:(()=>{try{return JSON.parse(r.querySelector('[data-db-atts]')?.value||'[]')}catch{return[]}})(),expenseEnabled:r.querySelector('[data-db-expense]').checked,unitPrice:Number(r.querySelector('[data-db-unit]').value)||0,linkedExpenseId:''})).filter(b=>b.count>0||b.case||b.memberId)};
function openLibraryBatch(ctx={}){syncBenefitDraftFromUI();window.__GEMS_BATCH_CTX__=ctx;let input=$('gemsMultiPhotoInput');if(!input){input=document.createElement('input');input.id='gemsMultiPhotoInput';input.type='file';input.accept='image/*';input.multiple=true;document.body.appendChild(input);input.onchange=async()=>{try{const files=[...(input.files||[])].slice(0,4);if(!files.length)return;toast(`${files.length}枚を読み込み中…`);const rows=[];for(const f of files){const url=await fileToResizedDataURL(f,2000);if(url)rows.push({name:f.name||'photo.jpg',dataURL:url})}window.__GEMS_WEB_IMAGE_BATCH__=rows;native('save-web-image-batch',{...window.__GEMS_BATCH_CTX__,count:rows.length})}catch(e){toast('写真の読み込みに失敗しました')}finally{input.value=''}}}input.click()}
async function fileToResizedDataURL(file,maxSide=2000){const raw=await new Promise((res,rej)=>{const fr=new FileReader();fr.onload=()=>res(fr.result);fr.onerror=rej;fr.readAsDataURL(file)}),img=await new Promise((res,rej)=>{const im=new Image();im.onload=()=>res(im);im.onerror=rej;im.src=raw}),scale=Math.min(1,maxSide/Math.max(img.naturalWidth,img.naturalHeight)),w=Math.max(1,Math.round(img.naturalWidth*scale)),h=Math.max(1,Math.round(img.naturalHeight*scale)),c=document.createElement('canvas');c.width=w;c.height=h;c.getContext('2d').drawImage(img,0,0,w,h);return c.toDataURL('image/jpeg',.9)}
window.GEMS_GET_WEB_IMAGE_BATCH=()=>JSON.stringify(window.__GEMS_WEB_IMAGE_BATCH__||[]);window.GEMS_CLEAR_WEB_IMAGE_BATCH=()=>{window.__GEMS_WEB_IMAGE_BATCH__=[]};
function attachMetas(metas,ctx={}){for(const meta of metas||[]){if(!meta?.id)continue;if(!G.state.attachments.some(x=>x.id===meta.id))G.state.attachments.push(meta);if(ctx.target==='event-draft'){if(!draftDetails().attachments.includes(meta.id))draftDetails().attachments.push(meta.id)}else if(ctx.target==='benefit-draft'){const b=draftDetails().benefits.find(x=>x.id===ctx.benefitId);if(b&&!b.attachments.includes(meta.id))b.attachments.push(meta.id)}}persist();if($('photoDraftBody'))renderPhotoDraft();if($('benefitDraftList'))renderBenefitManager();updateDetailLaunchSummaries();toast(`${(metas||[]).length}枚追加しました`)}
window.GEMS_NATIVE_BATCH_ATTACHMENTS=(metas,ctx)=>attachMetas(metas,ctx||{});
window.GEMS_NATIVE_EDIT_CROP_START=(payload,ctx)=>openV8Cropper(payload,ctx||{});
function openV8Cropper(payload,ctx={}){closeCropper();const spec=cropSpec(ctx,payload);G.crop={payload,ctx,spec,img:null,zoom:1,offX:0,offY:0,last:null,pinch:null};const ov=document.createElement('div');ov.id='cropOverlay';ov.className='crop-overlay';ov.innerHTML=`<div class="crop-sheet"><div class="modal-head"><div><div class="guide-kicker">CROP</div><h2>表示範囲を編集</h2></div><button class="close-btn" id="cropClose">×</button></div><div class="panel crop-wrap"><div class="hint" style="margin-bottom:8px">点線の枠が保存される範囲です。画像を動かし、ピンチまたはスライダーで拡大してください。</div><div class="crop-stage"><canvas id="cropCanvas" width="${spec.w}" height="${spec.h}"></canvas></div><div class="crop-toolbar"><span class="hint">縮小</span><input id="cropZoom" type="range" min="1" max="4" step="0.01" value="1"><span class="hint">拡大</span></div></div><div class="modal-foot"><button class="btn" id="cropReset">リセット</button><button class="btn" id="cropCancel">キャンセル</button><button class="btn primary" id="cropConfirm">切り抜きを保存</button></div></div>`;document.body.appendChild(ov);$('cropClose').onclick=$('cropCancel').onclick=closeCropper;const img=new Image();G.crop.img=img;img.onload=()=>{drawCrop();bindCropCanvas()};img.onerror=()=>toast('画像を読み込めませんでした');img.src=payload.dataURL;$('cropZoom').oninput=()=>{G.crop.zoom=Number($('cropZoom').value)||1;drawCrop()};$('cropReset').onclick=()=>{G.crop.zoom=1;G.crop.offX=0;G.crop.offY=0;$('cropZoom').value='1';drawCrop()};$('cropConfirm').onclick=()=>{const c=$('cropCanvas'),a=attachmentById(ctx.attachmentId);if(!a)return;const mini=document.createElement('canvas'),max=720,ratio=c.width/c.height;mini.width=Math.min(max,c.width);mini.height=Math.round(mini.width/ratio);mini.getContext('2d').drawImage(c,0,0,mini.width,mini.height);a.thumbDataURL=mini.toDataURL('image/jpeg',.82);persist();closeCropper();if($('photoDraftBody'))renderPhotoDraft();if($('benefitDraftList'))renderBenefitManager();renderAll();toast('切り抜きを保存しました')}}

function bindBenefitDraft(){qsa('[data-db-group]').forEach(sel=>sel.onchange=()=>{const r=sel.closest('[data-draft-benefit]'),m=r.querySelector('[data-db-member]'),cur=m.value;m.innerHTML=memberOptions(cur,sel.value,$('eventDate')?.value||'')});qsa('[data-db-remove]').forEach(b=>b.onclick=()=>confirmModal('チェキ明細を削除','このチェキ明細を削除しますか？',()=>{b.closest('[data-draft-benefit]').remove();syncBenefitDraftFromUI()},{danger:true}));qsa('[data-db-library]').forEach(b=>b.onclick=()=>{syncBenefitDraftFromUI();openLibraryBatch({target:'benefit-draft',benefitId:b.closest('[data-draft-benefit]').dataset.draftBenefit})});qsa('[data-db-camera]').forEach(b=>b.onclick=()=>{syncBenefitDraftFromUI();native('capture-image',{target:'benefit-draft',benefitId:b.closest('[data-draft-benefit]').dataset.draftBenefit})});qsa('[data-att-open]',$('subModalSheet')).forEach(b=>b.onclick=()=>native('open-attachment',{id:b.dataset.attOpen}))}
openBenefitManager=function(){setSubModal(`<div class="modal-head"><div><div class="guide-kicker">CHEKI / BENEFIT</div><h2>チェキ・特典明細</h2></div><button class="close-btn" id="benefitDraftClose">×</button></div><div class="hint prominent-hint">1件ずつ折りたたんで管理します。2件目以降は下の大きなボタンから追加できます。</div><div id="benefitDraftList"></div><button class="btn primary cheki-add-main" id="addDraftBenefit">＋ 別のチェキ明細を追加</button><div class="modal-foot"><button class="btn primary" id="benefitDraftDone">完了</button></div>`);renderBenefitManager();const done=()=>{syncBenefitDraftFromUI();closeSubModal();updateDetailLaunchSummaries()};$('benefitDraftClose').onclick=done;$('benefitDraftDone').onclick=done;$('addDraftBenefit').onclick=()=>{syncBenefitDraftFromUI();draftDetails().benefits.push({id:uid('b'),groupId:(qsa('#eventGroupChecks input:checked')[0]?.value||''),memberId:'',count:0,part:'',case:false,kind:'cheki',note:'',attachments:[],expenseEnabled:false,unitPrice:0,__new:true});renderBenefitManager();qsa('[data-draft-benefit]').at(-1)?.setAttribute('open','')}};

renderPhotoDraft=function(){if(!$('photoDraftBody'))return;const ids=draftDetails().attachments||[];$('photoDraftBody').innerHTML=ids.length?`<div class="photo-batch-grid">${ids.map((id,i)=>{const a=attachmentById(id),src=a?mediaURL(a.path):'';return `<div class="photo-edit-card"><div class="preview">${src?`<img src="${esc(src)}">`:''}</div><div class="photo-edit-actions"><button class="btn small" data-photo-open="${id}">画像を開く</button><button class="btn small" data-photo-crop="${id}">切り抜き</button><button class="btn danger small" data-dp-remove="${id}">外す</button></div></div>`}).join('')}</div>`:'<div class="empty">写真はまだありません</div>';qsa('[data-photo-open]').forEach(b=>b.onclick=()=>native('open-attachment',{id:b.dataset.photoOpen}));qsa('[data-photo-crop]').forEach(b=>b.onclick=()=>native('edit-attachment-crop',{id:b.dataset.photoCrop,ratio:'4:3'}));qsa('[data-dp-remove]').forEach(b=>b.onclick=()=>{draftDetails().attachments=draftDetails().attachments.filter(x=>x!==b.dataset.dpRemove);renderPhotoDraft();updateDetailLaunchSummaries()})};
openEventPhotoManager=function(){setSubModal(`<div class="modal-head"><div><div class="guide-kicker">PHOTOS</div><h2>写真</h2></div><button class="close-btn" id="photoDraftClose">×</button></div><div class="hint prominent-hint">写真を先に追加し、必要な画像だけ「切り抜き」で表示範囲を整えます。</div><div class="photo-manager-actions"><button class="btn primary" id="photoBatchAdd">写真ライブラリ（最大4枚）</button><button class="btn" id="photoCameraAdd">カメラで撮影</button></div><div class="batch-progress">1回の追加で最大4枚。追加後も何度でも写真を足せます。</div><div id="photoDraftBody"></div><div class="modal-foot"><button class="btn primary" id="photoDraftDone">完了</button></div>`);renderPhotoDraft();$('photoBatchAdd').onclick=()=>openLibraryBatch({target:'event-draft'});$('photoCameraAdd').onclick=()=>native('capture-image',{target:'event-draft'});$('photoDraftClose').onclick=$('photoDraftDone').onclick=()=>{closeSubModal();updateDetailLaunchSummaries()}};

openEventGallery=function(e,start=0){const atts=eventPhotoAttachments(e);if(!atts.length){toast('画像はありません');return}G.galleryIndex=Math.max(0,Math.min(start,atts.length-1));const render=()=>{const a=atts[G.galleryIndex],src=mediaURL(a.path);$('galleryBody').innerHTML=`<div class="gallery-hero"><img src="${esc(src)}" alt="画像"></div><div class="gallery-controls"><button class="btn small" id="galleryPrev">←</button><span class="gallery-count">${G.galleryIndex+1} / ${atts.length}</span><button class="btn small" id="galleryNext">→</button></div><div class="gallery-thumbs">${atts.map((x,i)=>`<button class="gallery-thumb ${i===G.galleryIndex?'active':''}" data-gallery-i="${i}"><img src="${esc(mediaURL(x.path))}"></button>`).join('')}</div><button class="btn" id="galleryOpenOriginal">画像を開く</button>`;$('galleryPrev').onclick=()=>{G.galleryIndex=(G.galleryIndex-1+atts.length)%atts.length;render()};$('galleryNext').onclick=()=>{G.galleryIndex=(G.galleryIndex+1)%atts.length;render()};qsa('[data-gallery-i]').forEach(b=>b.onclick=()=>{G.galleryIndex=Number(b.dataset.galleryI);render()});$('galleryOpenOriginal').onclick=()=>native('open-attachment',{id:a.id})};setSubModal(`<div class="modal-head"><h2>${esc(e.name)} / 画像</h2><button class="close-btn" id="galleryClose">×</button></div><div id="galleryBody"></div>`);$('galleryClose').onclick=closeSubModal;render()};
eventDetailPhotosHTML=function(e){const atts=eventPhotoAttachments(e);if(!atts.length)return'';return `<div class="panel photo-summary-panel"><div class="share-top"><h3>写真・チェキ画像</h3><button class="btn small" id="openEventGalleryBtn">すべて見る（${atts.length}）</button></div><div class="photo-summary-strip">${atts.slice(0,5).map((a,i)=>`<button class="event-photo-btn" data-gallery-open="${i}"><img src="${esc(mediaURL(a.path))}"></button>`).join('')}</div></div>`};
eventBenefitSummaryHTML=function(e){if(!e.benefits?.length)return'';return `<div class="panel"><div class="share-top"><h3>チェキ・特典明細</h3><b>${sum(e.benefits,b=>Number(b.count)||0)}${e.type==='online_bingo'?'枠':'枚'}</b></div>${e.benefits.map(b=>{const m=memberById(b.memberId);return `<div class="master-row"><div class="member-inline">${m?memberAvatarHTML(m,'member-mini-avatar'):''}<div><b>${esc(m?.name||groupById(resolveBenefitGroup(b,e))?.name||'')}</b><small>${b.part?`${esc(b.part)} / `:''}${b.count}${b.kind==='bingo'?'枠':'枚'}${b.expenseEnabled&&b.unitPrice?` / ${yen(Number(b.count)*Number(b.unitPrice))}`:''}${b.attachments?.length?` / 画像${b.attachments.length}枚`:''}</small></div></div>${b.kind!=='bingo'?`<button class="btn small" data-cheki-detail="${b.id}">開く</button>`:''}</div>`}).join('')}</div>`};
openChekiDetail=function(eventId,benefitId){const e=G.state.events.find(x=>x.id===eventId),b=e?.benefits?.find(x=>x.id===benefitId);if(!e||!b)return;const m=memberById(b.memberId),ids=b.attachments||[];setModal(`<div class="modal-head"><h2>チェキ詳細</h2><button class="close-btn" data-close>×</button></div><div class="panel"><div class="profile-hero">${m?memberAvatarHTML(m):''}<div><div class="event-date">${esc(fmtDate(e.date))}</div><h2 style="margin:4px 0">${esc(m?.name||'メンバー未設定')}</h2><div class="event-meta">${esc(e.name)} / ${b.part?`${esc(b.part)} / `:''}${Number(b.count)||0}枚</div></div></div></div>${b.note?`<div class="panel"><h3>メモ・エピソード</h3><div class="detail-text">${esc(b.note)}</div></div>`:''}<div class="panel"><h3>チェキ画像</h3><div class="cheki-gallery">${ids.length?benefitImagesHTML(ids):'<div class="empty">画像なし</div>'}</div></div><div class="modal-foot"><button class="btn" data-close>閉じる</button><button class="btn" id="chekiShareBtn">共有</button><button class="btn primary" id="chekiEventBtn">現場を開く</button></div>`);qsa('[data-close]').forEach(x=>x.onclick=closeModal);qsa('[data-att-open]').forEach(x=>x.onclick=()=>native('open-attachment',{id:x.dataset.attOpen}));$('chekiShareBtn').onclick=()=>openShareModal('チェキを共有',shareTextCheki(e,b),ids,chatLogCheki(e,b));$('chekiEventBtn').onclick=()=>openEventDetail(eventId)};

function eventDetailActionCards(e){const bcount=sum(e.benefits||[],b=>Number(b.count)||0),mcount=sum(e.merchItems||[],m=>Number(m.qty)||0),photos=eventPhotoAttachments(e).length,expense=expenseTotal(e);return `<div class="panel"><h3>明細</h3>${e.benefits?.length?`<div class="detail-action-card">${picto('cheki')}<div><b>チェキ・特典</b><small>${bcount}${e.type==='online_bingo'?'枠':'枚'} / ${e.benefits.length}明細</small></div><button class="btn small" id="detailOpenBenefits">開く</button></div>`:''}${e.expenses?.length?`<div class="detail-action-card">${picto('wallet')}<div><b>支出</b><small>${e.expenses.length}明細 / ${yen(expense)}</small></div><button class="btn small" id="detailOpenExpenses">開く</button></div>`:''}${e.merchItems?.length?`<div class="detail-action-card">${picto('merch')}<div><b>物販</b><small>${mcount}点</small></div><button class="btn small" id="detailOpenMerch">開く</button></div>`:''}${photos?`<div class="detail-action-card">${picto('camera')}<div><b>写真・チェキ画像</b><small>${photos}枚</small></div><button class="btn small" id="detailOpenPhotos">開く</button></div>`:''}${e.setlist?.length?`<div class="detail-action-card">${picto('record')}<div><b>セットリスト</b><small>${e.setlist.length}曲</small></div><button class="btn small" id="detailOpenSetlist">開く</button></div>`:''}</div>`}
function openReadOnlyExpense(e){setSubModal(`<div class="modal-head"><h2>支出明細</h2><button class="close-btn" data-close>×</button></div><div class="panel"><div class="share-top"><b>合計</b><strong>${yen(expenseTotal(e))}</strong></div></div>${(e.expenses||[]).map(x=>`<div class="master-row"><div><b>${esc(x.category)}</b><small>${esc(x.description||'')}</small></div><strong>${yen(x.amount)}</strong></div>`).join('')||'<div class="empty">支出なし</div>'}`);qsa('[data-close]').forEach(x=>x.onclick=closeSubModal)}
function openReadOnlyMerch(e){setSubModal(`<div class="modal-head"><h2>物販明細</h2><button class="close-btn" data-close>×</button></div>${(e.merchItems||[]).map(x=>`<div class="master-row"><div><b>${esc(x.name||merchProductById(x.productId)?.name||'商品')}</b><small>${Number(x.qty)||0}点</small></div><strong>${yen(Number(x.qty||0)*Number(x.unitPrice||0))}</strong></div>`).join('')||'<div class="empty">物販なし</div>'}`);qsa('[data-close]').forEach(x=>x.onclick=closeSubModal)}
function openReadOnlySetlist(e){setSubModal(`<div class="modal-head"><h2>セットリスト</h2><button class="close-btn" data-close>×</button></div><div class="panel"><ol>${(e.setlist||[]).slice().sort((a,b)=>a.order-b.order).map(r=>`<li>${esc(songById(r.songId)?.title||r.songTitle||'')} ${r.encore?'<span class="badge">ENCORE</span>':''}</li>`).join('')}</ol></div>`);qsa('[data-close]').forEach(x=>x.onclick=closeSubModal)}
openEventDetail=function(id){const e=G.state.events.find(x=>x.id===id);if(!e)return;const ga=groupEventAlloc(e),travel=eventTravelShare(e),travelObj=e.travelId?G.state.travels.find(t=>t.id===e.travelId):null;setModal(`<div class="modal-head"><h2>${e.type==='schedule'?'スケジュール':'現場'}</h2><button class="close-btn" data-close>×</button></div><div class="panel">${e.type!=='schedule'?eventDetailHeroHTML(e):''}<div class="event-date">${esc(e.type==='schedule'?(e.scheduleAt||e.date).replace('T',' '):fmtDate(e.date))}</div><h2 style="margin:4px 0 7px">${e.important?'★ ':''}${esc(e.name)}</h2><div class="chips"><span class="badge">${esc(typeById(e.type).name)}</span>${e.status?`<span class="badge">${esc(e.status)}</span>`:''}${(e.tags||[]).map(t=>`<span class="badge primary">${esc(t)}</span>`).join('')}</div></div>${e.type!=='schedule'?`<div class="detail-grid"><div class="detail-item"><span>GEM Carat</span><b>${eventWorkdays(e).toFixed(2)}</b></div><div class="detail-item"><span>遠征Carat配分</span><b>${travel.toFixed(2)}</b></div><div class="detail-item"><span>合計Carat</span><b>${eventTotalDays(e).toFixed(2)}</b></div><div class="detail-item"><span>支出</span><b>${yen(expenseTotal(e))}</b></div><div class="detail-item"><span>グループ</span><b>${esc(eventGroupNames(e))}</b></div><div class="detail-item"><span>会場</span><b>${esc(eventVenue(e)||'—')}</b></div>${e.seatNumber?`<div class="detail-item"><span>席番号</span><b>${esc(e.seatNumber)}</b></div>`:''}${e.queueNumber?`<div class="detail-item"><span>整番</span><b>${esc(e.queueNumber)}</b></div>`:''}</div>${eventDetailActionCards(e)}`:''}${Object.keys(ga).length?`<div class="panel"><h3>グループ別GEM Carat</h3>${Object.entries(ga).filter(([g])=>g!=='__unassigned').map(([g,d])=>`<div class="share-top"><b>${esc(groupById(g)?.name||'不明')}</b><span>${d.toFixed(2)}</span></div>`).join('')}</div>`:''}${travelObj?`<div class="panel"><h3>遠征</h3><div class="detail-text">${esc(travelObj.name)}\n遠征Carat ${travelWorkdays(travelObj).toFixed(2)} / この現場への配分 ${travel.toFixed(2)}</div></div>`:''}${e.notes?`<div class="panel"><h3>参考事項・意見</h3><div class="detail-text">${esc(e.notes)}</div></div>`:''}<div class="modal-foot"><button class="btn" data-close>閉じる</button>${e.type!=='schedule'?'<button class="btn" id="detailPdfBtn">PDF・印刷</button>':''}<button class="btn" id="detailShareBtn">共有</button><button class="btn danger" id="detailDeleteBtn">削除</button><button class="btn primary" id="detailEditBtn">編集</button></div>`);qsa('[data-close]').forEach(b=>b.onclick=closeModal);$('detailEditBtn').onclick=()=>{closeModal();setTimeout(()=>openEventForm(id),0)};$('detailDeleteBtn').onclick=()=>{closeModal();setTimeout(()=>deleteEvent(id),0)};$('detailShareBtn').onclick=()=>openShareModal(e.type==='schedule'?'予定を共有':'現場を共有',shareTextEvent(e),[],chatLogEvent(e));if($('detailPdfBtn'))$('detailPdfBtn').onclick=()=>openEventPdfOptions(e.id);if($('detailOpenBenefits'))$('detailOpenBenefits').onclick=()=>{qsa('[data-cheki-detail]');setSubModal(`<div class="modal-head"><h2>チェキ・特典明細</h2><button class="close-btn" data-close>×</button></div>${eventBenefitSummaryHTML(e)}`);qsa('[data-close]').forEach(x=>x.onclick=closeSubModal);qsa('[data-cheki-detail]').forEach(b=>b.onclick=()=>openChekiDetail(e.id,b.dataset.chekiDetail))};if($('detailOpenExpenses'))$('detailOpenExpenses').onclick=()=>openReadOnlyExpense(e);if($('detailOpenMerch'))$('detailOpenMerch').onclick=()=>openReadOnlyMerch(e);if($('detailOpenPhotos'))$('detailOpenPhotos').onclick=()=>openEventGallery(e,0);if($('detailOpenSetlist'))$('detailOpenSetlist').onclick=()=>openReadOnlySetlist(e);setTimeout(startSlideshows,30)};

// Profiles and icons.
function setupHomeProfilesPanel(){if($('homeProfilesPanel'))return;const imp=$('importantPanel');if(!imp)return;imp.insertAdjacentHTML('beforebegin',`<div class="panel" id="homeProfilesPanel"><div class="share-top"><div><h3>推し・グループ</h3><div class="hint">アイコンをタップすると基本情報を開きます。</div></div><button class="btn small" id="homeProfilesAll">すべて見る</button></div><div class="home-profile-strip" id="homeProfileStrip"></div></div>`);$('homeProfilesAll').onclick=()=>{showView('settings');setTimeout(()=>{selectSettingsTab('master');selectSettingsSub('groups')},50)}}
function renderHomeProfiles(){setupHomeProfilesPanel();if(!$('homeProfileStrip'))return;const fav=G.state.members.filter(m=>m.favorite&&m.active!==false),groups=G.state.groups.filter(g=>g.active!==false);const rows=[...fav.slice(0,8).map(m=>({kind:'member',obj:m})),...groups.slice(0,8).map(g=>({kind:'group',obj:g}))].slice(0,12);$('homeProfileStrip').innerHTML=rows.length?rows.map(r=>{if(r.kind==='member'){const m=r.obj;return `<button class="home-profile-card" data-home-member="${m.id}">${memberAvatarHTML(m,'profile-mini-img')}<b>${esc(m.name)}</b><small>メンバー</small></button>`}const g=r.obj;return `<button class="home-profile-card" data-home-group="${g.id}">${groupAvatarHTML(g,'profile-mini-img')}<b>${esc(g.name)}</b><small>グループ</small></button>`}).join(''):'<div class="empty">推し・グループを設定するとここに表示されます</div>';qsa('[data-home-member]').forEach(b=>b.onclick=()=>openMemberProfile(b.dataset.homeMember));qsa('[data-home-group]').forEach(b=>b.onclick=()=>openGroupProfile(b.dataset.homeGroup))}
const _v8RenderHome=renderHome;renderHome=function(){_v8RenderHome();renderHomeProfiles()};
function profileIconTap(kind,id){setSubModal(`<div class="modal-head"><h2>アイコン画像</h2><button class="close-btn" data-close>×</button></div><div class="panel"><div class="hint prominent-hint">1:1に切り抜いてアイコンとして保存します。</div><button class="btn primary block" id="profileIconLibrary">写真ライブラリから選ぶ</button><button class="btn block" id="profileIconCamera" style="margin-top:8px">カメラで撮影</button></div>`);qsa('[data-close]').forEach(x=>x.onclick=closeSubModal);$('profileIconLibrary').onclick=()=>{closeSubModal();native('pick-photo',{role:kind==='member'?'member-icon':'group-icon',entityId:id,ratio:'1:1'})};$('profileIconCamera').onclick=()=>{closeSubModal();native('capture-profile-icon',{role:kind==='member'?'member-icon':'group-icon',entityId:id,ratio:'1:1'})}}
openMemberProfile=function(id){const m=memberById(id);if(!m)return;const st=memberStats(id),c=memberColorFor(m),aff=(m.memberships||[]).map(mm=>groupById(mm.groupId)?.name).filter(Boolean).join(' / '),chekiRows=chekiBenefits(st.events).filter(x=>x.memberId===id).sort((a,b)=>b.event.date.localeCompare(a.event.date));setModal(`<div class="modal-head"><h2>メンバー基本情報</h2><button class="close-btn" data-close>×</button></div><div class="panel"><div class="profile-hero"><button class="profile-avatar-btn" id="memberProfileIcon">${memberAvatarHTML(m)}</button><div><h2 style="margin:0">${esc(m.name)} ${m.favorite?'★':''}</h2><div class="profile-meta">${c?`<span class="badge"><span class="member-color-dot" style="background:${esc(c.color)}"></span>${esc(c.name)}</span>`:''}${m.birthday?`<span class="badge">誕生日 ${esc(m.birthday)}</span>`:''}<span class="badge">${esc(aff||'所属未設定')}</span></div></div></div>${m.notes?`<div class="detail-text" style="margin-top:12px">${esc(m.notes)}</div>`:''}</div><div class="profile-stat-grid"><div class="profile-stat"><span>関連GEM</span><b>${st.eventCount}</b></div><div class="profile-stat"><span>会った・見たGEM</span><b>${st.liveSeen}回</b></div><div class="profile-stat"><span>チェキ参加現場</span><b>${st.chekiEvents}回</b></div><div class="profile-stat"><span>通算チェキ</span><b>${st.cheki}枚</b></div><div class="profile-stat"><span>初回記録</span><b style="font-size:14px">${st.first?fmtDateShort(st.first):'—'}</b></div><div class="profile-stat"><span>最終記録</span><b style="font-size:14px">${st.last?fmtDateShort(st.last):'—'}</b></div></div><div class="panel"><h3>チェキ履歴</h3>${chekiRows.length?chekiRows.map(r=>`<div class="master-row"><div><b>${esc(fmtDateShort(r.event.date))} ${esc(r.event.name)}</b><small>${r.benefit.part?`${esc(r.benefit.part)} / `:''}${r.count}枚${r.benefit.note?` / ${esc(r.benefit.note.slice(0,40))}`:''}${r.benefit.attachments?.length?` / 画像${r.benefit.attachments.length}枚`:''}</small></div><button class="btn small" data-cheki-open="${r.event.id}|${r.benefit.id}">開く</button></div>`).join(''):'<div class="empty">チェキ記録なし</div>'}</div><div class="panel"><h3>GEM履歴</h3>${st.events.length?st.events.slice().sort((a,b)=>b.date.localeCompare(a.date)).map(e=>`<div class="master-row"><div><b>${esc(fmtDateShort(e.date))} ${esc(e.name)}</b><small>${e.type==='live'?'ライブ':esc(typeById(e.type).name)} / ${esc(eventVenue(e)||'')}</small></div><button class="btn small" data-event-open="${e.id}">開く</button></div>`).join(''):'<div class="empty">履歴なし</div>'}</div><div class="panel"><h3>エピソード</h3>${episodeHTML(st.events,id)}</div><div class="modal-foot"><button class="btn" data-close>閉じる</button><button class="btn" id="memberShareBtn">共有</button><button class="btn primary" id="memberEditBtn">編集</button></div>`);qsa('[data-close]').forEach(b=>b.onclick=closeModal);$('memberProfileIcon').onclick=()=>profileIconTap('member',id);qsa('[data-event-open]').forEach(b=>b.onclick=()=>openEventDetail(b.dataset.eventOpen));qsa('[data-cheki-open]').forEach(b=>b.onclick=()=>{const [eid,bid]=b.dataset.chekiOpen.split('|');openChekiDetail(eid,bid)});$('memberShareBtn').onclick=()=>openShareModal('メンバーを共有',shareTextMember(m,st),[],chatLogMember(m,st));$('memberEditBtn').onclick=()=>openMemberMaster(id)};
openGroupProfile=function(id){const g=groupById(id);if(!g)return;const st=groupStats(id),current=G.state.members.filter(m=>currentMemberInGroup(m,id)),past=G.state.members.filter(m=>(m.memberships||[]).some(mm=>mm.groupId===id)&&!currentMemberInGroup(m,id));setModal(`<div class="modal-head"><h2>グループ基本情報</h2><button class="close-btn" data-close>×</button></div><div class="panel"><div class="profile-hero"><button class="profile-avatar-btn" id="groupProfileIcon">${groupAvatarHTML(g)}</button><div><h2 style="margin:0">${esc(g.name)}</h2><div class="profile-meta"><span class="badge ${g.active===false?'':'primary'}">${g.active===false?'活動終了':'活動中'}</span>${g.startDate?`<span class="badge">${esc(g.startDate)}〜</span>`:''}</div></div></div>${g.notes?`<div class="detail-text" style="margin-top:12px">${esc(g.notes)}</div>`:''}</div><div class="profile-stat-grid"><div class="profile-stat"><span>現場件数</span><b>${st.eventCount.toFixed(0)}</b></div><div class="profile-stat"><span>GEM Carat</span><b>${st.eventDays.toFixed(2)}</b></div><div class="profile-stat"><span>遠征Carat</span><b>${st.travelDays.toFixed(2)}</b></div><div class="profile-stat"><span>チェキ</span><b>${st.cheki}枚</b></div></div><div class="panel"><h3>現在所属メンバー</h3>${current.length?current.map(memberMasterRow).join(''):'<div class="empty">なし</div>'}${past.length?`<h4 style="margin-top:13px">過去所属</h4>${past.map(memberMasterRow).join('')}`:''}</div><div class="panel"><h3>履歴</h3>${st.events.length?st.events.slice().sort((a,b)=>b.date.localeCompare(a.date)).map(e=>`<div class="master-row"><div><b>${esc(fmtDateShort(e.date))} ${esc(e.name)}</b><small>${esc(typeById(e.type).name)} / ${esc(eventVenue(e)||'')}</small></div><button class="btn small" data-event-open="${e.id}">開く</button></div>`).join(''):'<div class="empty">履歴なし</div>'}</div><div class="panel"><h3>エピソード</h3>${episodeHTML(st.events)}</div><div class="modal-foot"><button class="btn" data-close>閉じる</button><button class="btn" id="profileShareBtn">共有</button><button class="btn primary" id="profileEditBtn">編集</button></div>`);qsa('[data-close]').forEach(b=>b.onclick=closeModal);$('groupProfileIcon').onclick=()=>profileIconTap('group',id);qsa('[data-member-profile]').forEach(b=>b.onclick=()=>openMemberProfile(b.dataset.memberProfile));qsa('[data-member-edit]').forEach(b=>b.onclick=()=>openMemberMaster(b.dataset.memberEdit));qsa('[data-event-open]').forEach(b=>b.onclick=()=>openEventDetail(b.dataset.eventOpen));$('profileShareBtn').onclick=()=>openShareModal('グループを共有',shareTextGroup(g,st),[],chatLogGroup(g,st));$('profileEditBtn').onclick=()=>openGroupMaster(id)};

