function bindMembershipConfirm(){qsa('[data-mm-remove]').forEach(b=>b.onclick=()=>{const row=b.closest('.membership-row'),g=row?.querySelector('[data-mm-group]')?.value,name=groupById(g)?.name||'この所属履歴';confirmModal('所属履歴を削除',`${name} の所属履歴を入力画面から削除しますか？`,()=>row?.remove(),{danger:true})})}
const _v8OpenMemberMaster=openMemberMaster;openMemberMaster=function(id='',prefillGroupId=''){_v8OpenMemberMaster(id,prefillGroupId);setTimeout(()=>{bindMembershipConfirm();if($('addMembership')){const old=$('addMembership').onclick;$('addMembership').onclick=()=>{old?.();setTimeout(bindMembershipConfirm,0)}}},0)};

