const _v8Attach=window.GEMS_NATIVE_ATTACHMENT;window.GEMS_NATIVE_ATTACHMENT=function(meta,ctx={}){if(ctx.role==='member-icon'||ctx.role==='group-icon'){if(!meta?.id)return;if(!G.state.attachments.some(x=>x.id===meta.id))G.state.attachments.push(meta);if(ctx.role==='member-icon'){const m=memberById(ctx.entityId);if(m)m.iconAttachmentId=meta.id}else{const g=groupById(ctx.entityId);if(g)g.iconAttachmentId=meta.id}persist();renderAll();closeCropper();toast('アイコンを保存しました');return}_v8Attach(meta,ctx)};

// Analysis always starts on annual after launch.
const _v8Init=init;init=function(){_v8Init();G.analysisPeriod='year';if($('analysisPeriod'))$('analysisPeriod').value='year';if($('analysisYear'))$('analysisYear').value=now.getFullYear();renderAnalysis();setupV8Extras();updateBackButton()};
