function saveSavedChekiManager(){if(!G.savedChekiDraft)return;syncSavedChekiUI();const e=G.state.events.find(x=>x.id===G.savedChekiDraft.eventId);if(!e)return;e.benefits=clone(G.savedChekiDraft.benefits).map(b=>{delete b.__new;return b});rebuildBenefitExpenses(e);e.updatedAt=new Date().toISOString();persist();const id=e.id;G.savedChekiDraft=null;closeSubModal();renderAll();openEventDetail(id);toast('チェキ・特典明細を保存しました')}
