  // --- Better cropper: dotted fixed frame + explicit zoom / horizontal / vertical controls. ---
  function v81CropDraw(){const c=$('cropCanvas'),x=G.crop;if(!c||!x?.img?.naturalWidth)return;const ctx=c.getContext('2d'),iw=x.img.naturalWidth,ih=x.img.naturalHeight,base=Math.max(c.width/iw,c.height/ih),scale=base*x.zoom,sw=iw*scale,sh=ih*scale,maxX=Math.max(0,(sw-c.width)/2),maxY=Math.max(0,(sh-c.height)/2),px=Math.max(-100,Math.min(100,Number(x.posX)||0)),py=Math.max(-100,Math.min(100,Number(x.posY)||0)),left=(c.width-sw)/2-(px/100)*maxX,top=(c.height-sh)/2-(py/100)*maxY;ctx.clearRect(0,0,c.width,c.height);ctx.drawImage(x.img,left,top,sw,sh)}
  function v81CropBind(){const c=$('cropCanvas');if(!c)return;let drag=null;c.addEventListener('touchstart',e=>{if(e.touches.length===1){e.preventDefault();drag={x:e.touches[0].clientX,y:e.touches[0].clientY,px:G.crop.posX||0,py:G.crop.posY||0}}},{passive:false});c.addEventListener('touchmove',e=>{if(!drag||e.touches.length!==1)return;e.preventDefault();const r=c.getBoundingClientRect(),dx=(e.touches[0].clientX-drag.x)/Math.max(1,r.width)*200,dy=(e.touches[0].clientY-drag.y)/Math.max(1,r.height)*200;G.crop.posX=Math.max(-100,Math.min(100,drag.px-dx));G.crop.posY=Math.max(-100,Math.min(100,drag.py-dy));if($('cropPosX'))$('cropPosX').value=G.crop.posX;if($('cropPosY'))$('cropPosY').value=G.crop.posY;v81CropDraw()},{passive:false});c.addEventListener('touchend',()=>drag=null)}
  function v81OpenCropper(payload,ctx={}){closeCropper();const spec=cropSpec(ctx,payload);G.crop={payload,ctx,spec,img:null,zoom:1,posX:0,posY:0};const ov=document.createElement('div');ov.id='cropOverlay';ov.className='crop-overlay';ov.innerHTML=`<div class="crop-sheet"><div class="modal-head"><div><div class="guide-kicker">CROP</div><h2>切り抜き</h2></div><button class="close-btn" id="cropClose">×</button></div><div class="panel crop-wrap"><div class="hint" style="margin-bottom:8px">点線の内側が保存される範囲です。画像は指で動かすか、下のスライダーで微調整できます。</div><div class="crop-stage"><canvas id="cropCanvas" width="${spec.w}" height="${spec.h}"></canvas></div><div class="v81-crop-sliders"><div class="v81-crop-line"><b>縮小</b><input id="cropZoom" type="range" min="1" max="4" step="0.01" value="1"><b>拡大</b></div><div class="v81-crop-line"><b>左</b><input id="cropPosX" type="range" min="-100" max="100" step="1" value="0"><b>右</b></div><div class="v81-crop-line"><b>上</b><input id="cropPosY" type="range" min="-100" max="100" step="1" value="0"><b>下</b></div></div></div><div class="modal-foot"><button class="btn" id="cropReset">中央に戻す</button><button class="btn" id="cropCancel">キャンセル</button><button class="btn primary" id="cropConfirm">切り抜きを保存</button></div></div>`;document.body.appendChild(ov);$('cropClose').onclick=$('cropCancel').onclick=closeCropper;const img=new Image();G.crop.img=img;img.onload=()=>{v81CropDraw();v81CropBind()};img.onerror=()=>toast('画像を読み込めませんでした');img.src=payload.dataURL;$('cropZoom').oninput=()=>{G.crop.zoom=Number($('cropZoom').value)||1;v81CropDraw()};$('cropPosX').oninput=()=>{G.crop.posX=Number($('cropPosX').value)||0;v81CropDraw()};$('cropPosY').oninput=()=>{G.crop.posY=Number($('cropPosY').value)||0;v81CropDraw()};$('cropReset').onclick=()=>{G.crop.zoom=1;G.crop.posX=0;G.crop.posY=0;$('cropZoom').value='1';$('cropPosX').value='0';$('cropPosY').value='0';v81CropDraw()};$('cropConfirm').onclick=()=>{const c=$('cropCanvas'),a=attachmentById(ctx.attachmentId);if(!a)return;const mini=document.createElement('canvas'),max=720,ratio=c.width/c.height;mini.width=Math.min(max,c.width);mini.height=Math.round(mini.width/ratio);mini.getContext('2d').drawImage(c,0,0,mini.width,mini.height);a.thumbDataURL=mini.toDataURL('image/jpeg',.84);persist();closeCropper();if($('photoDraftBody'))renderPhotoDraft();if($('benefitDraftList'))renderBenefitManager();if($('savedChekiList'))window.GEMS801_RENDER_SAVED_CHEKI?.();renderAll();toast('切り抜きを保存しました')}}
  window.GEMS_NATIVE_EDIT_CROP_START=(payload,ctx)=>v81OpenCropper(payload,ctx||{});

  // --- Cheki manager safety lives inside the v8.0.1 cheki module to preserve strict-mode scope. ---
