/* ===== GEMS v8.1.3 minor stabilization ===== */
(function(){
  const V813_ROOT_VIEWS=new Set(['home','events','digest','analysis','settings']);

  // The top-left back button is for subordinate screens only.
  // Root tabs are navigated by the bottom tab bar, so a back button there is redundant/confusing.
  updateBackButton=function(){
    const b=$('gemsBackBtn');if(!b)return;
    const sub=$('subModalBackdrop'),modal=$('modalBackdrop');
    const overlays=(sub&&!sub.classList.contains('hidden'))||(modal&&!modal.classList.contains('hidden'));
    b.classList.toggle('hidden',!overlays&&V813_ROOT_VIEWS.has(currentViewName()));
  };
  const _v813ShowView=showView;
  showView=function(name,opts={}){
    const cur=currentViewName();
    if(V813_ROOT_VIEWS.has(cur)&&V813_ROOT_VIEWS.has(name))opts={...opts,noHistory:true};
    _v813ShowView(name,opts);updateBackButton();
  };

  // Event photos are capped at four in one event draft. This matches the manager label and
  // prevents a second batch/camera add from silently growing beyond the advertised maximum.
  const _v813Batch=window.GEMS_NATIVE_BATCH_ATTACHMENTS;
  window.GEMS_NATIVE_BATCH_ATTACHMENTS=function(metas,ctx={}){
    if(ctx.target==='event-draft'){
      const current=(draftDetails().attachments||[]).length,remaining=Math.max(0,4-current);
      if(!remaining){toast('写真は最大4枚です');renderPhotoDraft();return}
      const use=(metas||[]).slice(0,remaining);
      _v813Batch(use,ctx);
      if((metas||[]).length>use.length)toast(`写真は最大4枚です。${use.length}枚だけ追加しました`);
      return;
    }
    _v813Batch(metas,ctx);
  };
  const _v813OpenLibraryBatch=openLibraryBatch;
  openLibraryBatch=function(ctx={}){
    if(ctx.target==='event-draft'&&(draftDetails().attachments||[]).length>=4){toast('写真は最大4枚です');return}
    _v813OpenLibraryBatch(ctx);
  };
  const _v813RenderPhotoDraft=renderPhotoDraft;
  renderPhotoDraft=function(){
    _v813RenderPhotoDraft();
    const n=Math.min(4,(draftDetails().attachments||[]).length),full=n>=4;
    const progress=document.querySelector('#subModalSheet .batch-progress');
    if(progress)progress.textContent=`${n}/4枚登録済み。切り抜きは各サムネイルの「切り抜き」から任意で行います。`;
    const lib=$('photoBatchAdd'),cam=$('photoCameraAdd');
    [lib,cam].forEach(b=>{if(!b)return;b.disabled=full;b.setAttribute('aria-disabled',String(full))});
    if(lib)lib.textContent=full?'写真は4枚登録済み':'写真ライブラリ（最大4枚）';
    if(cam&&full)cam.textContent='カメラ（上限4枚）';
  };
  const _v813OpenPhotoManager=openEventPhotoManager;
  openEventPhotoManager=function(){_v813OpenPhotoManager();renderPhotoDraft()};

  // Keep all user-facing action wording aligned with Open -> Edit.
  const _v813RenderCalendarDay=renderCalendarDay;
  renderCalendarDay=function(ds){_v813RenderCalendarDay(ds);qsa('[data-cal-travel-open]').forEach(b=>b.textContent='開く')};

  updateBackButton();
})();
