  function v9FavoriteImagesHTML(m){const ids=m.favoriteImages||[];if(!ids.length)return '<div class="empty">お気に入り画像はまだありません</div>';const pages=[];for(let i=0;i<ids.length;i+=10)pages.push(ids.slice(i,i+10));return pages.map((page,pi)=>`<div class="v9-page ${pi===0?'active':''}" data-v9-page="memberFav" data-page="${pi}"><div class="v9-fav-grid">${page.map(id=>{const i=ids.indexOf(id),a=attachmentById(id),src=a?mediaURL(a.path):'';return `<div class="v9-fav-card">${src?`<button class="event-photo-btn" data-v9-fav-open="${id}"><img src="${esc(src)}" alt=""></button>`:'<div class="image-placeholder">画像</div>'}<div class="v9-order-actions"><button class="btn" data-v9-fav-left="${id}" ${i===0?'disabled':''}>←</button><button class="btn" data-v9-fav-right="${id}" ${i===ids.length-1?'disabled':''}>→</button><button class="btn danger" data-v9-fav-remove="${id}">×</button></div></div>`}).join('')}</div></div>`).join('')+(pages.length>1?`<div class="v9-pager" data-v9-pager="memberFav" data-current="0" data-total="${pages.length}"><button class="btn small" data-v9-prev>＜ 前へ</button><span class="v9-page-label">1 / ${pages.length}</span><button class="btn small" data-v9-next>次へ ＞</button></div>`:'')}
  function v9BindMemberProfile(m){
    qsa('[data-close]').forEach(b=>b.onclick=closeModal);$('memberProfileIcon')?.addEventListener('click',()=>profileIconTap('member',m.id));qsa('[data-event-open]').forEach(b=>b.onclick=()=>openEventDetail(b.dataset.eventOpen));qsa('[data-cheki-open]').forEach(b=>b.onclick=()=>{const [eid,bid]=b.dataset.chekiOpen.split('|');openChekiDetail(eid,bid)});v9BindPagers($('modal'));$('memberShareBtn')?.addEventListener('click',()=>{const st=memberStats(m.id);openShareModal('メンバーを共有',shareTextMember(m,st),[],chatLogMember(m,st))});$('memberEditBtn')?.addEventListener('click',()=>openMemberMaster(m.id));$('memberFavoriteAdd')?.addEventListener('click',()=>native('pick-image-attachment',{target:'member-favorite',memberId:m.id}));qsa('[data-v9-fav-open]').forEach(b=>b.onclick=()=>native('open-attachment',{id:b.dataset.v9FavOpen}));qsa('[data-v9-fav-left],[data-v9-fav-right]').forEach(b=>b.onclick=()=>{const id=b.dataset.v9FavLeft||b.dataset.v9FavRight,i=m.favoriteImages.indexOf(id);v9Move(m.favoriteImages,i,b.dataset.v9FavLeft?-1:1);persist();openMemberProfile(m.id)});qsa('[data-v9-fav-remove]').forEach(b=>b.onclick=()=>{m.favoriteImages=m.favoriteImages.filter(id=>id!==b.dataset.v9FavRemove);persist();openMemberProfile(m.id)});if($('memberXOpen')&&m.xId)$('memberXOpen').onclick=()=>window.open(`https://x.com/${encodeURIComponent(m.xId)}`,'_blank');if($('memberXFetch')&&m.xId)$('memberXFetch').onclick=()=>{const b=$('memberXFetch');b.disabled=true;b.textContent='取得中…';native('x-avatar-sync',{members:[{id:m.id,xId:m.xId,name:m.name}],mode:'single'})}
  }
  openMemberProfile=function(id){const m=memberById(id);if(!m)return;const st=memberStats(id),c=memberColorFor(m),aff=(m.memberships||[]).map(mm=>groupById(mm.groupId)?.name).filter(Boolean).join(' / '),chekiRows=chekiBenefits(st.events).filter(x=>x.memberId===id).sort((a,b)=>b.event.date.localeCompare(a.event.date)),events=st.events.slice().sort((a,b)=>b.date.localeCompare(a.date)),eps=v9EpisodeRows(st.events,id),favs=m.favoriteImages||[];setModal(`<div class="modal-head"><h2>メンバー基本情報</h2><button class="close-btn" data-close>×</button></div><div class="panel"><div class="profile-hero"><button class="profile-avatar-btn" id="memberProfileIcon">${memberAvatarHTML(m)}</button><div><h2 style="margin:0">${esc(m.name)} ${m.favorite?'★':''}</h2><div class="profile-meta">${c?`<span class="badge"><span class="member-color-dot" style="background:${esc(c.color)}"></span>${esc(c.name)}</span>`:''}${m.birthday?`<span class="badge">誕生日 ${esc(m.birthday)}</span>`:''}<span class="badge">${esc(aff||'所属未設定')}</span>${m.xId?`<span class="badge">@${esc(m.xId)}</span>`:''}</div></div></div>${m.notes?`<div class="detail-text" style="margin-top:12px">${esc(m.notes)}</div>`:''}${m.xId?'<div style="display:flex;gap:7px;margin-top:9px;flex-wrap:wrap"><button class="btn small" id="memberXOpen">Xプロフィールを開く</button><button class="btn primary small" id="memberXFetch">Xアイコンを取得</button></div>':''}</div><div class="profile-stat-grid"><div class="profile-stat"><span>関連GEM</span><b>${st.eventCount}</b></div><div class="profile-stat"><span>会った・見たGEM</span><b>${st.liveSeen}回</b></div><div class="profile-stat"><span>チェキ参加現場</span><b>${st.chekiEvents}回</b></div><div class="profile-stat"><span>通算チェキ</span><b>${st.cheki}枚</b></div><div class="profile-stat"><span>初回記録</span><b style="font-size:14px">${st.first?fmtDateShort(st.first):'—'}</b></div><div class="profile-stat"><span>最終記録</span><b style="font-size:14px">${st.last?fmtDateShort(st.last):'—'}</b></div></div><details class="v9-collapse"><summary><span>お気に入り画像　${favs.length}枚</span></summary><div class="v9-collapse-body"><button class="btn small" id="memberFavoriteAdd" style="margin:9px 0">＋ 画像を追加</button>${v9FavoriteImagesHTML(m)}</div></details><details class="v9-collapse"><summary><span>チェキ履歴　${chekiRows.length}件</span></summary><div class="v9-collapse-body">${v9PageRows(chekiRows,r=>`<div class="master-row"><div><b>${esc(fmtDateShort(r.event.date))} ${esc(r.event.name)}</b><small>${r.benefit.part?`${esc(r.benefit.part)} / `:''}${r.count}枚${r.benefit.note?` / ${esc(r.benefit.note.slice(0,40))}`:''}${r.benefit.attachments?.length?` / 画像${r.benefit.attachments.length}枚`:''}</small></div><button class="btn small" data-cheki-open="${r.event.id}|${r.benefit.id}">開く</button></div>`,10,'memberCheki')}</div></details><details class="v9-collapse"><summary><span>GEM履歴　${events.length}件</span></summary><div class="v9-collapse-body">${v9PageRows(events,e=>`<div class="master-row"><div><b>${esc(fmtDateShort(e.date))} ${esc(e.name)}</b><small>${esc(typeById(e.type).name)} / ${esc(eventVenue(e)||'')}</small></div><button class="btn small" data-event-open="${e.id}">開く</button></div>`,10,'memberEvents')}</div></details><details class="v9-collapse"><summary><span>エピソード　${eps.length}件</span></summary><div class="v9-collapse-body">${episodeHTML(st.events,id)}</div></details><div class="modal-foot"><button class="btn" data-close>閉じる</button><button class="btn" id="memberShareBtn">共有</button><button class="btn primary" id="memberEditBtn">編集</button></div>`);v9BindMemberProfile(m)};

  // member edit: persist X ID as a first-class field.
