  if(!G.v982WordingObserver){G.v982WordingObserver=new MutationObserver(()=>{clearTimeout(G.v982WordingTimer);G.v982WordingTimer=setTimeout(()=>v982ApplyWording(document.body),40)});document.addEventListener('DOMContentLoaded',()=>G.v982WordingObserver.observe(document.body,{childList:true,subtree:true,characterData:true}),{once:true})}
  const _v982RenderAllWording=renderAll;renderAll=function(){const r=_v982RenderAllWording();setTimeout(()=>v982ApplyWording(document.body),30);return r};
  function v9SetupDeveloperMenu(){if($('settingsPane_developer'))return;const tabs=$('settingsMidTabs');if(!tabs)return;tabs.insertAdjacentHTML('beforeend','<button class="settings-mid-btn" data-settings-mid="developer">開発者用メニュー</button>');const view=$('settingsView'),pane=document.createElement('div');pane.id='settingsPane_developer';pane.className='settings-pane';const xAll=G.state.members.filter(m=>m.xId).length,xSet=G.state.members.filter(m=>m.xId&&m.iconAttachmentId).length;pane.innerHTML=`<div class="panel"><div class="guide-kicker">DEVELOPER</div><h3>開発者用メニュー</h3><div class="hint">通常利用のデータを壊さず、検証・フィードバック整理を行います。</div></div><div class="v9-dev-card"><h4>Xプロフィールアイコン</h4><div class="hint">登録済みX IDから公開プロフィール画像を取得し、GEMS内へ保存します。取得済み ${xSet} / ${xAll}人。</div><div id="v9XAvatarStatus" class="v9-sync-status">必要なときだけ取得・更新できます。</div><div class="v9-dev-actions"><button class="btn primary" id="v9XAvatarMissing">未設定だけ一括取得</button><button class="btn" id="v9XAvatarAll">全員更新</button></div></div><div class="v9-dev-card"><h4>フィードバック管理</h4><div class="hint">保存済み ${(G.state.feedback||[]).length}件。チャッピーに渡せるMarkdownまたはJSONで出力できます。</div><div class="v9-dev-actions"><button class="btn" id="v9FbExportMd">Markdown出力</button><button class="btn" id="v9FbExportJson">JSON出力</button><button class="btn primary" id="v9FbChatGPT">チャッピーで分析</button><button class="btn danger" id="v9FbClear">全件削除</button></div></div><div class="v9-dev-card"><h4>文言カスタマイズ</h4><div class="hint">GEMSのボタン名・見出し・説明文など、表示上の言い回しだけを変更します。内部IDや登録データは変更しません。</div><button class="btn primary block" id="v9WordingEdit">文言を編集</button></div><div class="v9-dev-card"><h4>初期状態をプレビュー</h4><div class="hint">実データを削除せず、新規インストール直後の空状態を仮想表示します。終了すると元のデータへ戻ります。</div><button class="btn primary block" id="v9PreviewStart">初期状態をプレビュー</button></div>`;view.insertBefore(pane,view.querySelector('[style*="height:18px"]'));qsa('[data-settings-mid]').forEach(b=>b.onclick=()=>selectSettingsTab(b.dataset.settingsMid));$('v9XAvatarMissing').onclick=()=>v9StartXAvatarSync(true);$('v9XAvatarAll').onclick=()=>confirmModal('Xアイコンを全員更新',`X ID登録済み${xAll}人のプロフィール画像を再取得します。`,()=>v9StartXAvatarSync(false));$('v9FbExportMd').onclick=()=>native('export-feedback-md');$('v9FbExportJson').onclick=()=>native('export-feedback-json');$('v9FbChatGPT').onclick=()=>native('share-chatgpt',{text:v9FeedbackMarkdown()});$('v9FbClear').onclick=()=>confirmModal('フィードバックを削除',`保存済み${(G.state.feedback||[]).length}件を削除します。`,()=>{G.state.feedback=[];persist();renderSettings();toast('フィードバックを削除しました')},{danger:true});$('v9WordingEdit').onclick=v982OpenWordingEditor;$('v9PreviewStart').onclick=v9EnterPreview}

