/* ===== GEMS v9.0.2 patch: iOS input stability / landscape cheki ===== */
(function(){
  // Scriptable/WKWebView can stutter badly when the software keyboard is shown
  // inside a fixed+blurred+transformed sheet. Remove only the costly effects
  // while a text control has focus; tab/view animations remain intact.
  const isTypingControl=el=>!!el&&!!el.matches&&el.matches('input,textarea,[contenteditable="true"]');
  document.addEventListener('focusin',e=>{if(isTypingControl(e.target))document.body.classList.add('v902-keyboard')},true);
  document.addEventListener('focusout',()=>setTimeout(()=>{if(!isTypingControl(document.activeElement))document.body.classList.remove('v902-keyboard')},80),true);

  // No live processing is attached to eventName. Keep composition events entirely passive.
  const _v902OpenEventForm=openEventForm;
  openEventForm=function(id=''){
    _v902OpenEventForm(id);
    const name=$('eventName');
    if(name){
      name.oninput=null;name.onchange=null;name.onkeyup=null;name.onkeydown=null;
      name.setAttribute('autocomplete','off');name.setAttribute('autocapitalize','none');name.setAttribute('spellcheck','false');
    }
  };

  // Cheki crop supports both the physical LegacyScan Mini portrait ratio (54:86)
  // and the same card rotated to landscape (86:54), plus arbitrary rectangles.
  function v902CropDims(ratio){ratio=Math.max(.45,Math.min(2.25,Number(ratio)||1));return ratio>=1?{w:1200,h:Math.max(1,Math.round(1200/ratio))}:{w:Math.max(1,Math.round(1200*ratio)),h:1200}}
  function v902CropDraw(){const c=$('cropCanvas'),x=G.crop;if(!c||!x?.img?.naturalWidth)return;const ctx=c.getContext('2d'),iw=x.img.naturalWidth,ih=x.img.naturalHeight,base=Math.max(c.width/iw,c.height/ih),scale=base*x.zoom,sw=iw*scale,sh=ih*scale;let left=(c.width-sw)/2+(x.posX||0)/100*Math.max(0,sw-c.width)/2,top=(c.height-sh)/2+(x.posY||0)/100*Math.max(0,sh-c.height)/2;left=Math.min(0,Math.max(c.width-sw,left));top=Math.min(0,Math.max(c.height-sh,top));ctx.clearRect(0,0,c.width,c.height);ctx.drawImage(x.img,left,top,sw,sh)}
  function v902CropBind(){const c=$('cropCanvas');if(!c)return;const factor=()=>c.width/Math.max(1,c.getBoundingClientRect().width);let drag=null,pinch=null;c.addEventListener('touchstart',e=>{e.preventDefault();if(e.touches.length===1)drag={x:e.touches[0].clientX,y:e.touches[0].clientY,posX:G.crop.posX,posY:G.crop.posY};else if(e.touches.length>=2){const a=e.touches[0],b=e.touches[1];pinch={dist:Math.hypot(a.clientX-b.clientX,a.clientY-b.clientY),zoom:G.crop.zoom};drag=null}},{passive:false});c.addEventListener('touchmove',e=>{e.preventDefault();if(e.touches.length===1&&drag){const t=e.touches[0],f=factor(),dx=(t.clientX-drag.x)*f,dy=(t.clientY-drag.y)*f;G.crop.posX=Math.max(-100,Math.min(100,drag.posX+dx/Math.max(1,c.width)*180));G.crop.posY=Math.max(-100,Math.min(100,drag.posY+dy/Math.max(1,c.height)*180));if($('cropPosX'))$('cropPosX').value=String(G.crop.posX);if($('cropPosY'))$('cropPosY').value=String(G.crop.posY);v902CropDraw()}else if(e.touches.length>=2&&pinch){const a=e.touches[0],b=e.touches[1],d=Math.hypot(a.clientX-b.clientX,a.clientY-b.clientY);G.crop.zoom=Math.max(1,Math.min(4,pinch.zoom*d/Math.max(1,pinch.dist)));$('cropZoom').value=String(G.crop.zoom);v902CropDraw()}},{passive:false});c.addEventListener('touchend',()=>{drag=null;pinch=null})}
  function v902OpenCropper(payload,ctx={}){
    closeCropper();
    const target=String(ctx.target||''),isCheki=target.includes('benefit'),isFixedUI=['home','nav','action','member-icon','group-icon'].includes(String(ctx.role||''));
    const fixed=cropSpec(ctx,payload),portrait=54/86,landscape=86/54,defaultRatio=isCheki?portrait:(target.includes('member-favorite')?.8:4/3),dims=isFixedUI?{w:fixed.w,h:fixed.h}:v902CropDims(defaultRatio);
    G.crop={payload,ctx,spec:fixed,img:null,zoom:1,posX:0,posY:0,ratio:dims.w/dims.h};
    const chekiPresets=isCheki?`<div class="v902-cheki-presets"><button class="btn small active" id="cropPortrait" type="button">縦チェキ</button><button class="btn small" id="cropLandscape" type="button">横チェキ</button></div>`:'';
    const ratioControl=!isFixedUI?`${chekiPresets}<div class="v9-crop-ratio"><b>縦長</b><input id="cropRatio" type="range" min="0.45" max="2.25" step="0.01" value="${defaultRatio}"><b>横長</b></div><div class="v902-ratio-label" id="cropRatioLabel">縦横比 ${(defaultRatio).toFixed(2)}</div>`:'';
    const ov=document.createElement('div');ov.id='cropOverlay';ov.className='crop-overlay';ov.innerHTML=`<div class="crop-sheet"><div class="modal-head"><div><div class="guide-kicker">CROP</div><h2>${isCheki?'チェキを矩形で切り抜き':'矩形で切り抜き'}</h2></div><button class="close-btn" id="cropClose">×</button></div><div class="panel crop-wrap"><div class="hint" style="margin-bottom:8px">${isCheki?'縦チェキ・横チェキのどちらにも対応します。':'縦長・横長を自由に調整できます。'} 点線の内側が保存範囲です。</div><div class="crop-stage"><canvas id="cropCanvas" width="${dims.w}" height="${dims.h}"></canvas></div>${ratioControl}<div class="v81-crop-sliders"><div class="v81-crop-line"><b>縮小</b><input id="cropZoom" type="range" min="1" max="4" step="0.01" value="1"><b>拡大</b></div><div class="v81-crop-line"><b>左</b><input id="cropPosX" type="range" min="-100" max="100" step="1" value="0"><b>右</b></div><div class="v81-crop-line"><b>上</b><input id="cropPosY" type="range" min="-100" max="100" step="1" value="0"><b>下</b></div></div></div><div class="modal-foot"><button class="btn" id="cropReset">中央に戻す</button><button class="btn" id="cropCancel">キャンセル</button><button class="btn primary" id="cropConfirm">この矩形で保存</button></div></div>`;
    document.body.appendChild(ov);$('cropClose').onclick=$('cropCancel').onclick=closeCropper;
    const img=new Image();G.crop.img=img;img.onload=()=>{v902CropDraw();v902CropBind()};img.onerror=()=>toast('画像を読み込めませんでした');img.src=payload.dataURL;
    const setRatio=r=>{const d=v902CropDims(r),c=$('cropCanvas');c.width=d.w;c.height=d.h;G.crop.ratio=d.w/d.h;if($('cropRatio'))$('cropRatio').value=String(r);if($('cropRatioLabel'))$('cropRatioLabel').textContent=`縦横比 ${Number(r).toFixed(2)}`;$('cropPortrait')?.classList.toggle('active',Math.abs(r-portrait)<.02);$('cropLandscape')?.classList.toggle('active',Math.abs(r-landscape)<.02);v902CropDraw()};
    $('cropZoom').oninput=()=>{G.crop.zoom=Number($('cropZoom').value)||1;v902CropDraw()};$('cropPosX').oninput=()=>{G.crop.posX=Number($('cropPosX').value)||0;v902CropDraw()};$('cropPosY').oninput=()=>{G.crop.posY=Number($('cropPosY').value)||0;v902CropDraw()};if($('cropRatio'))$('cropRatio').oninput=()=>setRatio(Number($('cropRatio').value));if($('cropPortrait'))$('cropPortrait').onclick=()=>setRatio(portrait);if($('cropLandscape'))$('cropLandscape').onclick=()=>setRatio(landscape);
    $('cropReset').onclick=()=>{G.crop.zoom=1;G.crop.posX=0;G.crop.posY=0;$('cropZoom').value='1';$('cropPosX').value='0';$('cropPosY').value='0';v902CropDraw()};
    $('cropConfirm').onclick=()=>{const c=$('cropCanvas'),a=attachmentById(ctx.attachmentId);if(a){const mini=document.createElement('canvas'),max=1100,r=c.width/c.height;mini.width=Math.min(max,c.width);mini.height=Math.max(1,Math.round(mini.width/r));mini.getContext('2d').drawImage(c,0,0,mini.width,mini.height);a.thumbDataURL=mini.toDataURL('image/jpeg',.87);a.cropAspectRatio=r;persist();closeCropper();if($('photoDraftBody'))renderPhotoDraft();if($('benefitDraftList'))renderBenefitManager();if($('savedChekiList'))window.GEMS801_RENDER_SAVED_CHEKI?.();renderAll();toast(isCheki?(r>1?'横チェキとして保存しました':'縦チェキとして保存しました'):'矩形の切り抜きを保存しました');return}window.__GEMS_PENDING_CROP__=c.toDataURL('image/jpeg',.9);native('save-crop',{...ctx,cropAspectRatio:c.width/c.height})};
  }
  window.GEMS_NATIVE_CROP_START=(payload,ctx)=>v902OpenCropper(payload,ctx||{});
  window.GEMS_NATIVE_EDIT_CROP_START=(payload,ctx)=>v902OpenCropper(payload,ctx||{});
})();
