  function v91SeedDefaults(s){
    s.settings.appearance='light';s.settings.themePreset=s.settings.themePreset||'mint';
    s.settings.features={...(s.settings.features||{}),notes:true,attachments:true,tags:true,setlist:true,songMaster:true};
    const tags=['生誕','周年','遠征','初参戦','フェス'];tags.forEach(t=>{if(!(s.tags||[]).includes(t))s.tags.push(t)});
    if(!(s.venues||[]).some(v=>v.name==='東京ドーム'))s.venues.push({id:uid('v'),name:'東京ドーム',station:'水道橋',address:'',notes:'初期データベース'});
    (s.groups||[]).forEach(g=>{if(!g.xId)g.xId=V91_GROUP_X_IDS[g.name]||''});return s
  }

  function v91BuildStartUI(){
    const ob=document.getElementById('onboarding');if(!ob)return;
    ob.innerHTML=`<div class="v91-start"><div class="v91-start-card"><div class="v91-start-mark">G</div><div class="brand-small" style="margin-top:14px">GENERAL EVENT MANAGEMENT SYSTEM</div><h1>GEMSをはじめる</h1><p class="lead">最初に、KAWAII LAB.の人物・グループ情報と楽曲データベースを準備します。入力の土台を先に整えてから、実際の現場登録をチュートリアルで案内します。</p><div class="v91-setup-grid"><div class="v91-setup-item"><b>人物・グループ</b><small>Xの公開プロフィール画像を取得してアイコンを準備</small></div><div class="v91-setup-item"><b>楽曲データベース</b><small>MusicBrainzから対応グループの楽曲情報を同期</small></div><div class="v91-setup-item"><b>基本データベース</b><small>メンバー・色・タグ・基本会場を最初から利用可能に</small></div></div><button class="btn primary block v91-start-btn" id="v91StartBtn">スタート</button><div class="v91-start-secondary"><button class="btn small" id="v91RestoreBtn">バックアップから復元</button></div><div class="v91-progress" id="v91Progress"><div class="v91-progress-bar"><i id="v91ProgressBar"></i></div><div class="v91-progress-row" id="v91StepMaster"><b>基本データベース</b><span class="state">待機中</span></div><div class="v91-progress-row" id="v91StepX"><b>アイコン</b><span class="state">待機中</span></div><div class="v91-progress-row" id="v91StepMusic"><b>楽曲データベース</b><span class="state">待機中</span></div><div id="v91SetupNote" class="hint" style="margin-top:9px"></div><button class="btn primary block hidden" id="v91TutorialGo" style="margin-top:12px">初回チュートリアルへ</button></div></div></div>`;
    document.getElementById('v91StartBtn').onclick=v91StartInitialSetup;document.getElementById('v91RestoreBtn').onclick=()=>native('restore-backup');document.getElementById('v91TutorialGo').onclick=v91BeginTutorial;if(G.devPreview){const box=ob.querySelector('.v91-start-card');if(box&&!document.getElementById('v91PreviewExitOnboard')){box.insertAdjacentHTML('beforeend','<button class="btn block" id="v91PreviewExitOnboard" style="margin-top:10px">プレビューを終了して元のデータに戻す</button>');document.getElementById('v91PreviewExitOnboard').onclick=v91ExitPreview}}
  }
  function v91Step(id,state,text){const el=document.getElementById(id);if(!el)return;el.classList.remove('done','warn');if(state)el.classList.add(state);const s=el.querySelector('.state');if(s)s.textContent=text||''}
  function v91Progress(n){const b=document.getElementById('v91ProgressBar');if(b)b.style.width=Math.max(0,Math.min(100,n))+'%'}
  function v91XTargets(onlyMissing){const rows=[];(G.state.members||[]).forEach(m=>{if(m.xId&&(!onlyMissing||!m.iconAttachmentId))rows.push({id:m.id,entityType:'member',xId:m.xId,name:m.name})});(G.state.groups||[]).forEach(g=>{if(g.xId&&(!onlyMissing||!g.iconAttachmentId))rows.push({id:g.id,entityType:'group',xId:g.xId,name:g.name})});return rows}
  function v91StartInitialSetup(){
    const ob=document.getElementById('onboarding');if(!ob)return;G.state=v91SeedDefaults(starterState());G.state.settings.initialSetupCompleted=false;G.state.settings.tutorialCompleted=false;v91SetupPhase='icons';persist();renderAll();v91BuildStartUI();document.getElementById('v91Progress').classList.add('active');document.getElementById('v91StartBtn').classList.add('hidden');document.getElementById('v91RestoreBtn').classList.add('hidden');v91Step('v91StepMaster','done','準備完了');v91Progress(12);
    const targets=v91XTargets(true);if(G.devPreview){v91Step('v91StepX','done','プレビューでは省略');v91Progress(60);setTimeout(v91StartInitialMusic,80);return}if(!targets.length){v91Step('v91StepX','done','対象なし');v91Progress(60);v91StartInitialMusic();return}v91Step('v91StepX','',`取得中 0 / ${targets.length}`);native('x-avatar-sync',{targets,mode:'missing'});
  }
  function v91StartInitialMusic(){v91SetupPhase='music';const groups=G.state.groups.filter(g=>V91_MB_NAMES.has(g.name)).map(g=>({id:g.id,name:g.name,mbid:g.musicBrainzArtistId||G.state.integrations?.musicBrainz?.artists?.[g.id]||''}));if(G.devPreview){v91Step('v91StepMusic','done','プレビューでは省略');v91SetupReady();return}if(!groups.length){v91Step('v91StepMusic','done','対象なし');v91SetupReady();return}v91Step('v91StepMusic','',`取得中 0 / ${groups.length}`);native('musicbrainz-sync',{groups})}
  function v91SetupReady(){v91SetupPhase='';G.state.settings.initialSetupCompleted=true;G.state.settings.tutorialCompleted=false;persist();v91Progress(100);v91Step('v91StepMusic','done',document.querySelector('#v91StepMusic .state')?.textContent?.includes('失敗')?'一部失敗':'準備完了');const note=document.getElementById('v91SetupNote');if(note)note.textContent='準備ができました。続いて、実際の現場登録を1件だけ使って操作を案内します。';document.getElementById('v91TutorialGo')?.classList.remove('hidden')}

  const _v91XResult=window.GEMS_NATIVE_X_AVATAR_RESULT;
  window.GEMS_NATIVE_X_AVATAR_PROGRESS=function(p){p=p||{};const st=document.getElementById('v9XAvatarStatus');if(st)st.textContent=`Xアイコンを取得中… ${Number(p.done)||0} / ${Number(p.total)||0}${p.failed?`（失敗 ${p.failed}）`:''}`;if(v91SetupPhase==='icons'){v91Step('v91StepX','',`取得中 ${Number(p.done)||0} / ${Number(p.total)||0}${p.failed?`・失敗 ${p.failed}`:''}`);v91Progress(12+Math.round((Number(p.done)||0)/Math.max(1,Number(p.total)||1)*46))}};
  window.GEMS_NATIVE_X_AVATAR_RESULT=function(payload){
    const p=payload||{},items=Array.isArray(p.items)?p.items:[];let ok=0,failed=0;for(const row of items){if(row&&row.meta&&row.meta.id){if(!G.state.attachments.some(x=>x.id===row.meta.id))G.state.attachments.push(row.meta);if((row.entityType==='group'||row.groupId)&&groupById(row.entityId||row.groupId)){const g=groupById(row.entityId||row.groupId);g.iconAttachmentId=row.meta.id;g.xAvatarUpdatedAt=new Date().toISOString();ok++}else if(memberById(row.entityId||row.memberId)){const m=memberById(row.entityId||row.memberId);m.iconAttachmentId=row.meta.id;m.xAvatarUpdatedAt=new Date().toISOString();ok++}}else failed++}
    persist();renderAll();if(document.querySelector('.view[data-view="settings"].active'))renderSettings();const mb=document.getElementById('memberXFetch'),gb=document.getElementById('groupXFetch');if(mb){mb.disabled=false;mb.textContent='Xアイコンを取得'}if(gb){gb.disabled=false;gb.textContent='Xアイコンを取得'}const status=document.getElementById('v9XAvatarStatus');if(status)status.textContent=`取得完了 ${ok}件${failed?` / 失敗 ${failed}件`:''}`;
    if(v91SetupPhase==='icons'){v91Step('v91StepX',failed?'warn':'done',failed?`${ok}件取得・${failed}件失敗`:`${ok}件取得`);v91Progress(60);setTimeout(v91StartInitialMusic,80)}else toast(`Xアイコン：${ok}件取得${failed?` / ${failed}件失敗`:''}`)
  };
  window.GEMS_NATIVE_X_AVATAR_ERROR=function(msg){const mb=document.getElementById('memberXFetch'),gb=document.getElementById('groupXFetch');if(mb){mb.disabled=false;mb.textContent='Xアイコンを取得'}if(gb){gb.disabled=false;gb.textContent='Xアイコンを取得'}if(v91SetupPhase==='icons'){v91Step('v91StepX','warn','取得できず・後で再取得可');v91Progress(60);setTimeout(v91StartInitialMusic,80)}else toast(`Xアイコン取得に失敗：${String(msg||'不明なエラー')}`)};

  const _v91MBResult=window.GEMS_NATIVE_MUSICBRAINZ_RESULT,_v91MBError=window.GEMS_NATIVE_MUSICBRAINZ_ERROR;
  window.GEMS_NATIVE_MUSICBRAINZ_PROGRESS=function(p){if(v91SetupPhase==='music'){v91Step('v91StepMusic','',`取得中 ${Number(p.done)||0} / ${Number(p.total)||0}`);v91Progress(60+Math.round((Number(p.done)||0)/Math.max(1,Number(p.total)||1)*36))}};
  window.GEMS_NATIVE_MUSICBRAINZ_RESULT=function(p){if(_v91MBResult)_v91MBResult(p);if(v91SetupPhase==='music'){const failed=(p?.groups||[]).filter(x=>x.error).length;v91Step('v91StepMusic',failed?'warn':'done',failed?`同期完了・${failed}グループ失敗`:'同期完了');setTimeout(v91SetupReady,80)}};
  window.GEMS_NATIVE_MUSICBRAINZ_ERROR=function(msg){if(_v91MBError)_v91MBError(msg);if(v91SetupPhase==='music'){v91Step('v91StepMusic','warn','取得できず・後で同期可');setTimeout(v91SetupReady,80)}};

  function v91TutorialEvent(){const fz=G.state.groups.find(g=>g.name==='FRUITS ZIPPER'),td=G.state.venues.find(v=>v.name==='東京ドーム');return{id:V91_TUTORIAL_ID,date:'2026-02-01',time:'',name:'FRUITS ZIPPER 東京ドーム（チュートリアル）',type:'live',status:'実績',groupIds:fz?[fz.id]:[],venueId:td?td.id:'',venueText:td?'':'東京ドーム',important:false,tags:[],seatNumber:'',queueNumber:'',benefits:[],expenses:[],notes:'',attachments:[],setlist:[],travelEnabled:false,travelId:'',otherDays:0,otherCount:1,scheduleKind:'',scheduleAt:'',createdAt:new Date().toISOString(),updatedAt:new Date().toISOString(),tutorialOnly:true}}
  function v91BeginTutorial(){document.getElementById('onboarding')?.classList.add('hidden');setModal(`<div class="modal-head"><div><div class="v91-tutorial-progress">TUTORIAL 1 / 3</div><h2>現場登録を1件やってみます</h2></div></div><div class="panel"><div class="v91-tutorial-banner"><b>2026.02.01 / FRUITS ZIPPER / 東京ドーム</b><small>この現場へ参加した、という仮の記録を使います。チュートリアル完了時にこの1件は自動削除され、あなたの記録には残りません。</small></div><div class="detail-text">GEMSでは「日付」「現場名」「現場種別」を中心に、グループ・会場などを追加して登録します。次の画面では入力済みの例を見ながら、どこを確認するか案内します。</div></div><div class="modal-foot"><button class="btn primary" id="v91TutorialForm">登録画面を見る</button></div>`);document.getElementById('v91TutorialForm').onclick=()=>{closeModal();setTimeout(v91OpenTutorialForm,70)}}
  function v91OpenTutorialForm(){const e=v91TutorialEvent();openEventForm();document.getElementById('eventId').value=e.id;document.getElementById('eventDate').value=e.date;document.getElementById('eventName').value=e.name;document.getElementById('eventType').value=e.type;document.getElementById('eventStatus').value=e.status;document.querySelectorAll('#eventGroupChecks input').forEach(c=>{c.checked=e.groupIds.includes(c.value);c.closest('label')?.classList.toggle('active',c.checked)});const vs=document.getElementById('eventVenue');if(vs){if(e.venueId)vs.value=e.venueId;else{vs.value='__custom';document.getElementById('eventVenueText').classList.remove('hidden');document.getElementById('eventVenueText').value='東京ドーム'}}updateEventTypeUI(e);G.formSeedEvent=e;G.v91TutorialSaving=true;const intro=document.querySelector('#modal .entry-intro');if(intro)intro.insertAdjacentHTML('beforebegin','<div class="v91-tutorial-banner"><div class="v91-tutorial-progress">TUTORIAL 2 / 3</div><b>登録時は、まずこの5か所を確認</b><small>日付・現場名・現場種別・グループ・会場です。今回は例として入力済みです。そのまま下の「この現場を登録して次へ」を押してください。</small></div>');['eventDate','eventName','eventType','eventVenue'].forEach(id=>document.getElementById(id)?.closest('.field')?.classList.add('v91-tutorial-field'));document.getElementById('eventGroupChecks')?.closest('.field')?.classList.add('v91-tutorial-field');const save=document.getElementById('saveEventBtn');if(save)save.textContent='この現場を登録して次へ'}
  const _v91SaveEvent=saveEventFromForm;saveEventFromForm=function(){const tutorial=G.v91TutorialSaving&&document.getElementById('eventId')?.value===V91_TUTORIAL_ID;_v91SaveEvent();if(tutorial){const e=G.state.events.find(x=>x.id===V91_TUTORIAL_ID);if(e){e.tutorialOnly=true;persist();G.v91TutorialSaving=false;setTimeout(v91TutorialRegistered,180)}}};
  function v91TutorialRegistered(){showView('events',{noHistory:true});setModal(`<div class="modal-head"><div><div class="v91-tutorial-progress">TUTORIAL 3 / 3</div><h2>登録できました</h2></div></div><div class="panel"><div class="v91-tutorial-banner"><b>現場は一覧・カレンダー・分析へつながります</b><small>同じ要領で実際の現場を登録できます。公式スケジュール掲載現場なら、登録画面の「公式の予定から選ぶ」で入力を短縮できます。</small></div><div class="detail-text">いま作った東京ドームの仮記録は、チュートリアル終了と同時に削除します。</div></div><div class="modal-foot"><button class="btn primary" id="v91TutorialFinish">チュートリアルを完了</button></div>`);document.getElementById('v91TutorialFinish').onclick=v91FinishTutorial}
  function v91FinishTutorial(){G.state.events=(G.state.events||[]).filter(e=>e.id!==V91_TUTORIAL_ID&&!e.tutorialOnly);G.state.settings.tutorialCompleted=true;G.state.settings.initialSetupCompleted=true;persist();closeModal();renderAll();showView('home',{noHistory:true});toast('GEMSの準備が完了しました')}
  function v91ResumeTutorial(){if(!G.state.settings.initialSetupCompleted||G.state.settings.tutorialCompleted)return;setTimeout(()=>{if((G.state.events||[]).some(e=>e.id===V91_TUTORIAL_ID))v91TutorialRegistered();else v91BeginTutorial()},180)}

  // Group X profile controls / X ID edit.
  const _v91OpenGroupProfile=openGroupProfile;openGroupProfile=function(id){_v91OpenGroupProfile(id);const g=groupById(id);if(!g||!g.xId)return;const hero=document.getElementById('groupProfileIcon')?.closest('.profile-hero')?.parentElement;if(hero&&!document.getElementById('groupXFetch'))hero.insertAdjacentHTML('beforeend',`<div style="display:flex;gap:7px;margin-top:9px;flex-wrap:wrap"><button class="btn small" id="groupXOpen">Xプロフィールを開く</button><button class="btn primary small" id="groupXFetch">Xアイコンを取得</button></div>`);if(document.getElementById('groupXOpen'))document.getElementById('groupXOpen').onclick=()=>window.open(`https://x.com/${encodeURIComponent(g.xId)}`,'_blank');if(document.getElementById('groupXFetch'))document.getElementById('groupXFetch').onclick=()=>{const b=document.getElementById('groupXFetch');b.disabled=true;b.textContent='取得中…';native('x-avatar-sync',{targets:[{id:g.id,entityType:'group',xId:g.xId,name:g.name}],mode:'single'})}};
  const _v91OpenGroupMaster=openGroupMaster;openGroupMaster=function(id=''){_v91OpenGroupMaster(id);const g=id?groupById(id):null,panel=document.getElementById('mGroupName')?.closest('.panel');if(panel&&!document.getElementById('mGroupXId'))document.getElementById('mGroupName').closest('.field').insertAdjacentHTML('afterend',`<label class="field"><span>X ID（任意）</span><input id="mGroupXId" value="${esc(g?.xId||V91_GROUP_X_IDS[g?.name]||'')}" placeholder="@は不要"><div class="hint">公式Xのプロフィールアイコン取得に使用します。</div></label>`);const save=document.getElementById('mGroupSave'),old=save?.onclick;if(save)save.onclick=()=>{const x=document.getElementById('mGroupXId')?.value?.trim().replace(/^@/,'')||'',name=document.getElementById('mGroupName')?.value?.trim()||'';old?.();const saved=id?groupById(id):G.state.groups.slice().reverse().find(y=>y.name===name);if(saved){saved.xId=x||saved.xId||V91_GROUP_X_IDS[saved.name]||'';persist()}}};

  function v91PostSettings(){const mode=document.getElementById('appearanceMode');if(mode){mode.value='light';const f=mode.closest('.field');if(f)f.style.display='none'}const pane=document.getElementById('settingsPane_developer');if(pane){const card=document.getElementById('v9XAvatarStatus')?.closest('.v9-dev-card');if(card){const all=v91XTargets(false),set=all.filter(x=>(x.entityType==='member'?memberById(x.id):groupById(x.id))?.iconAttachmentId).length;card.querySelector('h4').textContent='Xプロフィールアイコン（メンバー・グループ）';const hint=card.querySelector('.hint');if(hint)hint.innerHTML=`公開プロフィール画像をGEMSへ保存します。取得済み ${set} / ${all.length}件。`;const m=document.getElementById('v9XAvatarMissing'),a=document.getElementById('v9XAvatarAll');if(m)m.onclick=()=>{const targets=v91XTargets(true);if(!targets.length){toast('未設定のXアイコンはありません');return}native('x-avatar-sync',{targets,mode:'missing'})};if(a)a.onclick=()=>{const targets=v91XTargets(false);confirmModal('Xアイコンを更新',`${targets.length}件のプロフィール画像を再取得します。`,()=>native('x-avatar-sync',{targets,mode:'all'}))}}const prev=document.getElementById('v9PreviewStart');if(prev)prev.onclick=v91EnterPreview}}
  const _v91RenderSettings=renderSettings;renderSettings=function(){_v91RenderSettings();v91PostSettings()};

  function v91EnterPreview(){if(G.devPreview)return;G.devPreviewOriginal=clone(G.state);G.devPreview=true;G.state=v91Ensure(blankState(),true);renderAll();showView('home',{noHistory:true});v91BuildStartUI();document.getElementById('onboarding')?.classList.remove('hidden');v91PreviewBanner()}
  function v91PreviewBanner(){document.getElementById('v9PreviewBanner')?.remove();if(!G.devPreview)return;const el=document.createElement('div');el.id='v9PreviewBanner';el.className='v9-preview-banner';el.innerHTML='<span>初期状態プレビュー中（実データは変更されません）</span><button class="btn small" id="v91PreviewExit">元のデータに戻す</button>';document.querySelector('.topbar')?.insertAdjacentElement('afterend',el);document.getElementById('v91PreviewExit').onclick=v91ExitPreview}
