  function v92BuildStartUI(){const ob=document.getElementById('onboarding');if(!ob)return;ob.innerHTML=`<div class="v92-start"><div class="v92-start-card"><img class="v92-start-icon" src="${V92_START_ICON}" alt="GEMS"><div class="brand-small" style="text-align:center">GENERAL EVENT MANAGEMENT SYSTEM</div><h1>GEMSをはじめよう</h1><p class="lead">ライブも特典会も、写真もチェキも。あなたの推し活をここにまとめよう。</p><button class="btn primary block v92-start-btn" id="v92StartBtn">スタート</button><button class="btn block" id="v92RestoreBtn" style="margin-top:8px">バックアップから復元</button><div class="hidden" id="v92SetupBox"><div class="v92-loader"></div><div class="v92-setup-status" id="v92SetupStatus">セットアップ中…</div><div class="hint" style="text-align:center;margin-top:6px">このまま少し待ってね</div></div>${G.devPreview?'<button class="btn block" id="v92PreviewExit" style="margin-top:10px">プレビューを終了して元のデータに戻す</button>':''}</div></div>`;document.getElementById('v92StartBtn').onclick=v92StartSetup;document.getElementById('v92RestoreBtn').onclick=()=>native('restore-backup');if(document.getElementById('v92PreviewExit'))document.getElementById('v92PreviewExit').onclick=v92ExitPreview}
  function v92EnterPreview(){if(G.devPreview)return;G.devPreviewOriginal=clone(G.state);G.devPreview=true;G.state=v92Ensure(starterState(),true);renderAll();showView('home',{noHistory:true});v92BuildStartUI();document.getElementById('onboarding')?.classList.remove('hidden');toast('初期状態をプレビューしています')}
  function v92ExitPreview(){if(!G.devPreview)return;G.state=v92Ensure(G.devPreviewOriginal||blankState(),false);G.devPreviewOriginal=null;G.devPreview=false;document.getElementById('v9PreviewBanner')?.remove();document.getElementById('onboarding')?.classList.add('hidden');renderAll();showView('settings',{noHistory:true});setTimeout(()=>document.querySelector('[data-settings-mid="developer"]')?.click(),60);toast('元のデータへ戻しました')}
  function v92StartSetup(){G.state=v92Ensure(starterState(),true);G.state.settings.initialSetupCompleted=false;G.state.settings.tutorialCompleted=false;persist();renderAll();v92BuildStartUI();document.getElementById('v92StartBtn')?.classList.add('hidden');document.getElementById('v92RestoreBtn')?.classList.add('hidden');document.getElementById('v92SetupBox')?.classList.remove('hidden');v92SetupPhase='icons';const targets=v92XTargets(true);if(!targets.length){v92SetupMusic();return}native('x-avatar-sync',{targets,mode:'missing'})}
  function v92SetupMusic(){v92SetupPhase='music';const groups=v92MusicGroups();if(!groups.length){v92SetupReady();return}const s=document.getElementById('v92SetupStatus');if(s)s.textContent='もうすぐ準備完了！';native('musicbrainz-sync',{groups})}
  function v92SetupReady(){v92SetupPhase='';G.state.settings.initialSetupCompleted=true;G.state.settings.tutorialCompleted=false;persist();const s=document.getElementById('v92SetupStatus');if(s)s.textContent='準備できたよ！';setTimeout(v92StartTutorial,420)}
