  function v92TourClear(){document.querySelector('.v92-tour-mask')?.remove();document.querySelector('.v92-tour-bubble')?.remove();document.querySelectorAll('.v92-tour-target').forEach(x=>x.classList.remove('v92-tour-target'));if(v92TutorialCleanup){try{v92TutorialCleanup()}catch{}v92TutorialCleanup=null}}
  function v92Bubble(target,html,{button='',onButton=null,requireTap=false,side='auto'}={}){v92TourClear();const t=typeof target==='string'?document.querySelector(target):target;if(!t)return false;t.classList.add('v92-tour-target');const mask=document.createElement('div');mask.className='v92-tour-mask';document.body.appendChild(mask);const b=document.createElement('div');b.className='v92-tour-bubble';b.innerHTML=`<button class="v92-tour-close" type="button">×</button>${html}${button?`<button class="btn primary v92-tour-next" type="button">${button}</button>`:''}`;document.body.appendChild(b);const place=()=>{const r=t.getBoundingClientRect(),bw=Math.min(320,innerWidth-28),below=r.bottom+12,above=r.top-b.offsetHeight-12;let top=below;if(below+b.offsetHeight>innerHeight-12&&above>12)top=above;b.style.left=Math.max(12,Math.min(innerWidth-bw-12,r.left+r.width/2-bw/2))+'px';b.style.top=Math.max(12,Math.min(innerHeight-b.offsetHeight-12,top))+'px'};requestAnimationFrame(place);b.querySelector('.v92-tour-close').onclick=()=>{v92TourClear();v92FinishTutorial(true)};if(button)b.querySelector('.v92-tour-next').onclick=()=>onButton?.();if(requireTap){const old=t.onclick;t.onclick=function(ev){v92TourClear();if(old)old.call(this,ev);setTimeout(()=>onButton?.(),80)};v92TutorialCleanup=()=>{t.onclick=old}}return true}
  function v92StartTutorial(){document.getElementById('onboarding')?.classList.add('hidden');showView('home',{noHistory:true});v92TutorialStep=0;setTimeout(()=>v92Bubble(document.querySelector('.app'),`<div class="v92-tour-kicker">WELCOME TO GEMS</div><b>ダウンロードいただきありがとう！</b><div>GEMSでは、現場の予定や思い出、チェキ、支出などをまとめて管理できるよ。まずは一緒にGEMを登録してみよう！</div>`,{button:'はじめる',onButton:v92TutorialEvents}),100)}
  function v92TutorialEvents(){showView('events');setTimeout(()=>{const nav=document.querySelector('[data-nav="events"]');v92Bubble(nav,`<div class="v92-tour-kicker">STEP 1</div><b>ここが「GEM」だよ</b><div>GEM（イベント情報）として、ライブや特典会の予定も思い出もここに残せるよ！</div>`,{button:'次へ',onButton:v92TutorialAdd})},140)}
