  function v92TutorialOfficial(){setTimeout(()=>{const btn=document.getElementById('v905OfficialOpen');if(!btn){v92Bubble(document.getElementById('eventName'),`<div class="v92-tour-kicker">STEP 3</div><b>公式の予定から入力できるよ</b><div>今回はFRUITS ZIPPERの東京ドーム公演を練習に使おう。</div>`,{button:'入力する',onButton:v92FillTutorialEvent});return}v92Bubble(btn,`<div class="v92-tour-kicker">STEP 3</div><b>「公式の予定から選ぶ」を使ってみよう！</b><div>公式サイトから日付や現場名を入力できるよ。</div>`,{requireTap:true,onButton:v92TutorialPickOfficial})},160)}
  function v92TutorialPickOfficial(){setTimeout(()=>{const gs=document.getElementById('v905OfficialGroup'),mo=document.getElementById('v905OfficialMonth');if(gs){const fz=G.state.groups.find(g=>g.name==='FRUITS ZIPPER');if(fz)gs.value=fz.id}if(mo)mo.value='2026-02';document.getElementById('v905OfficialFetch')?.click();const out=document.getElementById('v905OfficialResults');if(out)v92Bubble(out,`<div class="v92-tour-kicker">STEP 4</div><b>東京ドーム公演を選んでみよう</b><div>候補が出たら「この予定を使う」をタップしてね。</div><small>通信できない場合は、練習用データを使って続けられるよ。</small>`,{button:'練習用データで続ける',onButton:v92FillTutorialEvent})},180)}
  const _v92OfficialDetail=window.GEMS_NATIVE_OFFICIAL_SCHEDULE_DETAIL;window.GEMS_NATIVE_OFFICIAL_SCHEDULE_DETAIL=function(payload){_v92OfficialDetail?.(payload);if(G.state?.settings?.initialSetupCompleted&&!G.state?.settings?.tutorialCompleted&&payload&&String(payload.date||'')==='2026-02-01'&&/東京ドーム/.test(String(payload.title||'')))setTimeout(v92TutorialAfterOfficial,160)};
  function v92TutorialAfterOfficial(){closeSubModal();const save=document.getElementById('saveEventBtn');if(save)v92Bubble(save,`<div class="v92-tour-kicker">STEP 5</div><b>内容を確認して登録しよう！</b><div>この現場はチュートリアルが終わったら自動で消えるよ。</div>`,{requireTap:true,onButton:v92TutorialMarkEvent});else v92FillTutorialEvent()}
  function v92FillTutorialEvent(){closeSubModal();const fz=G.state.groups.find(g=>g.name==='FRUITS ZIPPER'),td=G.state.venues.find(v=>v.name==='東京ドーム');if(document.getElementById('eventDate'))document.getElementById('eventDate').value='2026-02-01';if(document.getElementById('eventName'))document.getElementById('eventName').value='FRUITS ZIPPER 東京ドーム';if(document.getElementById('eventType')){document.getElementById('eventType').value='live';updateEventTypeUI(G.formSeedEvent)}document.querySelectorAll('#eventGroupChecks input').forEach(c=>{c.checked=!!fz&&c.value===fz.id;c.closest('label')?.classList.toggle('active',c.checked)});if(td&&document.getElementById('eventVenue'))document.getElementById('eventVenue').value=td.id;const save=document.getElementById('saveEventBtn');if(save)v92Bubble(save,`<div class="v92-tour-kicker">STEP 5</div><b>内容を確認して登録しよう！</b><div>この現場はチュートリアルが終わったら自動で消えるよ。</div>`,{requireTap:true,onButton:v92TutorialMarkEvent})}
  function v92TutorialMarkEvent(){setTimeout(()=>{const e=G.state.events.filter(x=>!x.deletedAt&&x.date==='2026-02-01'&&/東京ドーム/.test(x.name||'')).slice(-1)[0];if(e){e.tutorialOnly=true;e.id=V92_TUTORIAL_ID;persist()}v92OpenFavoriteSettings(true)},240)}
  function v92FinishTutorial(skipped=false){v92TourClear();G.state.events=G.state.events.filter(e=>e.id!==V92_TUTORIAL_ID&&!e.tutorialOnly);G.state.settings.tutorialCompleted=true;G.state.settings.initialSetupCompleted=true;persist();renderAll();showView('home',{noHistory:true});if(!skipped)toast('チュートリアル完了！GEMSへようこそ ✨')}

  function v92FavoriteGroups(){return v92SafeArray(G.state.settings.favoriteGroupIds)}
  function v92OpenFavoriteSettings(tutorial=false){const favGroups=new Set(v92FavoriteGroups()),favMembers=new Set(G.state.members.filter(m=>m.favorite).map(m=>m.id));setModal(`<div class="modal-head"><div>${tutorial?'<div class="v92-tour-kicker">LAST STEP</div>':''}<h2>推しを設定しよう</h2></div><button class="close-btn" data-close>×</button></div><div class="panel v92-gem-card"><h3>推しグループ</h3><div class="v92-fav-grid">${G.state.groups.filter(g=>g.active!==false&&!['櫻井優衣（ソロ）'].includes(g.name)).map(g=>`<button type="button" class="v92-fav-choice ${favGroups.has(g.id)?'active':''}" data-v92-fg="${g.id}">${groupAvatarHTML(g,'profile-mini-img')}<b>${esc(g.name)}</b></button>`).join('')}</div></div><div class="panel v92-gem-card"><h3>推しメンバー</h3><div class="v92-fav-grid">${G.state.members.filter(m=>m.active!==false).map(m=>`<button type="button" class="v92-fav-choice ${favMembers.has(m.id)?'active':''}" data-v92-fm="${m.id}">${memberAvatarHTML(m,'profile-mini-img')}<b>${esc(m.name)}</b></button>`).join('')}</div></div><div class="modal-foot"><button class="btn" data-close>あとで</button><button class="btn primary" id="v92FavSave">${tutorial?'設定してはじめる':'保存'}</button></div>`);qsa('[data-close]').forEach(b=>b.onclick=()=>{closeModal();if(tutorial)v92FinishTutorial(true)});qsa('[data-v92-fg]').forEach(b=>b.onclick=()=>b.classList.toggle('active'));qsa('[data-v92-fm]').forEach(b=>b.onclick=()=>b.classList.toggle('active'));document.getElementById('v92FavSave').onclick=()=>{G.state.settings.favoriteGroupIds=qsa('[data-v92-fg].active').map(b=>b.dataset.v92Fg);G.state.members.forEach(m=>m.favorite=!!document.querySelector(`[data-v92-fm="${m.id}"].active`));G.state.settings.primaryGroupId=G.state.settings.favoriteGroupIds[0]||'';persist();closeModal();renderAll();if(tutorial)v92FinishTutorial(false);else toast('推し設定を保存しました')}}

  function v92SetupFavoritePanel(){const p=document.getElementById('homeProfilesPanel');if(!p)return;const head=p.querySelector('.share-top');if(head&&!document.getElementById('v92FavEdit')){const old=head.querySelector('button');if(old)old.textContent='データベース';head.insertAdjacentHTML('beforeend','<button class="btn primary small" id="v92FavEdit">推しを設定</button>');document.getElementById('v92FavEdit').onclick=()=>v92OpenFavoriteSettings(false)}const hint=p.querySelector('.hint');if(hint)hint.textContent='推しメンバーと推しグループをここから設定できます。'}
  const _v92RenderHomeProfiles=typeof renderHomeProfiles==='function'?renderHomeProfiles:null;
