  // Member/group icon changes are database-only.
  const _v92MemberRow=memberMasterRow;memberMasterRow=function(m){const groups=(m.memberships||[]).map(mm=>groupById(mm.groupId)?.name).filter(Boolean).join(' / '),c=memberColorFor(m);return `<div class="member-mini v92-db-member"><span class="v92-db-avatar">${memberAvatarHTML(m,'profile-mini-img')}</span><button class="profile-list-button" data-member-profile="${m.id}"><b>${esc(m.name)}${m.favorite?'<span class="oshi-badge">★ 推し</span>':''}</b><small>${c?`${esc(c.name)} ・ `:''}${esc(groups||'所属未設定')}</small></button><div class="v92-db-actions"><button class="btn small" data-v92-x-member="${m.id}">X取得</button><button class="btn small" data-v92-photo-member="${m.id}">画像</button><button class="btn small" data-member-edit="${m.id}">編集</button></div></div>`};
  const _v92RenderMasterLists=renderMasterLists;renderMasterLists=function(){_v92RenderMasterLists();qsa('[data-v92-x-member]').forEach(b=>b.onclick=()=>{const m=memberById(b.dataset.v92XMember);if(m?.xId)native('x-avatar-sync',{targets:[{id:m.id,entityType:'member',xId:m.xId,name:m.name}],mode:'single'});else toast('X IDが未設定です')});qsa('[data-v92-photo-member]').forEach(b=>b.onclick=()=>profileIconTap('member',b.dataset.v92PhotoMember));qsa('[data-group-edit]').forEach(b=>{const g=groupById(b.dataset.groupEdit);if(g&&!b.parentElement.querySelector('[data-v92-x-group]'))b.insertAdjacentHTML('beforebegin',`<button class="btn small" data-v92-x-group="${g.id}">X取得</button>`)});qsa('[data-v92-x-group]').forEach(b=>b.onclick=()=>{const g=groupById(b.dataset.v92XGroup);if(g?.xId)native('x-avatar-sync',{targets:[{id:g.id,entityType:'group',xId:g.xId,name:g.name}],mode:'single'});else toast('公式X IDが未設定です')})};
  const _v92OpenMemberProfile=openMemberProfile;openMemberProfile=function(id){_v92OpenMemberProfile(id);const btn=document.getElementById('memberProfileIcon');if(btn){const d=document.createElement('div');d.className='profile-avatar-btn v92-static-avatar';d.innerHTML=btn.innerHTML;btn.replaceWith(d)}document.getElementById('memberXFetch')?.remove()};
