  function v92EventSushi(){document.getElementById('v92EventGuide')?.remove();const view=document.getElementById('eventsView'),title=view?.querySelector('.section-title');if(!title)return;const box=document.createElement('div');box.id='v92EventGuide';box.className='v92-event-guide';const members=G.state.members.filter(m=>m.active!==false).slice().sort(()=>Math.random()-.5);const one=members.map(m=>`<span class="v92-sushi-item">${m.iconAttachmentId?memberAvatarHTML(m,''): `<span class="v92-sushi-fallback">${esc(m.name.slice(0,1))}</span>`}</span>`).join('');const px=Math.max(1,members.length)*42,duration=Math.max(1,px/24);box.innerHTML=`<div class="v92-event-guide-message">${V92_EVENT_MESSAGES[Math.floor(Math.random()*V92_EVENT_MESSAGES.length)]}</div><div class="v92-sushi"><div class="v92-sushi-track" style="--v92-duration:${duration}s">${one}${one}</div></div>`;title.insertAdjacentElement('afterend',box)}
  const _v92RenderEvents=renderEvents;renderEvents=function(){_v92RenderEvents();v92EventSushi();v92AddChekiCollectionPanel()};

  // No merchandise entry tab: legacy merchandise is migrated into expense lines.
  const _v92EventFormHTML=eventFormHTML;eventFormHTML=function(e){let h=_v92EventFormHTML(e);h=h.replace(/<option value="merch"[^>]*>[^<]*<\/option>/g,'');h=h.replace(/<button[^>]*id="openMerchManager"[\s\S]*?<\/button>/,'');h=h.replace(/チェキ・支出・物販・写真等/g,'チェキ・支出・写真等').replace(/チェキ・支出・物販・写真等は/g,'チェキ・支出・写真等は');return h};
