  const _v92EventDetailActionCards=eventDetailActionCards;eventDetailActionCards=function(e){return _v92EventDetailActionCards(e).replace(/<div class="detail-action-card">[\s\S]*?id="detailOpenMerch"[\s\S]*?<\/div>/,'')};

  // One cheki = one detail. Bulk creation duplicates identical rows before save.
  benefitEditorHTML=function(b={},index=0){const id=b.id||uid('b'),groupId=b.groupId||'',atts=v92SafeArray(b.attachments).slice(0,1),bingo=document.getElementById('eventType')?.value==='online_bingo';return `<details class="detail-collapse" data-draft-benefit="${id}" ${index===0&&b.__new?'open':''}><summary><span><b>${esc(memberById(b.memberId)?.name||groupById(groupId)?.name||`明細 ${index+1}`)}</b><small>${bingo?`${Number(b.count)||1}枠`:'チェキ1枚'}${b.part?` ・ ${esc(b.part)}`:''}${atts.length?' ・ 画像あり':''}</small></span></summary><div class="detail-collapse-body"><div class="form-grid"><label class="field"><span>グループ</span><select data-db-group>${groupOptions(groupId)}</select></label><label class="field"><span>メンバー</span><select data-db-member>${memberOptions(b.memberId||'',groupId,document.getElementById('eventDate')?.value||'')}</select></label>${bingo?`<label class="field"><span>枠数</span><input data-db-count type="number" min="1" step="1" value="${Number(b.count)||1}"></label>`:`<input data-db-count type="hidden" value="1"><label class="field"><span>同じ条件で作る枚数</span><input data-v92-bulk type="number" min="1" max="30" step="1" value="${Number(b.__bulk)||1}"><div class="v92-form-note">保存時に1枚ずつの明細へ分けます。</div></label>`}<label class="field"><span>撮影した部（任意）</span><input data-db-part value="${esc(b.part||'')}" placeholder="例：4部"></label></div><label class="switch-row"><div class="text"><b>チェキ代を支出へ反映</b><small>1枚分の金額を支出へ連携</small></div><span class="switch"><input data-db-expense type="checkbox" ${b.expenseEnabled?'checked':''}><i></i></span></label><label class="field"><span>1枚・1枠あたり単価</span><input data-db-unit type="number" min="0" step="1" value="${Number(b.unitPrice)||''}" placeholder="例：2000"></label>${G.state.settings.features.notes?`<label class="field"><span>メモ・エピソード</span><textarea data-db-note>${esc(b.note||'')}</textarea></label>`:''}${G.state.settings.features.attachments&&!bingo?`<input type="hidden" data-db-atts value='${esc(JSON.stringify(atts))}'><div class="benefit-image-strip" data-db-images>${benefitImagesHTML(atts)}</div><div class="cheki-image-actions"><button class="btn small" type="button" data-db-library ${atts.length?'disabled':''}>写真ライブラリ</button><button class="btn small" type="button" data-db-camera ${atts.length?'disabled':''}>カメラで撮影</button></div><div class="v92-form-note">チェキ1枚につき画像1枚。横チェキも切り抜き・90°回転に対応。</div>`:''}<button class="btn danger small" type="button" data-db-remove>この明細を削除</button></div></details>`};
  syncBenefitDraftFromUI=function(){if(!document.getElementById('benefitDraftList'))return;const bingo=document.getElementById('eventType')?.value==='online_bingo',out=[];qsa('[data-draft-benefit]',document.getElementById('benefitDraftList')).forEach(r=>{const base={id:r.dataset.draftBenefit,groupId:r.querySelector('[data-db-group]')?.value||'',memberId:r.querySelector('[data-db-member]')?.value||'',count:bingo?(Number(r.querySelector('[data-db-count]')?.value)||1):1,part:r.querySelector('[data-db-part]')?.value?.trim()||'',kind:bingo?'bingo':'cheki',note:r.querySelector('[data-db-note]')?.value||'',attachments:(()=>{try{return JSON.parse(r.querySelector('[data-db-atts]')?.value||'[]').slice(0,1)}catch{return[]}})(),expenseEnabled:!!r.querySelector('[data-db-expense]')?.checked,unitPrice:Number(r.querySelector('[data-db-unit]')?.value)||0,linkedExpenseId:'',acquisitionType:'現場撮影',tweet:{status:'unposted',description:'',postedAt:'',url:''}};if(!base.memberId&&!base.groupId)return;const n=bingo?1:Math.max(1,Math.min(30,Number(r.querySelector('[data-v92-bulk]')?.value)||1));for(let i=0;i<n;i++)out.push({...base,id:i===0?base.id:uid('b'),attachments:i===0?base.attachments:[]})});draftDetails().benefits=out};

  function v92AllChekis(){const rows=[];G.state.events.filter(e=>!e.deletedAt).forEach(e=>(e.benefits||[]).filter(b=>(b.kind||'cheki')!=='bingo').forEach(b=>rows.push({kind:'event',id:b.id,event:e,benefit:b,date:e.date,memberId:b.memberId,attachmentId:(b.attachments||[])[0]||'',acquisitionType:'現場撮影'})));(G.state.collectionChekis||[]).forEach(c=>rows.push({kind:'owned',id:c.id,owned:c,date:c.acquiredDate,memberId:c.memberId,attachmentId:c.attachmentId,acquisitionType:c.acquisitionType}));return rows.sort((a,b)=>String(b.date||'').localeCompare(String(a.date||'')))}
  function v92ChekiThumb(id){const a=attachmentById(id),src=a?mediaURL(a.path):'';return src?`<img src="${esc(src)}" alt="">`:'<span style="font-size:24px">▧</span>'}
  function v92AddChekiCollectionPanel(){document.getElementById('v92ChekiCollectionPanel')?.remove();const view=document.getElementById('eventsView'),listMode=document.getElementById('eventListMode');if(!view||!listMode)return;const p=document.createElement('div');p.id='v92ChekiCollectionPanel';p.className='v92-cheki-panel';const rows=v92AllChekis();p.innerHTML=`<div class="share-top"><div><b>チェキコレクション</b><div class="hint">現場で撮ったチェキも、もらった・買ったチェキもまとめて管理</div></div><button class="btn small primary" id="v92OpenCollection">${rows.length}枚を見る</button></div>`;listMode.insertAdjacentElement('beforebegin',p);document.getElementById('v92OpenCollection').onclick=v92OpenCollection}
  function v92OpenCollection(){const rows=v92AllChekis();setModal(`<div class="modal-head"><div><div class="guide-kicker">CHEKI COLLECTION</div><h2>チェキコレクション</h2></div><button class="close-btn" data-close>×</button></div><div class="panel"><div class="share-top"><div><b>${rows.length}枚</b><div class="hint">1枚ずつ画像・入手方法・チェキツイを管理できます。</div></div><button class="btn primary small" id="v92AddOwned">＋ チェキを追加</button></div></div><div class="v92-cheki-grid">${rows.map(r=>{const m=memberById(r.memberId);return `<button class="v92-cheki-card" data-v92-cheki="${r.kind}|${r.kind==='event'?r.event.id:''}|${r.id}"><div class="v92-cheki-thumb">${v92ChekiThumb(r.attachmentId)}</div><b>${esc(m?.name||'メンバー未設定')}</b><small>${esc(r.date||'日付未設定')}</small><span class="v92-acq-badge">${esc(r.acquisitionType)}</span></button>`}).join('')||'<div class="empty">チェキはまだありません</div>'}</div>`);qsa('[data-close]').forEach(b=>b.onclick=closeModal);document.getElementById('v92AddOwned').onclick=()=>v92OpenOwnedEditor();qsa('[data-v92-cheki]').forEach(b=>b.onclick=()=>{const [kind,eid,id]=b.dataset.v92Cheki.split('|');if(kind==='event')openChekiDetail(eid,id);else v92OpenOwnedDetail(id)})}
  function v92OpenOwnedEditor(id=''){const existing=id?(G.state.collectionChekis.find(x=>x.id===id)||(G.v92EditingOwned?.id===id?G.v92EditingOwned:null)):null,c=existing?clone(existing):{id:uid('oc'),memberId:'',acquiredDate:todayISO(),acquisitionType:'譲渡・もらいもの',source:'',price:0,shipping:0,note:'',attachmentId:'',tweet:{status:'unposted',description:'',postedAt:'',url:'',manualDate:'',manualEvent:'',manualPlace:''}};setSubModal(`<div class="modal-head"><h2>${id?'チェキを編集':'チェキを追加'}</h2><button class="close-btn" data-close>×</button></div><div class="panel"><label class="field"><span>メンバー</span><select id="v92OcMember">${memberOptions(c.memberId)}</select></label><div class="form-grid"><label class="field"><span>入手日</span><input id="v92OcDate" type="date" value="${c.acquiredDate}"></label><label class="field"><span>入手方法</span><select id="v92OcType">${V92_ACQUISITIONS.filter(x=>x!=='現場撮影').map(x=>`<option ${x===c.acquisitionType?'selected':''}>${x}</option>`).join('')}</select></label></div><label class="field"><span>入手元</span><input id="v92OcSource" value="${esc(c.source)}" placeholder="例：メルカリ / 友人 / 抽選会"></label><div class="form-grid"><label class="field"><span>購入価格</span><input id="v92OcPrice" type="number" min="0" value="${c.price||''}"></label><label class="field"><span>送料</span><input id="v92OcShipping" type="number" min="0" value="${c.shipping||''}"></label></div><label class="field"><span>メモ</span><textarea id="v92OcNote">${esc(c.note||'')}</textarea></label><div class="field"><span>チェキ画像</span><div class="v92-cheki-thumb" style="max-width:220px">${v92ChekiThumb(c.attachmentId)}</div><button class="btn small" id="v92OcPhoto">${c.attachmentId?'画像を変更':'画像を追加'}</button></div></div><div class="modal-foot"><button class="btn" data-close>取消</button><button class="btn primary" id="v92OcSave">保存</button></div>`);qsa('[data-close]').forEach(b=>b.onclick=closeSubModal);document.getElementById('v92OcPhoto').onclick=()=>native('pick-image-attachment',{target:'collection-cheki',chekiId:c.id,ratio:'free'});document.getElementById('v92OcSave').onclick=()=>{c.memberId=document.getElementById('v92OcMember').value;c.acquiredDate=document.getElementById('v92OcDate').value;c.acquisitionType=document.getElementById('v92OcType').value;c.source=document.getElementById('v92OcSource').value.trim();c.price=Number(document.getElementById('v92OcPrice').value)||0;c.shipping=Number(document.getElementById('v92OcShipping').value)||0;c.note=document.getElementById('v92OcNote').value;const i=G.state.collectionChekis.findIndex(x=>x.id===c.id);if(i>=0)G.state.collectionChekis[i]=c;else G.state.collectionChekis.push(c);persist();closeSubModal();closeModal();v92OpenCollection()};G.v92EditingOwned=c}
  function v92OpenOwnedDetail(id){const c=G.state.collectionChekis.find(x=>x.id===id);if(!c)return;const m=memberById(c.memberId);setSubModal(`<div class="modal-head"><h2>チェキ詳細</h2><button class="close-btn" data-close>×</button></div><div class="panel"><div class="profile-hero">${m?memberAvatarHTML(m):''}<div><h2 style="margin:0">${esc(m?.name||'メンバー未設定')}</h2><div class="event-meta">${esc(c.acquiredDate)} / ${esc(c.acquisitionType)}</div></div></div></div><div class="panel"><div class="v92-cheki-thumb">${v92ChekiThumb(c.attachmentId)}</div>${c.source?`<div class="hint">入手元：${esc(c.source)}</div>`:''}${c.price||c.shipping?`<div class="hint">支出：${yen(c.price+c.shipping)}</div>`:''}${c.note?`<div class="detail-text">${esc(c.note)}</div>`:''}</div><div class="modal-foot"><button class="btn" id="v92OwnedTweet">チェキツイ</button><button class="btn" id="v92OwnedEdit">編集</button><button class="btn danger" id="v92OwnedDelete">削除</button></div>`);qsa('[data-close]').forEach(b=>b.onclick=closeSubModal);document.getElementById('v92OwnedTweet').onclick=()=>v92OpenChekiTweet({kind:'owned',owned:c});document.getElementById('v92OwnedEdit').onclick=()=>v92OpenOwnedEditor(c.id);document.getElementById('v92OwnedDelete').onclick=()=>confirmModal('チェキを削除','このチェキをコレクションから削除します。',()=>{G.state.collectionChekis=G.state.collectionChekis.filter(x=>x.id!==c.id);persist();closeSubModal();closeModal();v92OpenCollection()},{danger:true})}
  const _v92NativeAttachment=window.GEMS_NATIVE_ATTACHMENT;window.GEMS_NATIVE_ATTACHMENT=function(meta,ctx={}){if(ctx.target==='collection-cheki'){if(!meta?.id)return;if(!G.state.attachments.some(x=>x.id===meta.id))G.state.attachments.push(meta);let c=G.state.collectionChekis.find(x=>x.id===ctx.chekiId);if(!c&&G.v92EditingOwned?.id===ctx.chekiId)c=G.v92EditingOwned;if(c)c.attachmentId=meta.id;if(G.v92EditingOwned?.id===ctx.chekiId)G.v92EditingOwned.attachmentId=meta.id;persist();closeCropper();v92OpenOwnedEditor(ctx.chekiId);return}_v92NativeAttachment(meta,ctx)};

  function v92TweetText(ctx){if(ctx.kind==='event'){const e=ctx.event,b=ctx.benefit,desc=b.tweet?.description||'',place=eventVenue(e)||'';return `${Number(e.date.slice(0,4))}年${Number(e.date.slice(5,7))}月${Number(e.date.slice(8,10))}日${e.name}${place?`📍${place}`:''}\n${desc}\n\n✨GEMSでチェキを自慢しちゃおう✨\n#GEMS`}const c=ctx.owned,t=c.tweet||{},d=t.manualDate||c.acquiredDate||'',head=d?`${Number(d.slice(0,4))}年${Number(d.slice(5,7))}月${Number(d.slice(8,10))}日`:'';return `${head}${t.manualEvent||''}${t.manualPlace?`📍${t.manualPlace}`:''}\n${t.description||''}\n\n✨GEMSでチェキを自慢しちゃおう✨\n#GEMS`}
  function v92OpenChekiTweet(ctx){const rec=ctx.kind==='event'?ctx.benefit:ctx.owned;rec.tweet={status:'unposted',description:'',postedAt:'',url:'',manualDate:'',manualEvent:'',manualPlace:'',...(rec.tweet||{})};const isOwned=ctx.kind==='owned',aid=isOwned?ctx.owned.attachmentId:(ctx.benefit.attachments||[])[0]||'';setSubModal(`<div class="modal-head"><div><div class="guide-kicker">CHEKI POST</div><h2>チェキツイ</h2></div><button class="close-btn" data-close>×</button></div><div class="panel"><label class="field"><span>チェキ説明文</span><textarea id="v92TweetDesc" rows="4" placeholder="このチェキの思い出を書こう">${esc(rec.tweet.description||'')}</textarea></label>${isOwned?`<div class="form-grid"><label class="field"><span>日付（任意）</span><input id="v92TweetDate" type="date" value="${esc(rec.tweet.manualDate||ctx.owned.acquiredDate||'')}"></label><label class="field"><span>イベント名（任意）</span><input id="v92TweetEvent" value="${esc(rec.tweet.manualEvent||'')}"></label><label class="field full"><span>場所（任意）</span><input id="v92TweetPlace" value="${esc(rec.tweet.manualPlace||'')}"></label></div>`:''}<label class="field"><span>状態</span><select id="v92TweetStatus"><option value="unposted">未投稿</option><option value="draft">下書き</option><option value="posted">投稿済み</option></select></label><div class="v92-tweet-preview" id="v92TweetPreview"></div></div><div class="modal-foot"><button class="btn" id="v92TweetCopy">文面をコピー</button><button class="btn primary" id="v92TweetShare">画像と共有</button></div>`);document.getElementById('v92TweetStatus').value=rec.tweet.status||'unposted';const update=()=>{rec.tweet.description=document.getElementById('v92TweetDesc').value;rec.tweet.status=document.getElementById('v92TweetStatus').value;if(isOwned){rec.tweet.manualDate=document.getElementById('v92TweetDate').value;rec.tweet.manualEvent=document.getElementById('v92TweetEvent').value;rec.tweet.manualPlace=document.getElementById('v92TweetPlace').value}const txt=v92TweetText(ctx),img=v92ChekiThumb(aid);document.getElementById('v92TweetPreview').innerHTML=`${esc(txt).replace(/\n/g,'<br>')}${aid?`<div class="v92-cheki-thumb" style="margin-top:10px">${img}</div>`:''}`;persist();return txt};['v92TweetDesc','v92TweetStatus','v92TweetDate','v92TweetEvent','v92TweetPlace'].forEach(id=>{const el=document.getElementById(id);if(el)el.oninput=update});update();qsa('[data-close]').forEach(b=>b.onclick=()=>{update();closeSubModal()});document.getElementById('v92TweetCopy').onclick=()=>{const txt=update();if(navigator.clipboard?.writeText)navigator.clipboard.writeText(txt).then(()=>toast('文面をコピーしました'));else native('share',{text:txt,attachmentIds:[]})};document.getElementById('v92TweetShare').onclick=()=>{const txt=update();native('share',{text:txt,attachmentIds:aid?[aid]:[]});rec.tweet.status='posted';rec.tweet.postedAt=new Date().toISOString();persist()}}
  const _v92OpenChekiDetail=openChekiDetail;openChekiDetail=function(eventId,benefitId){_v92OpenChekiDetail(eventId,benefitId);const e=G.state.events.find(x=>x.id===eventId),b=e?.benefits?.find(x=>x.id===benefitId);if(!e||!b)return;const foot=document.querySelector('#subModalSheet .modal-foot');if(foot&&!document.getElementById('v92EventTweet')){foot.insertAdjacentHTML('afterbegin','<button class="btn" id="v92EventTweet">チェキツイ</button>');document.getElementById('v92EventTweet').onclick=()=>v92OpenChekiTweet({kind:'event',event:e,benefit:b})}};

  // Standalone collection expenses join normal analysis without adding any person-days/event count.
  const _v92AnalysisData=analysisData;analysisData=function(kind,key,scope='all'){const a=_v92AnalysisData(kind,key,scope),range=periodRange(kind,key),rows=(G.state.collectionChekis||[]).filter(c=>c.acquiredDate&&(!range.start||c.acquiredDate>=range.start)&&(!range.end||c.acquiredDate<=range.end)),cost=sum(rows,c=>(Number(c.price)||0)+(Number(c.shipping)||0));if(cost){a.totalExpenses+=cost;a.eventExpenses+=cost;a.expenseCats['チェキ購入・送料']=(a.expenseCats['チェキ購入・送料']||0)+cost}rows.forEach(c=>{if(c.memberId){a.chekiMembers[c.memberId]=(a.chekiMembers[c.memberId]||0)+1;const gs=memberGroups(c.memberId,c.acquiredDate||'');if(gs[0])a.chekiGroups[gs[0]]=(a.chekiGroups[gs[0]]||0)+1}});a.chekiTotal+=rows.length;return a};

  function v92MonthlyMetric(year,metric,mode){const months=Array.from({length:12},(_,i)=>`${year}-${String(i+1).padStart(2,'0')}`),series=[];if(mode==='groups'){G.state.groups.filter(g=>g.active!==false&&g.name!=='櫻井優衣（ソロ）').forEach(g=>{const vals=months.map(m=>v92GroupMonth(g.id,m,metric));if(vals.some(v=>v>0))series.push({id:g.id,name:g.name,vals})})}else{G.state.members.filter(m=>m.favorite&&m.active!==false).forEach(mem=>{const vals=months.map(m=>v92MemberMonth(mem.id,m,metric));series.push({id:mem.id,name:mem.name,vals})})}return{months,series}}
  function v92GroupMonth(gid,m,metric){const ev=G.state.events.filter(e=>!e.deletedAt&&e.type!=='schedule'&&String(e.date||'').startsWith(m)&&(e.groupIds||[]).includes(gid));if(metric==='events')return ev.reduce((n,e)=>n+eventCount(e),0);if(metric==='days')return round2(ev.reduce((n,e)=>n+(groupEventAlloc(e)[gid]||0),0));if(metric==='cheki')return ev.reduce((n,e)=>n+(e.benefits||[]).filter(b=>resolveBenefitGroup(b,e)===gid&&(b.kind||'cheki')!=='bingo').length,0);if(metric==='expenses'){let n=0;ev.forEach(e=>{const groups=(e.groupIds||[]).length||1;n+=expenseTotal(e)/groups});return Math.round(n)}return 0}

  function v92MemberMonth(mid,m,metric){const mem=memberById(mid);if(!mem)return 0;const related=G.state.events.filter(e=>!e.deletedAt&&e.type!=='schedule'&&String(e.date||'').startsWith(m)&&memberGroups(mid,e.date||'').some(g=>(e.groupIds||[]).includes(g)));if(metric==='events')return related.reduce((n,e)=>n+eventCount(e),0);if(metric==='cheki'){const inEvent=related.reduce((n,e)=>n+(e.benefits||[]).filter(b=>b.memberId===mid&&(b.kind||'cheki')!=='bingo').length,0),owned=(G.state.collectionChekis||[]).filter(c=>c.memberId===mid&&String(c.acquiredDate||'').startsWith(m)).length;return inEvent+owned}if(metric==='days'){return round2(related.reduce((n,e)=>{const gs=memberGroups(mid,e.date||'').filter(g=>(e.groupIds||[]).includes(g));return n+(gs.length?(sum(gs,g=>groupEventAlloc(e)[g]||0)/Math.max(1,G.state.members.filter(x=>x.active!==false&&gs.some(g=>memberGroups(x.id,e.date||'').includes(g))).length)):0)},0))}if(metric==='expenses'){let n=0;related.forEach(e=>{const mine=(e.benefits||[]).filter(b=>b.memberId===mid);n+=mine.reduce((z,b)=>z+(b.expenseEnabled?Number(b.unitPrice)||0:0),0)});(G.state.collectionChekis||[]).filter(c=>c.memberId===mid&&String(c.acquiredDate||'').startsWith(m)).forEach(c=>n+=(Number(c.price)||0)+(Number(c.shipping)||0));return Math.round(n)}return 0}
  const V92_PALETTE=['#e85b78','#4ca784','#5887d9','#9a70d2','#eb9a3c','#55bfd4','#8f9aa6','#d875b2','#76b95c','#d56b4d','#5778a4','#a67c52'];
  function v92ChartSVG(data,hidden){const W=620,H=255,pad={l:38,r:12,t:15,b:32},max=Math.max(1,...data.series.filter(s=>!hidden.has(s.id)).flatMap(s=>s.vals)),x=i=>pad.l+i*(W-pad.l-pad.r)/11,y=v=>H-pad.b-(v/max)*(H-pad.t-pad.b);let svg=`<svg viewBox="0 0 ${W} ${H}" role="img">`;for(let i=0;i<=4;i++){const yy=pad.t+i*(H-pad.t-pad.b)/4,val=max*(1-i/4);svg+=`<line class="v92-chart-grid" x1="${pad.l}" y1="${yy}" x2="${W-pad.r}" y2="${yy}"/><text class="v92-chart-axis" x="${pad.l-5}" y="${yy+3}" text-anchor="end">${Math.round(val*10)/10}</text>`}data.months.forEach((m,i)=>svg+=`<text class="v92-chart-axis" x="${x(i)}" y="${H-10}" text-anchor="middle">${i+1}月</text>`);data.series.forEach((s,si)=>{if(hidden.has(s.id))return;const col=V92_PALETTE[si%V92_PALETTE.length],pts=s.vals.map((v,i)=>`${x(i)},${y(v)}`).join(' ');svg+=`<polyline class="v92-chart-line" stroke="${col}" points="${pts}"/>`;s.vals.forEach((v,i)=>svg+=`<circle class="v92-chart-dot" fill="${col}" cx="${x(i)}" cy="${y(v)}" r="3"><title>${esc(s.name)} ${i+1}月: ${v}</title></circle>`)});return svg+'</svg>'}
  function v92EnsureAnalysisChart(){const view=document.getElementById('analysisView'),kpi=document.getElementById('analysisKpis');if(!view||!kpi)return;let p=document.getElementById('v92MonthlyChartPanel');if(!p){p=document.createElement('div');p.id='v92MonthlyChartPanel';p.className='panel v92-gem-card';p.innerHTML=`<div class="section-title mini"><div><h3>月ごとの推移</h3><p>グループ別・推し別の線を重ねて比較</p></div></div><div class="v92-chart-controls"><button class="btn small active" data-v92-mode="groups">グループ別</button><button class="btn small" data-v92-mode="favorites">推し別</button><select id="v92Metric"><option value="events">現場数</option><option value="days">Carat</option><option value="expenses">支出額</option><option value="cheki">チェキ枚数</option></select></div><div class="v92-chart-wrap"><div class="v92-chart" id="v92Chart"></div></div><div class="v92-chart-legend" id="v92Legend"></div>`;kpi.insertAdjacentElement('beforebegin',p);G.v92ChartMode=G.v92ChartMode||'groups';G.v92ChartHidden=G.v92ChartHidden||new Set();qsa('[data-v92-mode]').forEach(b=>b.onclick=()=>{G.v92ChartMode=b.dataset.v92Mode;G.v92ChartHidden=new Set();qsa('[data-v92-mode]').forEach(x=>x.classList.toggle('active',x===b));v92RenderChart()});document.getElementById('v92Metric').onchange=()=>{G.v92ChartHidden=new Set();v92RenderChart()}}v92RenderChart()}
  function v92RenderChart(){const year=Number(document.getElementById('analysisYear')?.value)||new Date().getFullYear(),metric=document.getElementById('v92Metric')?.value||'events',data=v92MonthlyMetric(year,metric,G.v92ChartMode==='favorites'?'favorites':'groups'),hidden=G.v92ChartHidden||new Set();document.getElementById('v92Chart').innerHTML=data.series.length?v92ChartSVG(data,hidden):'<div class="empty">表示できるデータがありません</div>';document.getElementById('v92Legend').innerHTML=data.series.map((s,i)=>`<button class="v92-legend ${hidden.has(s.id)?'off':''}" data-v92-leg="${s.id}"><span style="color:${V92_PALETTE[i%V92_PALETTE.length]}">●</span> ${esc(s.name)}</button>`).join('');qsa('[data-v92-leg]').forEach(b=>b.onclick=()=>{const id=b.dataset.v92Leg;if(hidden.has(id))hidden.delete(id);else hidden.add(id);v92RenderChart()})}
  const _v92RenderAnalysis=renderAnalysis;renderAnalysis=function(){_v92RenderAnalysis();v92EnsureAnalysisChart()};

  function v92FeedbackConfigUI(){const pane=document.getElementById('settingsPane_developer');if(!pane||document.getElementById('v92FeedbackGoogle'))return;const f=G.state.settings.feedbackGoogleForm||{};pane.insertAdjacentHTML('beforeend',`<div class="v9-dev-card" id="v92FeedbackGoogle"><h4>Googleフォーム（フィードバック送信先）</h4><div class="hint">フォームの formResponse URL と entry ID を設定すると、他のユーザーからの回答も同じGoogleフォームへ集約できます。未設定時は端末内に保存します。</div><label class="field"><span>formResponse URL</span><input id="v92GfUrl" value="${esc(f.actionUrl||'')}" placeholder="https://docs.google.com/forms/d/e/.../formResponse"></label><div class="form-grid"><label class="field"><span>種別 entry</span><input id="v92GfCategory" value="${esc(f.category||'')}"></label><label class="field"><span>画面 entry</span><input id="v92GfScreen" value="${esc(f.screen||'')}"></label><label class="field full"><span>本文 entry</span><input id="v92GfMessage" value="${esc(f.message||'')}"></label></div><button class="btn small primary" id="v92GfSave">送信先を保存</button></div>`);document.getElementById('v92GfSave').onclick=()=>{G.state.settings.feedbackGoogleForm={...G.state.settings.feedbackGoogleForm,actionUrl:document.getElementById('v92GfUrl').value.trim(),category:document.getElementById('v92GfCategory').value.trim(),screen:document.getElementById('v92GfScreen').value.trim(),message:document.getElementById('v92GfMessage').value.trim()};persist();toast('Googleフォーム設定を保存しました')}}
  const _v92OpenFeedback=window.openFeedbackForm;window.openFeedbackForm=function(reopen=false){_v92OpenFeedback(reopen);const send=document.getElementById('v9FbSend');if(send){const old=send.onclick;send.onclick=()=>{const cat=document.getElementById('v9FbCategory')?.value||'',screen=document.getElementById('v9FbScreen')?.value||'',message=document.getElementById('v9FbMessage')?.value||'',f=G.state.settings.feedbackGoogleForm||{};old?.();if(f.actionUrl&&f.category&&f.screen&&f.message)native('google-form-feedback',{url:f.actionUrl,fields:{[f.category]:cat,[f.screen]:screen,[f.message]:message}})}}};

  function v92PostRender(){v92ApplyLight();document.getElementById('quickAddBtn')?.remove();const mode=document.getElementById('appearanceMode');if(mode){mode.value='light';const mf=mode.closest('.field');if(mf)mf.style.display='none'}const merchTab=document.querySelector('[data-settings-sub="merch"]');if(merchTab)merchTab.style.display='none';const merchPane=document.getElementById('settingsSub_merch');if(merchPane)merchPane.style.display='none';v92FeedbackConfigUI();v92SetupFavoritePanel();const prev=document.getElementById('v9PreviewStart');if(prev)prev.onclick=v92EnterPreview;const status=document.getElementById('v9XAvatarStatus');if(status){const all=v92XTargets(false),done=all.filter(t=>(t.entityType==='member'?memberById(t.id):groupById(t.id))?.iconAttachmentId).length;status.textContent=`取得済み ${done} / ${all.length}件`}}
