  function v93EventVisualAttachments(e){const ids=[];v92SafeArray(e?.attachments).forEach(id=>ids.push(id));v92SafeArray(e?.benefits).forEach(b=>v92SafeArray(b.attachments).forEach(id=>ids.push(id)));const seen=new Set();return ids.filter(id=>id&&!seen.has(id)&&seen.add(id)).map(attachmentById).filter(Boolean)}
  function v93EventMembers(e){const ids=[];v92SafeArray(e?.benefits).forEach(b=>{if(b.memberId)ids.push(b.memberId)});if(!ids.length)v92SafeArray(e?.groupIds).forEach(gid=>G.state.members.filter(m=>m.active!==false&&memberGroups(m.id,e?.date||'').includes(gid)).forEach(m=>ids.push(m.id)));return [...new Set(ids)].map(memberById).filter(Boolean)}
  function v93TodayCard(e){const vis=v93EventVisualAttachments(e),a=vis[0],src=a?mediaURL(a.path):'',members=v93EventMembers(e),one=members.slice(0,12).map(m=>`<span class="v93-today-member">${memberAvatarHTML(m,'')}</span>`).join(''),dur=Math.max(12,(Math.max(1,members.length)*88)/24),time=e.time?String(e.time).slice(0,5):'';return `<article class="v93-today-card ${src?'':'no-photo'}" data-v93-today="${e.id}">${src?`<div class="v93-today-bg"><img src="${esc(src)}" alt=""></div>`:(one?`<div class="v93-today-members"><div class="v93-today-member-track" style="--v93-dur:${dur}s">${one}${one}</div></div>`:'')}<span class="v93-today-badge">TODAY'S GEMS</span><div class="v93-today-content"><h2>${esc(e.name)}</h2><div class="v93-today-meta">${esc(eventGroupNames(e)||'')}${eventVenue(e)?`<br>📍 ${esc(eventVenue(e))}`:''}${time?`　${esc(time)}`:''}</div><div class="v93-today-actions"><button type="button" data-v93-today-open="${e.id}">現場を開く</button><button type="button" data-v93-today-photo="${e.id}">＋ 写真</button><button type="button" data-v93-today-cheki="${e.id}">＋ チェキ</button></div></div></article>`}
  function v93RenderTodayHero(forceEvent=null){document.getElementById('v93TodayWrap')?.remove();const home=document.getElementById('homeView'),hero=document.getElementById('homeHero');if(!home||!hero)return;let rows=forceEvent?[forceEvent]:G.state.events.filter(e=>!e.deletedAt&&e.type!=='schedule'&&e.date===todayISO());if(!rows.length)return;rows=rows.slice().sort((a,b)=>String(a.time||'').localeCompare(String(b.time||'')));const w=document.createElement('section');w.id='v93TodayWrap';w.className='v93-today-wrap';w.innerHTML=`<div class="v93-today-head"><div><div class="k">TODAY</div><b>今日の現場</b></div><small>${rows.length>1?`${rows.length}現場・横にスワイプ`: '当日の記録をすぐ追加'}</small></div><div class="v93-today-track">${rows.map(v93TodayCard).join('')}</div>${rows.length>1?`<div class="v93-today-dots">● ${'○ '.repeat(rows.length-1)}</div>`:''}`;hero.insertAdjacentElement('afterend',w);qsa('[data-v93-today-open]',w).forEach(b=>b.onclick=()=>openEventDetail(b.dataset.v93TodayOpen));qsa('[data-v93-today-photo]',w).forEach(b=>b.onclick=()=>v93OpenEventTool(b.dataset.v93TodayPhoto,'photo'));qsa('[data-v93-today-cheki]',w).forEach(b=>b.onclick=()=>v93OpenEventTool(b.dataset.v93TodayCheki,'cheki'))}
  function v93OpenEventTool(id,tool){openEventForm(id);setTimeout(()=>{try{if(tool==='photo')openEventPhotoManager();else openBenefitManager()}catch(err){console.error('TODAY quick action failed',err);toast(tool==='photo'?'写真を追加できませんでした':'チェキ明細を開けませんでした')}},90)}
  const _v93RenderHome=renderHome;renderHome=function(){_v93RenderHome();v93RenderTodayHero()};

  // GEMS DIGEST: event photos and cheki photos are equal visual candidates.
  memoryEventCard=function(e,label=''){if(!e)return'<div class="digest-empty">表示できる過去現場がまだありません。</div>';const visuals=v93EventVisualAttachments(e),a=visuals[0],src=a?mediaURL(a.path):'',eventPhotoIds=new Set(v92SafeArray(e.attachments)),isCheki=!!a&&!eventPhotoIds.has(a.id),cheki=(e.benefits||[]).filter(b=>(b.kind||'cheki')!=='bingo').length;return `${src?`<div class="digest-photo"><img src="${esc(src)}" alt=""><span class="digest-photo-label">${esc(label||fmtDate(e.date))}</span>${isCheki?'<span class="v93-digest-cheki-label">CHEKI PHOTO</span>':''}</div>`:''}<div class="digest-memory-title">${esc(e.name)}</div><div class="digest-meta">${esc(fmtDate(e.date))} ・ ${esc(eventGroupNames(e))}${eventVenue(e)?`<br>${esc(eventVenue(e))}`:''}</div><div class="digest-stat-row"><div class="digest-stat"><b>${eventWorkdays(e).toFixed(2)}</b><span>GEM Carat</span></div><div class="digest-stat"><b>${cheki}</b><span>チェキ</span></div><div class="digest-stat"><b>${yen(expenseTotal(e))}</b><span>支出</span></div></div><div class="digest-actions"><button class="btn small" data-event-open="${e.id}">開く</button></div>`}

  function v93TweetObject(rec){rec.tweet={status:'unposted',description:'',postedAt:'',url:'',manualDate:'',manualEvent:'',manualPlace:'',...(rec.tweet||{})};return rec.tweet}
  v92TweetText=function(ctx){if(ctx.kind==='event'){const e=ctx.event,b=ctx.benefit,t=v93TweetObject(b),desc=String(t.description||'').trim(),place=eventVenue(e)||'',d=String(e.date||'');const head=d?`${Number(d.slice(0,4))}年${Number(d.slice(5,7))}月${Number(d.slice(8,10))}日`:'';return `${head}${e.name||''}${place?`📍${place}`:''}${desc?`\n${desc}`:''}\n\n✨GEMSでチェキを自慢しちゃおう✨\n#GEMS`}const c=ctx.owned,t=v93TweetObject(c),d=t.manualDate||c.acquiredDate||'',head=d?`${Number(d.slice(0,4))}年${Number(d.slice(5,7))}月${Number(d.slice(8,10))}日`:'';return `${head}${t.manualEvent||''}${t.manualPlace?`📍${t.manualPlace}`:''}${t.description?`\n${t.description}`:''}\n\n✨GEMSでチェキを自慢しちゃおう✨\n#GEMS`}
  function v93SetTweetStatus(t,status){const prev=t.status;t.status=status;if(status==='posted'&&!t.postedAt)t.postedAt=new Date().toISOString();if(status!=='posted'&&prev==='posted')t.postedAt=t.postedAt||''}
  function v93ShareCheki(text,aid,imageOnly=false){const requestId=uid('share');G.v93ShareRequest=requestId;native('share-cheki',{requestId,text,attachmentIds:aid?[aid]:[],requireImage:true,imageOnly});return requestId}
  window.GEMS_NATIVE_SHARE_RESULT=function(result){G.v93LastShareResult=result||{};const box=document.getElementById('v93ShareResult')||document.getElementById('v92ShareResult');if(box)box.textContent=result?.ok?`共有シートを閉じました${result.sharedImageCount?`（画像${result.sharedImageCount}枚）`:''}。Xへの投稿完了は「投稿済み」で記録してね。`:`共有できませんでした：${result?.error||'不明なエラー'}`;toast(result?.ok?'共有シートを閉じました':'共有に失敗しました')}
  function v93CopyText(txt){if(navigator.clipboard?.writeText)navigator.clipboard.writeText(txt).then(()=>toast('文面をコピーしました')).catch(()=>native('share',{text:txt,attachmentIds:[]}));else native('share',{text:txt,attachmentIds:[]})}

  v92OpenChekiTweet=function(ctx){const rec=ctx.kind==='event'?ctx.benefit:ctx.owned,t=v93TweetObject(rec),isOwned=ctx.kind==='owned',aid=isOwned?ctx.owned.attachmentId:(ctx.benefit.attachments||[])[0]||'';setSubModal(`<div class="modal-head"><div><div class="guide-kicker">CHEKI POST</div><h2>チェキツイ</h2></div><button class="close-btn" data-close>×</button></div><div class="panel"><label class="field"><span>チェキ説明文</span><textarea id="v92TweetDesc" rows="4" placeholder="このチェキの思い出を書こう">${esc(t.description||'')}</textarea></label>${isOwned?`<div class="form-grid"><label class="field"><span>日付（任意）</span><input id="v92TweetDate" type="date" value="${esc(t.manualDate||ctx.owned.acquiredDate||'')}"></label><label class="field"><span>イベント名（任意）</span><input id="v92TweetEvent" value="${esc(t.manualEvent||'')}"></label><label class="field full"><span>場所（任意）</span><input id="v92TweetPlace" value="${esc(t.manualPlace||'')}"></label></div>`:''}<div class="form-grid"><label class="field"><span>状態</span><select id="v92TweetStatus"><option value="unposted">未投稿</option><option value="draft">下書き</option><option value="posted">投稿済み</option></select></label><label class="field"><span>投稿日時</span><input id="v92TweetPostedAt" type="datetime-local"></label><label class="field full"><span>投稿URL（任意）</span><input id="v92TweetUrl" value="${esc(t.url||'')}" placeholder="https://x.com/..."></label></div><div class="v92-tweet-preview" id="v92TweetPreview"></div><div class="v93-share-result" id="v92ShareResult">共有しただけでは自動で「投稿済み」にはなりません。</div></div><div class="modal-foot"><button class="btn" id="v92TweetCopy">本文コピー</button><button class="btn" id="v92TweetImageOnly" ${aid?'':'disabled'}>画像だけ共有</button><button class="btn primary" id="v92TweetShare" ${aid?'':'disabled'}>本文＋画像で共有</button></div>`);document.getElementById('v92TweetStatus').value=t.status||'unposted';document.getElementById('v92TweetPostedAt').value=t.postedAt?String(t.postedAt).slice(0,16):'';const update=()=>{t.description=document.getElementById('v92TweetDesc').value;v93SetTweetStatus(t,document.getElementById('v92TweetStatus').value);const pa=document.getElementById('v92TweetPostedAt').value;t.postedAt=pa?new Date(pa).toISOString():'';t.url=document.getElementById('v92TweetUrl').value.trim();if(isOwned){t.manualDate=document.getElementById('v92TweetDate').value;t.manualEvent=document.getElementById('v92TweetEvent').value;t.manualPlace=document.getElementById('v92TweetPlace').value}const txt=v92TweetText(ctx),img=v92ChekiThumb(aid);document.getElementById('v92TweetPreview').innerHTML=`${esc(txt).replace(/\n/g,'<br>')}${aid?`<div class="v92-cheki-thumb" style="margin-top:10px">${img}</div>`:'<div class="warning-box" style="margin-top:10px">画像がありません。画像付き共有を使うにはチェキ画像を登録してね。</div>'}`;persist();return txt};['v92TweetDesc','v92TweetStatus','v92TweetPostedAt','v92TweetUrl','v92TweetDate','v92TweetEvent','v92TweetPlace'].forEach(id=>{const el=document.getElementById(id);if(el)el.oninput=update});update();qsa('[data-close]',document.getElementById('subModalSheet')).forEach(b=>b.onclick=()=>{update();closeSubModal()});document.getElementById('v92TweetCopy').onclick=()=>v93CopyText(update());document.getElementById('v92TweetShare').onclick=()=>v93ShareCheki(update(),aid,false);document.getElementById('v92TweetImageOnly').onclick=()=>v93ShareCheki('',aid,true)}

  function v93DraftTweetText(b){const snap=currentEventSnapshot(G.formSeedEvent||{});return v92TweetText({kind:'event',event:snap,benefit:b})}
  function v93InlineTweetHTML(b){const t=v93TweetObject(b),aid=(b.attachments||[])[0]||'';return `<details class="v93-tweet-inline" data-v93-tweet-box><summary>✨ チェキツイ ${t.status==='posted'?'・投稿済み':t.status==='draft'?'・下書き':''}</summary><label class="field"><span>チェキ説明文</span><textarea data-v93-tweet-desc placeholder="このチェキの思い出を書こう">${esc(t.description||'')}</textarea></label><div class="form-grid"><label class="field"><span>状態</span><select data-v93-tweet-status><option value="unposted" ${t.status==='unposted'?'selected':''}>未投稿</option><option value="draft" ${t.status==='draft'?'selected':''}>下書き</option><option value="posted" ${t.status==='posted'?'selected':''}>投稿済み</option></select></label><label class="field"><span>投稿URL</span><input data-v93-tweet-url value="${esc(t.url||'')}" placeholder="任意"></label></div><div class="v93-tweet-actions"><button class="btn small" type="button" data-v93-tweet-copy>本文コピー</button><button class="btn small" type="button" data-v93-tweet-image ${aid?'':'disabled'}>画像だけ</button><button class="btn small primary" type="button" data-v93-tweet-share ${aid?'':'disabled'}>本文＋画像</button></div><div class="v93-tweet-status-note">共有後も自動で投稿済みにはしません。Xへ投稿できたら状態を「投稿済み」に変更してね。</div></details>`}
  const _v93BenefitEditor=benefitEditorHTML;benefitEditorHTML=function(b={},index=0){let h=_v93BenefitEditor(b,index);if((b.kind||'cheki')==='bingo'||document.getElementById('eventType')?.value==='online_bingo')return h;const tools=`<div class="v93-cheki-tools"><button class="btn small" type="button" data-v93-legacy-scan-guide>📷 GEMS SCAN</button></div>${v93InlineTweetHTML(b)}`;return h.replace('<button class="btn danger small" type="button" data-db-remove>',tools+'<button class="btn danger small" type="button" data-db-remove>')}
  syncBenefitDraftFromUI=function(){if(!document.getElementById('benefitDraftList'))return;const bingo=document.getElementById('eventType')?.value==='online_bingo',old=new Map(v92SafeArray(draftDetails().benefits).map(b=>[b.id,b])),out=[];qsa('[data-draft-benefit]',document.getElementById('benefitDraftList')).forEach(r=>{const prev=old.get(r.dataset.draftBenefit)||{},tweet={status:'unposted',description:'',postedAt:'',url:'',...(prev.tweet||{})};const desc=r.querySelector('[data-v93-tweet-desc]'),status=r.querySelector('[data-v93-tweet-status]'),url=r.querySelector('[data-v93-tweet-url]');if(desc)tweet.description=desc.value;if(status)v93SetTweetStatus(tweet,status.value);if(url)tweet.url=url.value.trim();const base={id:r.dataset.draftBenefit,groupId:r.querySelector('[data-db-group]')?.value||'',memberId:r.querySelector('[data-db-member]')?.value||'',count:bingo?(Number(r.querySelector('[data-db-count]')?.value)||1):1,part:r.querySelector('[data-db-part]')?.value?.trim()||'',kind:bingo?'bingo':'cheki',note:r.querySelector('[data-db-note]')?.value||'',attachments:(()=>{try{return JSON.parse(r.querySelector('[data-db-atts]')?.value||'[]').slice(0,1)}catch{return[]}})(),expenseEnabled:!!r.querySelector('[data-db-expense]')?.checked,unitPrice:Number(r.querySelector('[data-db-unit]')?.value)||0,linkedExpenseId:'',acquisitionType:'現場撮影',tweet};if(!base.memberId&&!base.groupId)return;const n=bingo?1:Math.max(1,Math.min(30,Number(r.querySelector('[data-v92-bulk]')?.value)||1));for(let i=0;i<n;i++)out.push({...base,id:i===0?base.id:uid('b'),attachments:i===0?base.attachments:[],tweet:i===0?clone(tweet):{status:'unposted',description:'',postedAt:'',url:''}})});draftDetails().benefits=out}
  const _v93BindBenefitDraft=bindBenefitDraft;bindBenefitDraft=function(){_v93BindBenefitDraft();qsa('[data-v93-legacy-scan-guide]').forEach(b=>b.onclick=v93OpenLegacyScanGuide);qsa('[data-v93-tweet-copy]').forEach(btn=>btn.onclick=()=>{syncBenefitDraftFromUI();const id=btn.closest('[data-draft-benefit]')?.dataset.draftBenefit,b=draftDetails().benefits.find(x=>x.id===id);if(b)v93CopyText(v93DraftTweetText(b))});qsa('[data-v93-tweet-share]').forEach(btn=>btn.onclick=()=>{syncBenefitDraftFromUI();const id=btn.closest('[data-draft-benefit]')?.dataset.draftBenefit,b=draftDetails().benefits.find(x=>x.id===id),aid=(b?.attachments||[])[0]||'';if(b&&aid)v93ShareCheki(v93DraftTweetText(b),aid,false)});qsa('[data-v93-tweet-image]').forEach(btn=>btn.onclick=()=>{syncBenefitDraftFromUI();const id=btn.closest('[data-draft-benefit]')?.dataset.draftBenefit,b=draftDetails().benefits.find(x=>x.id===id),aid=(b?.attachments||[])[0]||'';if(aid)v93ShareCheki('',aid,true)});qsa('[data-v93-tweet-desc],[data-v93-tweet-status],[data-v93-tweet-url]').forEach(el=>el.onchange=syncBenefitDraftFromUI)}
