    benefitEditorHTML = v970BenefitEditorHTML;

    syncBenefitDraftFromUI = function(){
      const list = document.getElementById('benefitDraftList');
      if(!list) return;
      const type = v970Type();
      const old = new Map(v92SafeArray(draftDetails().benefits).map(b=>[b.id,b]));
      const out = [];
      qsa('[data-draft-benefit]',list).forEach(r=>{
        const prev = old.get(r.dataset.draftBenefit) || {};
        const isCheki = (r.querySelector('[data-v970-mode]')?.value||'cheki')==='cheki';
        const qty = isCheki ? 1 : Math.max(0, Number(r.querySelector('[data-db-count]')?.value)||0);
        const tweet = typeof v960CleanTweet==='function' ? v960CleanTweet(prev.tweet||{}, false) : (prev.tweet||{description:'',comment:'',altEnabled:false});
        const desc = r.querySelector('[data-v93-tweet-desc]'), comment = r.querySelector('[data-v960-tweet-comment]'), alt = r.querySelector('[data-v960-tweet-alt]');
        if(desc) tweet.description = desc.value;
        if(comment) tweet.comment = comment.value;
        if(alt) tweet.altEnabled = !!alt.checked;
        const base = v970CleanBenefit({
          ...prev,
          id:r.dataset.draftBenefit,
          groupId:r.querySelector('[data-db-group]')?.value||'',
          memberId:r.querySelector('[data-db-member]')?.value||'',
          count:qty,
          case:!!r.querySelector('[data-db-case]')?.checked,
          part:r.querySelector('[data-db-part]')?.value?.trim()||'',
          note:r.querySelector('[data-db-note]')?.value||'',
          attachments:(()=>{ try{return JSON.parse(r.querySelector('[data-db-atts]')?.value||'[]').slice(0,1);}catch{return [];} })(),
          expenseEnabled:!!r.querySelector('[data-db-expense]')?.checked,
          unitPrice:Number(r.querySelector('[data-db-unit]')?.value)||0,
          recordKind:isCheki?'cheki':'activity',
          isCheki,
          nonCheki:!isCheki,
          activityLabel:isCheki?'チェキ':(r.querySelector('[data-v970-label]')?.value?.trim()||v970DefaultActivityLabel(type,{kind:'activity'})),
          unitLabel:isCheki?'枚':(r.querySelector('[data-v970-unit]')?.value?.trim()||v970DefaultUnitLabel(type,false,r.querySelector('[data-v970-label]')?.value||'')),
          workdayPerUnit:isCheki?0:(Number(r.querySelector('[data-v970-rate]')?.value)||0),
          tweet
        }, type);
        if(!base.memberId && !base.groupId && !base.case && !( !isCheki && qty>0)) return;
        if(isCheki){
          const n = Math.max(1,Math.min(30,Number(r.querySelector('[data-v92-bulk]')?.value)||1));
          for(let i=0;i<n;i++){
            out.push({...base,id:i===0?base.id:uid('b'),count:1,attachments:i===0?base.attachments:[],tweet:i===0?clone(tweet):(typeof v960CleanTweet==='function'?v960CleanTweet({},false):{description:'',comment:'',altEnabled:false})});
          }
        } else if(qty>0 || base.case){
          out.push({...base,count:qty});
        }
      });
      draftDetails().benefits = out;
    };

