    function v980RewriteEventBenefits(eventId){
      const e=G.state.events.find(x=>x.id===eventId),sheet=document.getElementById('modal');if(!e||!sheet)return;const p=[...sheet.querySelectorAll('.panel')].find(x=>['特典明細','ビンゴ明細'].includes(x.querySelector('h3')?.textContent?.trim()));if(!p)return;const bingo=v980IsBingoEvent(e);p.innerHTML=`<h3>${bingo?'ビンゴ明細':'特典明細'}</h3>${v980Arr(e.benefits).map(b=>{const cheki=v980IsCheki(b,e),name=memberById(b.memberId)?.name||groupById(resolveBenefitGroup(b,e))?.name||(cheki?'チェキ':'ビンゴ'),meta=cheki?`${Number(b.count)||0}枚${b.part?` ・ ${esc(b.part)}`:''}`:`ビンゴ ${Number(b.count)||0}口 ・ ${round2((Number(b.count)||0)*v980BingoRate(b)).toFixed(2)}Carat`;return `<div class="master-row"><div><b>${esc(name)}</b><small>${meta}${b.note?` / ${esc(String(b.note).slice(0,50))}`:''}</small></div>${cheki?`<button class="btn small" data-v980-open-cheki="${b.id}">開く</button>`:''}</div>`}).join('')||'<div class="hint">明細はありません</div>'}`;qsa('[data-v980-open-cheki]').forEach(btn=>{if(p.contains(btn))btn.onclick=()=>openChekiDetail(eventId,btn.dataset.v980OpenCheki)});
    }
    const _v980OpenEventDetail=openEventDetail;
    openEventDetail=function(id){const r=_v980OpenEventDetail(id);setTimeout(()=>v980RewriteEventBenefits(id),60);return r};

    /* ---------- Cheki Collection: search + 10/page + guaranteed close ---------- */
    function v980CollectionHay(r){const m=memberById(r.memberId)?.name||'',e=r.event?.name||'',src=r.owned?.source||'',note=r.owned?.note||r.benefit?.note||'',desc=r.owned?.description||r.benefit?.description||r.owned?.tweet?.description||r.benefit?.tweet?.description||'';return [m,e,r.date||'',r.acquisitionType||'',src,note,desc].join(' ').toLowerCase()}
    v92OpenCollection=function(){
      const all=v92AllChekis();G.v980CollectionQuery=String(G.v980CollectionQuery||'');G.v980CollectionPage=Math.max(1,Number(G.v980CollectionPage)||1);
      setModal(`<div class="modal-head"><div><div class="guide-kicker">CHEKI COLLECTION</div><h2>チェキコレクション</h2></div><button class="close-btn" id="v980CollectionClose">×</button></div><div class="panel"><div class="v980-collection-tools"><label class="field"><span>検索</span><input id="v980CollectionSearch" value="${esc(G.v980CollectionQuery)}" placeholder="メンバー・現場名・日付・入手方法など"></label><button class="btn primary small" id="v92AddOwned">＋ チェキを追加</button></div><div class="hint" id="v980CollectionCount"></div></div><div id="v980CollectionGrid"></div><div id="v980CollectionPager"></div><div class="modal-foot"><button class="btn" id="v980CollectionBottomClose">閉じる</button></div>`);
      const close=()=>closeModal();document.getElementById('v980CollectionClose').onclick=close;document.getElementById('v980CollectionBottomClose').onclick=close;document.getElementById('v92AddOwned').onclick=()=>v92OpenOwnedEditor();
      const draw=()=>{const q=String(document.getElementById('v980CollectionSearch')?.value||'').trim().toLowerCase();G.v980CollectionQuery=q;const rows=q?all.filter(r=>v980CollectionHay(r).includes(q)):all,pages=Math.max(1,Math.ceil(rows.length/V980_PAGE_SIZE));G.v980CollectionPage=Math.min(Math.max(1,G.v980CollectionPage),pages);const start=(G.v980CollectionPage-1)*V980_PAGE_SIZE,shown=rows.slice(start,start+V980_PAGE_SIZE);document.getElementById('v980CollectionCount').textContent=`${rows.length}件${q?`（全${all.length}件から検索）`:''} ・ 10件ずつ表示`;document.getElementById('v980CollectionGrid').innerHTML=`<div class="v92-cheki-grid">${shown.map(r=>{const m=memberById(r.memberId);return `<button class="v92-cheki-card" data-v980-cheki="${r.kind}|${r.kind==='event'?r.event.id:''}|${r.id}"><div class="v92-cheki-thumb">${v92ChekiThumb(r.attachmentId)}</div><b>${esc(m?.name||'メンバー未設定')}</b><small>${esc(r.date||'日付未設定')}</small><span class="v92-acq-badge">${esc(r.acquisitionType)}</span></button>`}).join('')||'<div class="empty">該当するチェキはありません</div>'}</div>`;document.getElementById('v980CollectionPager').innerHTML=rows.length?`<div class="v980-pager"><button class="btn small" id="v980PrevPage" ${G.v980CollectionPage<=1?'disabled':''}>‹ 前へ</button><span class="v980-page-label">${G.v980CollectionPage} / ${pages}</span><button class="btn small" id="v980NextPage" ${G.v980CollectionPage>=pages?'disabled':''}>次へ ›</button></div>`:'';qsa('[data-v980-cheki]').forEach(btn=>{if(!document.getElementById('v980CollectionGrid').contains(btn))return;btn.onclick=()=>{const [kind,eid,id]=btn.dataset.v980Cheki.split('|');if(kind==='event')openChekiDetail(eid,id);else v92OpenOwnedDetail(id)}});document.getElementById('v980PrevPage')?.addEventListener('click',()=>{G.v980CollectionPage--;draw();document.getElementById('modal').scrollTop=0});document.getElementById('v980NextPage')?.addEventListener('click',()=>{G.v980CollectionPage++;draw();document.getElementById('modal').scrollTop=0})};document.getElementById('v980CollectionSearch').oninput=()=>{G.v980CollectionPage=1;draw()};draw();
    };

    /* Unbound close buttons get the correct layer as a safety net. Existing custom handlers are preserved. */
    const _v980SetModal=setModal;setModal=function(html){const r=_v980SetModal(html);setTimeout(()=>qsa('#modal [data-close]').forEach(b=>{if(!b.onclick)b.onclick=closeModal}),0);return r};
    const _v980SetSubModal=setSubModal;setSubModal=function(html){const r=_v980SetSubModal(html);setTimeout(()=>qsa('#subModalSheet [data-close]').forEach(b=>{if(!b.onclick)b.onclick=closeSubModal}),0);return r};

    /* ---------- Cheki Tweet + X icon + manual mosaic ---------- */
    v93InlineTweetHTML=function(b){return v980IsCheki(b,{type:v980EventType()})?`<div class="v93-cheki-tools"><button class="btn small v980-x-btn" type="button" data-v980-draft-tweet>${v980XInner('チェキツイ')}</button></div>`:''};
    function v980RemoveTweetOverlay(){document.getElementById('v980TweetOverlay')?.remove();G.v980TweetCtx=null;G.v980Mosaic=null}
    function v980RecordShared(ctx,txt){const rec=ctx.kind==='event'?ctx.benefit:ctx.owned,t=v980TweetObj(rec),stamp=new Date().toISOString();rec.description=String(t.description||'');t.lastSharedText=String(txt||'');t.lastSharedAt=stamp;rec.tweet=t;if(ctx.kind==='event'&&ctx.event){const liveEvent=G.state.events.find(x=>x.id===ctx.event.id),liveBenefit=liveEvent?.benefits?.find(x=>x.id===rec.id);if(liveBenefit){liveBenefit.description=rec.description;liveBenefit.tweet=clone(t);liveEvent.updatedAt=stamp;persist();return}if(!ctx.draft){ctx.event.updatedAt=stamp;persist();return}}if(!ctx.draft)persist()}
    function v980RefreshMosaicStatus(){const s=document.getElementById('v980MosaicStatus'),p=document.getElementById('v980MosaicPreview');if(!s)return;const ok=!!G.v980Mosaic?.dataURL;s.textContent=ok?'モザイク版をチェキツイに使用します。GEMSの原本画像は変更しません。':'未加工。GEMSの原本画像をそのまま保持します。';s.classList.toggle('ready',ok);if(p&&ok)p.src=G.v980Mosaic.dataURL}
    v92OpenChekiTweet=function(ctx){
      const rec=ctx.kind==='event'?ctx.benefit:ctx.owned;if(!rec)return;const t=v980TweetObj(rec),isOwned=ctx.kind==='owned',aid=isOwned?ctx.owned.attachmentId:v980Arr(ctx.benefit.attachments)[0]||'';v980RemoveTweetOverlay();G.v980TweetCtx=ctx;
      const ov=document.createElement('div');ov.id='v980TweetOverlay';ov.className='v980-overlay';ov.innerHTML=`<div class="v980-sheet"><div class="modal-head"><div><div class="guide-kicker">CHEKI POST</div><h2>チェキツイ</h2></div><button class="close-btn" id="v980TweetClose">×</button></div><div class="v980-tweet-hero"><img src="${V980_X_ICON}" alt="X"><div><b>チェキツイ</b><small>投稿文と画像を整えて、共有先でXを選択</small></div></div><div class="panel"><label class="field"><span>チェキ説明文・会話</span><textarea id="v980TweetDesc" rows="4" placeholder="チェキの会話や説明を書こう">${esc(t.description||'')}</textarea></label><label class="field"><span>コメント（任意）</span><textarea id="v980TweetComment" rows="2" placeholder="本文に添えるコメント">${esc(t.comment||'')}</textarea></label>${isOwned?`<div class="form-grid"><label class="field"><span>日付（任意）</span><input id="v980TweetDate" type="date" value="${esc(t.manualDate||ctx.owned.acquiredDate||'')}"></label><label class="field"><span>イベント名（任意）</span><input id="v980TweetEvent" value="${esc(t.manualEvent||'')}"></label><label class="field full"><span>場所（任意）</span><input id="v980TweetPlace" value="${esc(t.manualPlace||'')}"></label></div>`:''}<label class="switch-row"><div class="text"><b>会話を画像ALTに入れる</b><small>ON時、本文の会話部分は「（会話ALT）」になります。</small></div><span class="switch"><input id="v980TweetAlt" type="checkbox" ${t.altEnabled?'checked':''}><i></i></span></label><div class="v92-tweet-preview" id="v980TweetPreview"></div>${aid?`<div class="v980-mosaic-card"><div class="share-top"><div><b>顔などを隠す</b><div class="hint">指で塗るモザイクはチェキツイ用だけ。GEMS上の原本は一切上書きしません。</div></div><button class="btn small" id="v980MosaicEdit">モザイク編集</button></div><div class="v92-cheki-thumb" style="max-width:210px;margin-top:8px"><img id="v980MosaicPreview" src="${esc(mediaURL(attachmentById(aid)?.path)||'')}" alt="チェキ"></div><div class="v980-mosaic-status" id="v980MosaicStatus"></div></div>`:'<div class="warning-box">画像がありません。画像を登録するとモザイク編集と画像付きチェキツイが使えます。</div>'}</div><div class="modal-foot"><button class="btn" id="v980TweetCopy">本文コピー</button><button class="btn v980-x-btn" id="v980TweetShare" ${aid?'':'disabled'}>${v980XInner('チェキツイ')}</button></div></div>`;document.body.appendChild(ov);
      const sync=()=>{t.description=document.getElementById('v980TweetDesc')?.value||'';t.comment=document.getElementById('v980TweetComment')?.value||'';t.altEnabled=!!document.getElementById('v980TweetAlt')?.checked;if(isOwned){t.manualDate=document.getElementById('v980TweetDate')?.value||'';t.manualEvent=document.getElementById('v980TweetEvent')?.value||'';t.manualPlace=document.getElementById('v980TweetPlace')?.value||''}rec.tweet=t;const txt=v92TweetText(ctx),preview=document.getElementById('v980TweetPreview');if(preview)preview.innerHTML=esc(txt).replace(/\n/g,'<br>');return txt};
      ['v980TweetDesc','v980TweetComment','v980TweetAlt','v980TweetDate','v980TweetEvent','v980TweetPlace'].forEach(id=>{const el=document.getElementById(id);if(el)el.oninput=sync});sync();v980RefreshMosaicStatus();document.getElementById('v980TweetClose').onclick=()=>{sync();if(!ctx.draft)persist();v980RemoveTweetOverlay()};document.getElementById('v980TweetCopy').onclick=()=>v93CopyText(sync());if(aid)document.getElementById('v980MosaicEdit').onclick=()=>{sync();G.v980Mosaic=null;native('cheki-mosaic-start',{id:aid,requestId:`mos_${Date.now()}`})};document.getElementById('v980TweetShare').onclick=()=>{const txt=sync();v980RecordShared(ctx,txt);const alt=t.altEnabled?String(t.description||''):'';if(G.v980Mosaic?.dataURL&&G.v980Mosaic.attachmentId===aid)native('share-cheki-mosaic',{text:txt,altText:alt});else native('share',{text:txt,attachmentIds:aid?[aid]:[],altText:alt});toast('チェキツイ内容を説明文へ記録しました')};
    };

    window.GEMS_GET_PENDING_MOSAIC=()=>G.v980Mosaic?.dataURL||'';
    window.GEMS_NATIVE_MOSAIC_START=function(payload,ctx={}){const dataURL=payload?.dataURL||payload;if(!dataURL)return toast('モザイク編集用画像を読み込めませんでした');v980OpenMosaicEditor(String(dataURL),ctx)};
    function v980OpenMosaicEditor(dataURL,ctx={}){
      document.getElementById('v980MosaicOverlay')?.remove();const ov=document.createElement('div');ov.id='v980MosaicOverlay';ov.className='v980-overlay v980-mosaic-overlay';ov.innerHTML=`<div class="v980-mosaic-sheet"><div class="modal-head" style="background:#111827;color:#fff"><h2>モザイク編集</h2><button class="close-btn" id="v980MosaicClose">×</button></div><div class="hint" style="color:#cbd5e1;margin-bottom:8px">隠したい場所を指でなぞってください。加工画像はチェキツイ時だけ使われ、GEMSの原本には保存されません。</div><div class="v980-mosaic-canvas-wrap"><canvas id="v980MosaicCanvas" class="v980-mosaic-canvas"></canvas></div><div class="v980-mosaic-mode"><button class="btn active" id="v980ModeMosaic">モザイクを塗る</button></div><div class="v980-mosaic-controls"><label>ブラシサイズ <input id="v980Brush" type="range" min="18" max="130" value="60"></label><label>モザイクの粗さ <input id="v980Block" type="range" min="6" max="36" value="18"></label></div><div class="v980-mosaic-actions"><button class="btn" id="v980MosaicUndo">1つ戻す</button><button class="btn" id="v980MosaicClear">全消し</button><button class="btn danger" id="v980MosaicCancel">キャンセル</button><button class="btn primary wide" id="v980MosaicUse">このモザイクでチェキツイ</button></div></div>`;document.body.appendChild(ov);
      const canvas=document.getElementById('v980MosaicCanvas'),c=canvas.getContext('2d'),base=document.createElement('canvas'),bc=base.getContext('2d'),tmp=document.createElement('canvas'),tc=tmp.getContext('2d'),img=new Image(),strokes=[];let mode='mosaic',stroke=null;
      const setMode=m=>{mode=m;document.getElementById('v980ModeMosaic').classList.toggle('active',m==='mosaic')};
      const point=ev=>{const r=canvas.getBoundingClientRect();return{x:(ev.clientX-r.left)*(canvas.width/r.width),y:(ev.clientY-r.top)*(canvas.height/r.height),scale:canvas.width/r.width}};
      function applyPoint(op,p){const rad=Math.max(4,op.size*p.scale/2),x=p.x,y=p.y,sx=Math.max(0,x-rad),sy=Math.max(0,y-rad),ex=Math.min(canvas.width,x+rad),ey=Math.min(canvas.height,y+rad),sw=Math.max(1,ex-sx),sh=Math.max(1,ey-sy);c.save();c.beginPath();c.arc(x,y,rad,0,Math.PI*2);c.clip();if(op.mode==='erase'){c.drawImage(base,sx,sy,sw,sh,sx,sy,sw,sh)}else{const block=Math.max(3,op.block*p.scale),tw=Math.max(1,Math.round(sw/block)),th=Math.max(1,Math.round(sh/block));tmp.width=tw;tmp.height=th;tc.imageSmoothingEnabled=false;tc.clearRect(0,0,tw,th);tc.drawImage(canvas,sx,sy,sw,sh,0,0,tw,th);c.imageSmoothingEnabled=false;c.drawImage(tmp,0,0,tw,th,sx,sy,sw,sh);c.imageSmoothingEnabled=true}c.restore()}
      function redraw(){c.clearRect(0,0,canvas.width,canvas.height);c.drawImage(base,0,0);for(const op of strokes)for(const p of op.points)applyPoint(op,p)}
      img.onload=()=>{canvas.width=img.naturalWidth;canvas.height=img.naturalHeight;base.width=img.naturalWidth;base.height=img.naturalHeight;bc.drawImage(img,0,0);c.drawImage(img,0,0)};img.src=dataURL;
      canvas.onpointerdown=ev=>{ev.preventDefault();canvas.setPointerCapture?.(ev.pointerId);stroke={mode,size:Number(document.getElementById('v980Brush').value),block:Number(document.getElementById('v980Block').value),points:[]};strokes.push(stroke);const p=point(ev);stroke.points.push(p);applyPoint(stroke,p)};
      canvas.onpointermove=ev=>{if(!stroke)return;ev.preventDefault();const p=point(ev),last=stroke.points.at(-1);if(last&&Math.hypot(p.x-last.x,p.y-last.y)<Math.max(2,stroke.size*p.scale*.12))return;stroke.points.push(p);applyPoint(stroke,p)};
      const end=()=>{stroke=null};canvas.onpointerup=end;canvas.onpointercancel=end;document.getElementById('v980ModeMosaic').onclick=()=>setMode('mosaic');document.getElementById('v980MosaicUndo').onclick=()=>{strokes.pop();redraw()};document.getElementById('v980MosaicClear').onclick=()=>{strokes.length=0;redraw()};const cancel=()=>ov.remove();document.getElementById('v980MosaicClose').onclick=cancel;document.getElementById('v980MosaicCancel').onclick=cancel;document.getElementById('v980MosaicUse').onclick=()=>{if(!canvas.width)return;G.v980Mosaic={attachmentId:String(ctx.id||''),dataURL:canvas.toDataURL('image/jpeg',.93)};ov.remove();v980RefreshMosaicStatus()};
    }

    /* Make Cheki Tweet prominent from Cheki detail and owned detail. */
    const _v980OpenChekiDetail=openChekiDetail;
    openChekiDetail=function(eventId,benefitId){const r=_v980OpenChekiDetail(eventId,benefitId);setTimeout(()=>{const e=G.state.events.find(x=>x.id===eventId),b=e?.benefits?.find(x=>x.id===benefitId);if(!e||!b||!v980IsCheki(b,e))return;const foot=document.querySelector('#subModalSheet .modal-foot');if(!foot)return;let x=document.getElementById('v92EventTweet')||document.getElementById('v980ChekiDetailTweet');if(!x){x=document.createElement('button');x.id='v980ChekiDetailTweet';foot.prepend(x)}x.className='btn v980-x-btn';x.innerHTML=v980XInner('チェキツイ');x.onclick=()=>v92OpenChekiTweet({kind:'event',event:e,benefit:b});const desc=b.description||b.tweet?.description||'';if(desc&&!document.getElementById('v980ChekiDescription')){const panels=[...document.querySelectorAll('#subModalSheet .panel')],imgPanel=panels.find(p=>p.querySelector('h3')?.textContent?.includes('チェキ画像')),p=document.createElement('div');p.id='v980ChekiDescription';p.className='panel v980-description-panel';p.innerHTML=`<h3>説明文</h3><div class="detail-text">${esc(desc)}</div>`;(imgPanel||foot).insertAdjacentElement('beforebegin',p)}},80);return r};
    const _v980OwnedDetail=v92OpenOwnedDetail;v92OpenOwnedDetail=function(id){const r=_v980OwnedDetail(id);setTimeout(()=>{const c=G.state.collectionChekis.find(x=>x.id===id),b=document.getElementById('v92OwnedTweet');if(c&&b){b.className='btn v980-x-btn';b.innerHTML=v980XInner('チェキツイ');b.onclick=()=>v92OpenChekiTweet({kind:'owned',owned:c})}},40);return r};

    /* ---------- Tutorial fixes ---------- */
    const _v980TourClear=v92TourClear;v92TourClear=function(){document.getElementById('v980WelcomeLock')?.remove();return _v980TourClear()};
    const _v980StartTutorial=v92StartTutorial;v92StartTutorial=function(){const r=_v980StartTutorial();setTimeout(()=>{const b=document.querySelector('.v92-tour-bubble');if(!b||!/WELCOME TO GEMS/.test(b.textContent||''))return;if(document.getElementById('v980WelcomeLock'))return;const lock=document.createElement('div');lock.id='v980WelcomeLock';lock.className='v980-welcome-lock';const bubble=b;document.body.insertBefore(lock,bubble)},150);return r};
    function v980TutorialFinalIntro(){v92TourClear();setModal(`<div class="modal-head"><div><div class="v92-tour-kicker">TUTORIAL FINISH</div><h2>最後の仕上げ</h2></div></div><div class="panel v980-final-card"><div class="gem">💎</div><h2>さぁ、GEMSで推し活をアップデートしよ？</h2><p>ここまででGEMSの基本操作はひと通り完了！<br>最後にキミの推しをおしえてね。</p><div class="v980-final-note">推しは後でも設定しなおせるよ。</div></div><div class="modal-foot"><button class="btn" id="v980FavLater">あとで設定する</button><button class="btn primary" id="v980FavGo">推しをおしえる</button></div>`);document.getElementById('v980FavGo').onclick=()=>{closeModal();v92OpenFavoriteSettings(true)};document.getElementById('v980FavLater').onclick=()=>{closeModal();setTimeout(v93TutorialFinishScreen,50)}}
    const _v980TutorialAnalysis=v93TutorialAnalysis;v93TutorialAnalysis=function(){const r=_v980TutorialAnalysis();setTimeout(()=>{const n=document.querySelector('.v92-tour-next');if(n){n.textContent='仕上げへ';n.onclick=()=>{v92TourClear();v980TutorialFinalIntro()}}},240);return r};
    const _v980FavoriteSettings=v92OpenFavoriteSettings;v92OpenFavoriteSettings=function(tutorial=false){const r=_v980FavoriteSettings(tutorial);if(tutorial)setTimeout(()=>{const modal=document.getElementById('modal');if(!modal)return;const h=modal.querySelector('.modal-head h2');if(h)h.textContent='最後にキミの推しをおしえてね';if(!document.getElementById('v980FavHint')){const p=document.createElement('div');p.id='v980FavHint';p.className='hint prominent-hint';p.innerHTML='<b>ここが最後！</b><br>推しは後でも設定しなおせるよ。まずは今の推しを選んでみてね。';modal.querySelector('.modal-head')?.insertAdjacentElement('afterend',p)}},20);return r};

    /* ---------- User-editable wording ---------- */
    function v980Overrides(){G.state.settings=G.state.settings||{};return (G.state.settings.wordingOverrides&&typeof G.state.settings.wordingOverrides==='object')?G.state.settings.wordingOverrides:{}}
    function v980ApplyWording(root=document.body){return}
    function v980OpenWordingEditor(){const current=v980Overrides(),rows=Object.entries(current).map(([from,to])=>({from,to}));if(!rows.length)rows.push({from:'',to:''});G.v980WordingDraft=rows;const render=()=>{document.getElementById('v980WordingRows').innerHTML=G.v980WordingDraft.map((r,i)=>`<div class="v980-wording-row" data-v980-word-row="${i}"><div class="form-grid"><label class="field"><span>元の文言（完全一致）</span><input data-v980-word-from value="${esc(r.from)}" placeholder="例：チェキ・特典明細"></label><label class="field"><span>表示する文言</span><input data-v980-word-to value="${esc(r.to)}" placeholder="例：特典を入力"></label></div><button class="btn danger small" data-v980-word-del>この置換を削除</button></div>`).join('');qsa('#v980WordingRows [data-v980-word-del]').forEach(b=>b.onclick=()=>{sync();G.v980WordingDraft.splice(Number(b.closest('[data-v980-word-row]').dataset.v980WordRow),1);if(!G.v980WordingDraft.length)G.v980WordingDraft.push({from:'',to:''});render()})};const sync=()=>qsa('#v980WordingRows [data-v980-word-row]').forEach(row=>{const i=Number(row.dataset.v980WordRow);G.v980WordingDraft[i]={from:row.querySelector('[data-v980-word-from]')?.value||'',to:row.querySelector('[data-v980-word-to]')?.value||''}});setModal(`<div id="v980WordingEditor"><div class="modal-head"><div><div class="guide-kicker">WORDING</div><h2>文言カスタマイズ</h2></div><button class="close-btn" id="v980WordingClose">×</button></div><div class="panel"><div class="hint">画面に表示される文言を「完全一致」で置き換えます。内部IDやデータ値は変更しないため、機能ロジックとは分離されています。</div><div class="v980-wording-actions" style="margin-top:10px"><button class="btn small" id="v980WordAdd">＋ 置換を追加</button><button class="btn small danger" id="v980WordClear">全て解除</button></div></div><div id="v980WordingRows"></div><div class="modal-foot"><button class="btn" id="v980WordingCancel">キャンセル</button><button class="btn primary" id="v980WordingSave">保存</button></div></div>`);render();const close=()=>{G.v980WordingDraft=null;closeModal()};document.getElementById('v980WordingClose').onclick=close;document.getElementById('v980WordingCancel').onclick=close;document.getElementById('v980WordAdd').onclick=()=>{sync();G.v980WordingDraft.push({from:'',to:''});render();document.getElementById('modal').scrollTop=document.getElementById('modal').scrollHeight};document.getElementById('v980WordClear').onclick=()=>{G.v980WordingDraft=[{from:'',to:''}];render()};document.getElementById('v980WordingSave').onclick=()=>{sync();const obj={};for(const r of G.v980WordingDraft){const f=String(r.from||'').trim(),t=String(r.to||'').trim();if(f&&t)obj[f]=t}G.state.settings.wordingOverrides=obj;persist();close();renderAll();setTimeout(()=>v980ApplyWording(document.body),20);toast('文言カスタマイズを保存しました')}}
