      qsa('[data-v991-seen]',box).forEach(x=>x.onchange=()=>{if(x.checked)selected.add(x.value);else selected.delete(x.value);x.closest('label')?.classList.toggle('active',x.checked)});
      document.getElementById('v991SeenFromRelated')?.addEventListener('click',()=>{G.v991SeenSelection=new Set(G.v960ParticipantSelection instanceof Set?[...G.v960ParticipantSelection]:[]);v991RenderSeenManager()});
      document.getElementById('v991SeenClear')?.addEventListener('click',()=>{G.v991SeenSelection=new Set();v991RenderSeenManager()});
