      if(V991_PHYSICAL_CONTACT_TYPES.has(e?.type))v991Arr(e?.benefits).forEach(b=>{if(b?.memberId&&Number(b?.count)>0)ids.add(b.memberId)});
      return [...ids].map(id=>{const m=memberById(id),c=memberColorFor(m);return m?`<span class="v960-participant-tag"><span class="v960-member-dot" ${c?`style="background:${esc(c.color)}"`:''}></span>${esc(m.name)}</span>`:''}).join('');
